window.HOEREN = {"1":[{"id":"h1","type":"Radiobeitrag","title":"Brauchen wir die Handschrift noch?","title_fa":"آیا هنوز به دست‌خط نیاز داریم؟","intro_fa":"یک گزارش رادیویی در برنامهٔ علمی صبحگاهی دربارهٔ اینکه نوشتن با دست در عصر دیجیتال چه نقشی دارد.","s":[{"de":"Herzlich willkommen zu unserer Reihe „Wissen am Morgen“, heute geht es um die Rolle der Handschrift im digitalen Zeitalter.","fa":"به مجموعه‌برنامهٔ «دانش صبحگاهی» خوش آمدید؛ امروز موضوع ما نقش دست‌خط در عصر دیجیتال است."},{"de":"Statt Heften liegen in vielen Klassenzimmern heute Tablets auf den Tischen.","fa":"امروزه در بسیاری از کلاس‌ها به‌جای دفتر، تبلت روی میزها قرار دارد."},{"de":"Lehrerinnen und Lehrer beklagen seit Jahren, dass viele Kinder nicht mehr flüssig mit der Hand schreiben können.","fa":"معلمان سال‌هاست گلایه می‌کنند که بسیاری از کودکان دیگر نمی‌توانند روان با دست بنویسند."},{"de":"Manche Fachleute fordern deshalb, dass die Schreibschrift wieder intensiver geübt wird.","fa":"به همین دلیل برخی از کارشناسان خواستار آن هستند که خط پیوسته دوباره با جدیت بیشتری تمرین شود."},{"de":"Andere halten dagegen, dass Kinder statt der Schreibschrift lieber früh das Tippen lernen sollten.","fa":"در مقابل، عده‌ای دیگر معتقدند که کودکان بهتر است به‌جای خط پیوسته، زودتر تایپ کردن را یاد بگیرند."},{"de":"Ihr Argument lautet: Im Beruf schreibt heute fast jeder auf der Tastatur.","fa":"استدلال آن‌ها این است: امروزه تقریباً همه در محیط کار با صفحه‌کلید می‌نویسند."},{"de":"Doch was sagt die Forschung dazu?","fa":"اما پژوهش‌ها در این باره چه می‌گویند؟"},{"de":"Neurowissenschaftler haben herausgefunden, dass beim Schreiben mit der Hand deutlich mehr Bereiche des Gehirns aktiv sind als beim Tippen.","fa":"دانشمندان علوم اعصاب دریافته‌اند که هنگام نوشتن با دست، بخش‌های بسیار بیشتری از مغز فعال هستند تا هنگام تایپ کردن."},{"de":"Denn jeder Buchstabe muss mit einer feinen Bewegung der Hand geformt werden.","fa":"زیرا هر حرف باید با حرکتی ظریف از دست شکل بگیرد."},{"de":"Beim Tippen dagegen drückt man immer nur eine Taste, egal welcher Buchstabe entsteht.","fa":"اما هنگام تایپ، همیشه فقط یک دکمه فشار داده می‌شود، فرقی نمی‌کند کدام حرف نوشته شود."},{"de":"Besonders interessant ist eine Studie mit Studierenden, die eine Vorlesung mitschreiben sollten.","fa":"به‌ویژه پژوهشی جالب است که روی دانشجویانی انجام شد که باید از یک کلاس درس یادداشت برمی‌داشتند."},{"de":"Während die Hälfte der Teilnehmer auf dem Laptop tippte, benutzten die anderen stattdessen Papier und Stift.","fa":"در حالی که نیمی از شرکت‌کنندگان با لپ‌تاپ تایپ می‌کردند، بقیه به‌جای آن از کاغذ و خودکار استفاده کردند."},{"de":"Die Laptopgruppe notierte zwar fast doppelt so viele Wörter, aber oft wörtlich und ohne nachzudenken.","fa":"گروه لپ‌تاپ تقریباً دو برابر کلمه یادداشت کرد، اما اغلب کلمه‌به‌کلمه و بدون فکر کردن."},{"de":"Die Handschriftgruppe musste dagegen auswählen und mit eigenen Worten zusammenfassen, weil sie langsamer war.","fa":"در مقابل، گروه دست‌نویس چون کندتر بود، مجبور بود انتخاب کند و مطالب را با کلمات خودش خلاصه کند."},{"de":"Bei einem Test eine Woche später schnitt diese Gruppe deutlich besser ab, vor allem bei Verständnisfragen.","fa":"در آزمونی که یک هفته بعد برگزار شد، این گروه نتیجهٔ بسیار بهتری گرفت، به‌ویژه در پرسش‌های درک مطلب."},{"de":"Wer mit der Hand notiert, verarbeitet die Informationen also schon beim Schreiben.","fa":"پس کسی که با دست یادداشت برمی‌دارد، اطلاعات را همان هنگام نوشتن پردازش می‌کند."},{"de":"Sollte man also in Vorlesungen ganz auf den Laptop verzichten?","fa":"پس آیا باید در کلاس‌های دانشگاه به‌کلی از لپ‌تاپ صرف‌نظر کرد؟"},{"de":"Ganz so einfach ist es nicht.","fa":"موضوع به این سادگی هم نیست."},{"de":"Wenn man zum Beispiel lange Zitate oder viele Zahlen genau festhalten muss, ist der Laptop durchaus praktisch.","fa":"برای مثال اگر لازم باشد نقل‌قول‌های طولانی یا اعداد زیادی را دقیق ثبت کنید، لپ‌تاپ واقعاً کاربردی است."},{"de":"Die meisten Fachleute empfehlen deshalb einen Methodenmix.","fa":"به همین دلیل بیشتر کارشناسان ترکیبی از روش‌ها را توصیه می‌کنند."},{"de":"Die Handschrift komplett aus dem Unterricht zu streichen, halten sie jedoch für einen schweren Fehler.","fa":"با این حال، حذف کامل دست‌خط از آموزش را اشتباهی بزرگ می‌دانند."},{"de":"Im zweiten Teil der Sendung erfahren Sie, wie Sie Ihre eigenen Notizen verbessern können.","fa":"در بخش دوم برنامه می‌شنوید که چگونه می‌توانید یادداشت‌های خودتان را بهتر کنید."}],"q":[{"q":"Worum geht es in dem Beitrag hauptsächlich?","opts":["Um die Rolle der Handschrift im digitalen Zeitalter.","Darum, wie man möglichst schnell tippen lernt.","Darum, dass Kinder keine Tablets mehr benutzen dürfen."],"a":0,"fa":"گوینده در ابتدا می‌گوید موضوع امروز «نقش دست‌خط در عصر دیجیتال» است."},{"q":"Was beklagen viele Lehrkräfte?","opts":["Dass Kinder zu langsam tippen.","Dass Tablets in der Schule zu teuer sind.","Dass viele Kinder nicht mehr flüssig mit der Hand schreiben."],"a":2,"fa":"گفته شد معلمان گلایه می‌کنند که بسیاری از کودکان دیگر روان با دست نمی‌نویسند."},{"q":"Warum sind beim Schreiben mit der Hand mehr Bereiche des Gehirns aktiv?","opts":["Weil jeder Buchstabe mit einer feinen Bewegung geformt wird.","Weil man immer nur eine Taste drückt.","Weil man mit der Hand schneller schreibt."],"a":0,"fa":"دلیل این است که «هر حرف باید با حرکتی ظریف از دست شکل بگیرد»؛ فشار دادن یک دکمه مربوط به تایپ است."},{"q":"Was stimmt über die Laptopgruppe in der Studie?","opts":["Sie schnitt beim Test eine Woche später besser ab.","Sie notierte weniger Wörter als die andere Gruppe.","Sie notierte mehr Wörter, aber oft wörtlich."],"a":2,"fa":"گروه لپ‌تاپ تقریباً دو برابر کلمه نوشت، اما اغلب کلمه‌به‌کلمه و بی‌فکر؛ گروه دست‌نویس در آزمون بهتر بود."},{"q":"Warum fasste die Handschriftgruppe die Inhalte mit eigenen Worten zusammen?","opts":["Weil der Professor es verlangt hatte.","Weil sie keinen Laptop besaß.","Weil sie langsamer schrieb und auswählen musste."],"a":2,"fa":"گفته شد این گروه «چون کندتر بود» مجبور بود انتخاب و خلاصه کند."},{"q":"Was empfehlen die meisten Fachleute am Ende?","opts":["Nur noch mit der Hand zu schreiben.","Einen Mix aus verschiedenen Methoden.","Die Handschrift aus dem Unterricht zu streichen."],"a":1,"fa":"در پایان گفته شد بیشتر کارشناسان «ترکیبی از روش‌ها» را توصیه می‌کنند و حذف دست‌خط را اشتباه می‌دانند."}]},{"id":"h2","type":"Vortrag","title":"Fehlerkultur beim Sprachenlernen","title_fa":"فرهنگ برخورد با اشتباه در یادگیری زبان","intro_fa":"یک استاد زبان‌شناسی در سخنرانی خود در دانشگاه توضیح می‌دهد اشتباه در یادگیری زبان چه معنایی دارد و چگونه باید با آن برخورد کرد.","s":[{"de":"Guten Tag, meine Damen und Herren, mein Name ist Daniel Brenner, und ich spreche heute über Fehlerkultur beim Sprachenlernen.","fa":"روز بخیر خانم‌ها و آقایان، من دانیل برنر هستم و امروز دربارهٔ فرهنگ برخورد با اشتباه در یادگیری زبان صحبت می‌کنم."},{"de":"Mit Fehlerkultur meint man die Art und Weise, wie eine Gruppe oder eine Institution mit Fehlern umgeht.","fa":"منظور از فرهنگ برخورد با اشتباه، شیوه‌ای است که یک گروه یا یک نهاد با اشتباه‌ها رفتار می‌کند."},{"de":"Mein Vortrag besteht aus drei Teilen.","fa":"سخنرانی من از سه بخش تشکیل شده است."},{"de":"Zuerst frage ich, warum Fehler beim Lernen überhaupt entstehen.","fa":"اول این پرسش را مطرح می‌کنم که اصلاً چرا هنگام یادگیری اشتباه پیش می‌آید."},{"de":"Danach geht es um die Frage, ob und wie man Fehler korrigieren sollte.","fa":"سپس به این پرسش می‌پردازم که آیا و چگونه باید اشتباه‌ها را تصحیح کرد."},{"de":"Zum Schluss möchte ich zeigen, wie Lernende ihre Angst vor Fehlern verlieren können.","fa":"در پایان می‌خواهم نشان دهم که زبان‌آموزان چگونه می‌توانند ترسشان از اشتباه را کنار بگذارند."},{"de":"Die Sprachwissenschaft beschäftigt sich schon seit über fünfzig Jahren mit den Fehlern von Lernenden.","fa":"زبان‌شناسی بیش از پنجاه سال است که به اشتباه‌های زبان‌آموزان می‌پردازد."},{"de":"Man hat dabei erkannt, dass Fehler kein Zeichen von Faulheit sind, sondern ein normaler Teil des Lernprozesses.","fa":"در این مدت معلوم شده که اشتباه نشانهٔ تنبلی نیست، بلکه بخشی عادی از فرایند یادگیری است."},{"de":"Wer zum Beispiel „ich habe gegeht“ sagt, wendet eine gelernte Regel an, auch wenn sie hier nicht passt.","fa":"برای نمونه کسی که می‌گوید «ich habe gegeht»، قاعده‌ای را که یاد گرفته به کار می‌برد، هرچند اینجا مناسب نیست."},{"de":"Fehler zeigen uns also, welche Hypothesen ein Lernender über die neue Sprache bildet.","fa":"پس اشتباه‌ها به ما نشان می‌دهند که زبان‌آموز چه فرضیه‌هایی دربارهٔ زبان جدید می‌سازد."},{"de":"Problematisch wird es allerdings, wenn ein Fehler fossilisiert ist.","fa":"اما وقتی یک اشتباه «فسیل» یا تثبیت شده باشد، مشکل‌ساز می‌شود."},{"de":"Das bedeutet, dass man ihn immer wieder macht, obwohl man die richtige Form eigentlich kennt.","fa":"یعنی آدم آن را بارها تکرار می‌کند، با اینکه در اصل شکل درست را می‌داند."},{"de":"Solche Fehler sind leider sehr schwer zu korrigieren, selbst wenn man sich stark darauf konzentriert.","fa":"متأسفانه تصحیح چنین اشتباه‌هایی بسیار دشوار است، حتی اگر آدم حسابی روی آن تمرکز کند."},{"de":"Manche Lehrkräfte sagen: Wenn man die Lernenden trotzdem versteht, muss man nichts korrigieren.","fa":"برخی از معلمان می‌گویند: اگر با وجود اشتباه حرف زبان‌آموز را می‌فهمیم، لازم نیست چیزی را تصحیح کنیم."},{"de":"Dieser Ansicht stimme ich nur teilweise zu.","fa":"من فقط تا حدی با این دیدگاه موافقم."},{"de":"Zwar ist Kommunikation das wichtigste Ziel, trotzdem brauchen Lernende Rückmeldungen, sonst setzen sich falsche Formen fest.","fa":"درست است که ارتباط مهم‌ترین هدف است، اما با این حال زبان‌آموزان به بازخورد نیاز دارند، وگرنه شکل‌های نادرست تثبیت می‌شوند."},{"de":"Entscheidend ist, wie korrigiert wird: freundlich, gezielt und nicht bei jedem kleinen Fehler.","fa":"نکتهٔ تعیین‌کننده شیوهٔ تصحیح است: دوستانه، هدفمند و نه برای هر اشتباه کوچک."},{"de":"Damit komme ich zum letzten Punkt, der Angst vor Fehlern.","fa":"با این توضیح به نکتهٔ آخر می‌رسم، یعنی ترس از اشتباه."},{"de":"Viele Erwachsene sprechen im Kurs kaum, weil sie sich für ihre Fehler schämen.","fa":"بسیاری از بزرگسالان در کلاس به‌ندرت حرف می‌زنند، چون از اشتباه‌هایشان خجالت می‌کشند."},{"de":"Wenn sie aber verstehen, dass Fehler beim Lernen nützlich sind, werden sie mutiger.","fa":"اما وقتی بفهمند که اشتباه در یادگیری مفید است، جسورتر می‌شوند."},{"de":"In einer Gruppe darf man auch einmal gemeinsam über einen lustigen Fehler lachen, solange niemand ausgelacht wird.","fa":"در یک گروه می‌شود گاهی با هم به یک اشتباه خنده‌دار خندید، به شرطی که کسی مسخره نشود."},{"de":"Nach einer kurzen Pause stelle ich Ihnen konkrete Methoden für die mündliche Korrektur vor.","fa":"پس از یک استراحت کوتاه، روش‌های مشخصی را برای تصحیح شفاهی به شما معرفی می‌کنم."}],"q":[{"q":"Was bedeutet der Begriff „Fehlerkultur“?","opts":["Typische Fehler von Menschen aus anderen Kulturen.","Die Art, wie eine Gruppe oder Institution mit Fehlern umgeht.","Eine Liste der häufigsten Grammatikfehler."],"a":1,"fa":"سخنران توضیح داد منظور «شیوه‌ای است که یک گروه یا نهاد با اشتباه‌ها رفتار می‌کند»."},{"q":"Seit wann beschäftigt sich die Sprachwissenschaft mit Fehlern von Lernenden?","opts":["Seit über fünfzig Jahren.","Seit etwa zehn Jahren.","Erst seit wenigen Jahren."],"a":0,"fa":"گفته شد زبان‌شناسی «بیش از پنجاه سال» است که به این موضوع می‌پردازد."},{"q":"Was zeigt ein Fehler wie „ich habe gegeht“?","opts":["Dass der Lernende nie Grammatik gelernt hat.","Dass der Lernende faul ist.","Dass der Lernende eine gelernte Regel anwendet."],"a":2,"fa":"طبق سخنرانی، زبان‌آموز قاعده‌ای را که یاد گرفته به کار می‌برد؛ اشتباه نشانهٔ تنبلی نیست."},{"q":"Was ist ein fossilisierter Fehler?","opts":["Ein Fehler, der nur in alten Texten vorkommt.","Ein Fehler, den man wiederholt, obwohl man die richtige Form kennt.","Ein Fehler, den man nur ein einziges Mal macht."],"a":1,"fa":"اشتباه تثبیت‌شده یعنی آدم آن را تکرار می‌کند «با اینکه شکل درست را می‌داند»."},{"q":"Wie steht der Redner zu der Meinung, man müsse nicht korrigieren, wenn man die Lernenden versteht?","opts":["Er meint, Kommunikation sei unwichtig.","Er stimmt voll und ganz zu.","Er stimmt nur teilweise zu."],"a":2,"fa":"او گفت «فقط تا حدی با این دیدگاه موافقم»، چون زبان‌آموزان به بازخورد نیاز دارند."},{"q":"Worüber spricht der Redner nach der Pause?","opts":["Über schriftliche Prüfungen.","Über Methoden für die mündliche Korrektur.","Über die Geschichte der Sprachwissenschaft."],"a":1,"fa":"در جملهٔ آخر گفت پس از استراحت «روش‌های تصحیح شفاهی» را معرفی می‌کند."}]},{"id":"h3","type":"Podcast-Folge","title":"Allein oder in der Lerngruppe?","title_fa":"تنها یا در گروه مطالعه؟","intro_fa":"گویندهٔ یک پادکست آموزشی برای دانشجویان توضیح می‌دهد که مطالعهٔ گروهی و مطالعهٔ فردی چه مزایا و معایبی دارند.","s":[{"de":"Hallo und willkommen zu einer neuen Folge von „Besser lernen“, dem Podcast für alle, die sich gerade auf eine Prüfung vorbereiten.","fa":"سلام و خوش آمدید به قسمت تازهٔ «بهتر یاد بگیریم»، پادکستی برای همهٔ کسانی که الان برای امتحانی آماده می‌شوند."},{"de":"Heute geht es um eine Frage, die mir viele von euch im Forum gestellt haben: Lernt man besser allein oder in einer Lerngruppe?","fa":"امروز دربارهٔ پرسشی صحبت می‌کنیم که خیلی از شما در انجمن از من پرسیده‌اید: آیا تنها بهتر یاد می‌گیریم یا در گروه مطالعه؟"},{"de":"Lange Zeit hat man in Ratgebern gelesen, dass man zuerst seinen Lerntyp herausfinden muss.","fa":"مدت‌ها در کتاب‌های راهنما می‌خواندیم که اول باید تیپ یادگیری خودمان را پیدا کنیم."},{"de":"Angeblich lernen visuelle Typen am besten mit Bildern, auditive Typen dagegen durch Hören.","fa":"ظاهراً تیپ‌های دیداری با تصویر بهتر یاد می‌گیرند و تیپ‌های شنیداری با شنیدن."},{"de":"Dieses Konzept gilt in der Forschung heute jedoch als veraltet, weil es dafür kaum Belege gibt.","fa":"اما این مفهوم امروزه در پژوهش منسوخ به شمار می‌رود، چون شواهد چندانی برای آن وجود ندارد."},{"de":"Es sagt höchstens etwas darüber aus, wie man Informationen aufnimmt, aber nicht, wie man sie wirklich verarbeitet.","fa":"این مفهوم حداکثر چیزی دربارهٔ نحوهٔ دریافت اطلاعات می‌گوید، نه اینکه واقعاً چگونه آن‌ها را پردازش می‌کنیم."},{"de":"Für unsere Frage ist eine Umfrage unter rund 800 Studierenden interessant.","fa":"برای پرسش ما، نظرسنجی‌ای میان حدود ۸۰۰ دانشجو جالب است."},{"de":"Sie hat gezeigt, dass etwa sechzig Prozent regelmäßig in Gruppen lernen.","fa":"این نظرسنجی نشان داد که حدود شصت درصد آن‌ها به‌طور منظم گروهی درس می‌خوانند."},{"de":"Als Hauptgrund nannten die meisten, dass man Fragen sofort klären kann.","fa":"بیشترشان دلیل اصلی را این دانستند که می‌شود پرسش‌ها را فوراً روشن کرد."},{"de":"Außerdem bleiben viele leichter motiviert, da sie sich den anderen gegenüber verpflichtet fühlen.","fa":"علاوه بر این، بسیاری راحت‌تر انگیزه‌شان را حفظ می‌کنند، چون در برابر دیگران احساس تعهد دارند."},{"de":"Wer den Stoff anderen erklären muss, durchdenkt ihn zudem gründlicher.","fa":"کسی که باید مطلب را برای دیگران توضیح دهد، آن را عمیق‌تر هم بررسی می‌کند."},{"de":"Es gibt allerdings auch Nachteile.","fa":"البته معایبی هم وجود دارد."},{"de":"Obwohl man sich zum Lernen trifft, wird in vielen Gruppen mehr geplaudert als gearbeitet.","fa":"با اینکه برای درس خواندن دور هم جمع می‌شوند، در بسیاری از گروه‌ها بیشتر گپ می‌زنند تا کار کنند."},{"de":"Und wenn die Mitglieder auf einem sehr unterschiedlichen Niveau sind, profitieren die Stärkeren oft kaum.","fa":"و اگر سطح اعضا خیلی با هم فرق داشته باشد، افراد قوی‌تر معمولاً سود چندانی نمی‌برند."},{"de":"Allein zu lernen hat dagegen den Vorteil, dass man sein eigenes Tempo bestimmen kann.","fa":"در مقابل، تنها درس خواندن این مزیت را دارد که آدم سرعت خودش را تعیین می‌کند."},{"de":"Wegen der fehlenden Kontrolle schieben Einzellerner wichtige Aufgaben aber gern auf.","fa":"اما کسانی که تنها درس می‌خوانند، به دلیل نبودِ نظارت، کارهای مهم را اغلب به تعویق می‌اندازند."},{"de":"Mein Tipp lautet deshalb: Entweder ihr kombiniert beides, oder ihr entscheidet je nach Aufgabe.","fa":"برای همین توصیهٔ من این است: یا هر دو را با هم ترکیب کنید، یا بسته به نوع کار تصمیم بگیرید."},{"de":"Neue Vokabeln und Regeln kann man gut allein wiederholen, zum Beispiel mit Karteikarten.","fa":"واژه‌ها و قاعده‌های جدید را می‌شود به‌خوبی تنها مرور کرد، مثلاً با فلش‌کارت."},{"de":"Schwierige Texte oder Diskussionsthemen bespricht man dagegen besser zu dritt oder zu viert.","fa":"اما متن‌های دشوار یا موضوعات بحث‌برانگیز را بهتر است سه‌چهار نفری بررسی کرد."},{"de":"Wichtig ist in beiden Fällen ein klarer Lernplan mit festen Zeiten.","fa":"در هر دو حالت، داشتن یک برنامهٔ مطالعهٔ روشن با زمان‌های ثابت مهم است."},{"de":"Schreibt mir gern in den Kommentaren, welche Lernerfahrungen ihr gemacht habt.","fa":"خوشحال می‌شوم در بخش نظرها برایم بنویسید چه تجربه‌هایی در یادگیری داشته‌اید."},{"de":"In der nächsten Folge geht es dann um Lerntechniken für das Langzeitgedächtnis.","fa":"در قسمت بعد دربارهٔ تکنیک‌های یادگیری برای حافظهٔ بلندمدت صحبت می‌کنیم."}],"q":[{"q":"Warum gilt das Konzept „Lerntyp“ heute als veraltet?","opts":["Weil es nur für Kinder entwickelt wurde.","Weil es zu kompliziert für Studierende ist.","Weil es dafür kaum wissenschaftliche Belege gibt."],"a":2,"fa":"گوینده گفت این مفهوم منسوخ است «چون شواهد چندانی برای آن وجود ندارد»."},{"q":"Wie viele der befragten Studierenden lernen regelmäßig in Gruppen?","opts":["Fast alle.","Etwa sechzig Prozent.","Etwa zwanzig Prozent."],"a":1,"fa":"طبق نظرسنجی، حدود شصت درصد به‌طور منظم گروهی درس می‌خوانند."},{"q":"Was war der wichtigste Grund für das Lernen in der Gruppe?","opts":["Man kann längere Pausen machen.","Man kann Fragen sofort klären.","Man spart Geld für Bücher."],"a":1,"fa":"دلیل اصلی این بود که «می‌شود پرسش‌ها را فوراً روشن کرد»."},{"q":"Welchen Nachteil von Lerngruppen nennt der Sprecher?","opts":["Man bekommt keine Lernmaterialien.","Die Treffen sind zu teuer.","Oft wird mehr geplaudert als gearbeitet."],"a":2,"fa":"گفته شد در بسیاری از گروه‌ها «بیشتر گپ می‌زنند تا کار کنند»."},{"q":"Welches Problem haben viele, die allein lernen?","opts":["Sie schieben wichtige Aufgaben gern auf.","Sie haben zu viele Fragen.","Sie können ihr Tempo nicht selbst bestimmen."],"a":0,"fa":"به دلیل نبودِ نظارت، تنها‌خوان‌ها کارهای مهم را به تعویق می‌اندازند؛ تعیین سرعت شخصی مزیت آن‌هاست."},{"q":"Was empfiehlt der Sprecher für schwierige Texte?","opts":["Sie allein mit Karteikarten zu lernen.","Sie gar nicht zu lesen.","Sie in einer kleinen Gruppe zu besprechen."],"a":2,"fa":"او گفت متن‌های دشوار را «بهتر است سه‌چهار نفری» بررسی کرد؛ فلش‌کارت برای واژه‌هاست."}]}],"10":[{"id":"h1","type":"Erklärvideo-Text","title":"E-Mails an Dozierende richtig schreiben","title_fa":"نوشتن درست ایمیل به استادان","intro_fa":"گوینده‌ی یک ویدئوی آموزشی برای دانشجویان سال اول توضیح می‌دهد که چطور باید ایمیلی مؤدبانه و رسمی به استاد نوشت.","s":[{"de":"Hallo zusammen und willkommen zu unserem Erklärvideo für Studienanfänger.","fa":"سلام به همه و به ویدئوی آموزشی ما برای دانشجویان تازه‌وارد خوش آمدید."},{"de":"Heute geht es um eine Situation, die fast alle kennen: Man muss eine E-Mail an eine Dozentin oder einen Dozenten schreiben.","fa":"امروز موضوع موقعیتی است که تقریباً همه می‌شناسند: باید به یک استاد ایمیل بنویسید."},{"de":"Viele Studierende kommunizieren privat fast nur über Messenger, wo ein lockerer Ton und Emojis völlig normal sind.","fa":"بسیاری از دانشجویان در زندگی شخصی تقریباً فقط از طریق پیام‌رسان‌ها ارتباط برقرار می‌کنند، جایی که لحن خودمانی و ایموجی کاملاً عادی است."},{"de":"In einer E-Mail an die Uni wirkt dieser Stil aber schnell unangemessen.","fa":"اما در ایمیلی به دانشگاه، این سبک زود نامناسب به نظر می‌رسد."},{"de":"Stellt euch vor, eure Professorin bekommt eine Nachricht ohne Betreff, die nur mit „Hey“ beginnt.","fa":"تصور کنید استادتان پیامی بدون موضوع دریافت کند که فقط با «هی» شروع می‌شود."},{"de":"Wenn ihr so eine E-Mail bekommen würdet, würdet ihr den Absender wahrscheinlich auch nicht besonders ernst nehmen.","fa":"اگر خودتان چنین ایمیلی دریافت می‌کردید، احتمالاً فرستنده را چندان جدی نمی‌گرفتید."},{"de":"Deshalb kommen hier ein paar Tipps.","fa":"برای همین، اینجا چند توصیه داریم."},{"de":"Erstens: Schreibt immer eine klare Betreffzeile, zum Beispiel „Frage zur Gliederung meiner Hausarbeit“.","fa":"اول: همیشه یک خط موضوع روشن بنویسید، مثلاً «سؤال درباره‌ی ساختار مقاله‌ی پایان ترمم»."},{"de":"Zweitens: Verwendet eine formelle Anrede wie „Sehr geehrte Frau Professorin Weber“ oder zumindest „Liebe Frau Weber“.","fa":"دوم: از خطاب رسمی استفاده کنید، مثل «خانم پروفسور وبر محترم» یا دست‌کم «خانم وبر عزیز»."},{"de":"Drittens: Stellt euch kurz vor und nennt den Namen des Seminars, denn Dozierende betreuen oft mehrere hundert Studierende.","fa":"سوم: خودتان را کوتاه معرفی کنید و نام کلاس را بگویید، چون استادان اغلب چند صد دانشجو دارند."},{"de":"Viertens: Formuliert euer Anliegen höflich und kurz, ohne umgangssprachliche Ausdrücke und ohne Emojis.","fa":"چهارم: درخواستتان را مؤدبانه و کوتاه بنویسید، بدون اصطلاحات محاوره‌ای و بدون ایموجی."},{"de":"Das gilt besonders, wenn ihr eine Bitte habt, zum Beispiel weil ihr die Abgabe einer Hausarbeit nicht rechtzeitig schafft.","fa":"این به‌خصوص وقتی مهم است که خواهشی دارید، مثلاً چون نمی‌توانید مقاله‌ی پایان ترم را به‌موقع تحویل دهید."},{"de":"Statt einer Forderung wie „Ich brauche mehr Zeit“ schreibt ihr besser: „Wäre es möglich, die Frist um eine Woche zu verlängern?“","fa":"به جای یک مطالبه مثل «به وقت بیشتری نیاز دارم»، بهتر است بنویسید: «آیا امکان دارد مهلت را یک هفته تمدید کنید؟»"},{"de":"Nennt auch einen nachvollziehbaren Grund, zum Beispiel eine Krankheit, und bietet an, ein ärztliches Attest nachzureichen.","fa":"یک دلیل قابل‌فهم هم بیاورید، مثلاً بیماری، و پیشنهاد کنید که گواهی پزشکی را بعداً تحویل بدهید."},{"de":"Fünftens: Beendet die E-Mail mit einer Standardformel wie „Mit freundlichen Grüßen“ und eurem vollständigen Namen.","fa":"پنجم: ایمیل را با یک عبارت استاندارد مثل «با احترام» و نام کاملتان تمام کنید."},{"de":"Lest die Nachricht vor dem Absenden noch einmal durch, denn Tippfehler wirken nachlässig.","fa":"پیش از فرستادن، پیام را یک بار دیگر بخوانید، چون غلط‌های تایپی نشانه‌ی بی‌دقتی به نظر می‌رسند."},{"de":"Und schreibt nicht erst in letzter Minute, denn unter Zeitdruck passieren die meisten Fehler.","fa":"و نامه را دقیقه‌ی آخر ننویسید، چون بیشتر اشتباه‌ها زیر فشار وقت پیش می‌آید."},{"de":"Viele ältere Studierende sagen: Hätten wir diese Regeln schon im ersten Semester gekannt, wäre uns manche peinliche Situation erspart geblieben.","fa":"بسیاری از دانشجویان سال‌بالایی می‌گویند: اگر این قواعد را از همان ترم اول می‌دانستیم، از بعضی موقعیت‌های خجالت‌آور در امان می‌ماندیم."},{"de":"Übrigens: Wenn die Dozentin nach einer Woche nicht antwortet, dürft ihr ruhig noch einmal freundlich nachfragen.","fa":"راستی: اگر استاد بعد از یک هفته جواب نداد، می‌توانید با خیال راحت یک بار دیگر مؤدبانه پیگیری کنید."},{"de":"Im nächsten Video zeigen wir euch, wie man sich angemessen beschwert, ohne unhöflich zu werden.","fa":"در ویدئوی بعدی به شما نشان می‌دهیم که چطور می‌شود به‌شکلی مناسب شکایت کرد، بی‌آنکه بی‌ادب شد."},{"de":"Bis dann und viel Erfolg im Studium!","fa":"تا آن موقع، در تحصیلتان موفق باشید!"}],"q":[{"q":"Für wen ist das Erklärvideo gedacht?","opts":["für Professorinnen und Professoren","für Schülerinnen und Schüler","für Studienanfänger"],"a":2,"fa":"گوینده در آغاز می‌گوید این ویدئو برای دانشجویان تازه‌وارد است."},{"q":"Was sollte in der Betreffzeile stehen?","opts":["ein freundlicher Gruß","ein klares Thema der E-Mail","nur der eigene Name"],"a":1,"fa":"توصیه‌ی اول این است که همیشه یک خط موضوع روشن بنویسید، مثلاً «سؤال درباره‌ی ساختار مقاله»."},{"q":"Warum soll man den Namen des Seminars nennen?","opts":["Weil Dozierende sehr viele Studierende betreuen.","Weil es eine Vorschrift der Uni ist.","Weil die E-Mail sonst gelöscht wird."],"a":0,"fa":"دلیلش این است که استادان اغلب چند صد دانشجو دارند."},{"q":"Wie sollte man um eine Fristverlängerung bitten?","opts":["mit einer höflichen Frage","mit einer klaren Forderung","am besten gar nicht"],"a":0,"fa":"به جای مطالبه‌ای مثل «به وقت بیشتری نیاز دارم» بهتر است مؤدبانه بپرسید: «آیا امکان دارد…؟»"},{"q":"Was soll man vor dem Absenden tun?","opts":["ein paar Emojis hinzufügen","die E-Mail an Freunde schicken","die Nachricht noch einmal lesen"],"a":2,"fa":"گوینده می‌گوید پیش از فرستادن، پیام را یک بار دیگر بخوانید، چون غلط تایپی بی‌دقتی نشان می‌دهد."},{"q":"Was darf man tun, wenn nach einer Woche keine Antwort kommt?","opts":["freundlich nachfragen","die Hausarbeit nicht abgeben","sich sofort beschweren"],"a":0,"fa":"اگر استاد بعد از یک هفته جواب نداد، می‌توان یک بار دیگر مؤدبانه پیگیری کرد."}]},{"id":"h2","type":"Vortrag","title":"Interkulturelle Kompetenz – eine Schlüsselqualifikation","title_fa":"توانش میان‌فرهنگی؛ یک مهارت کلیدی","intro_fa":"یک مشاور سازمانی در یک همایش منابع انسانی درباره‌ی اهمیت توانش میان‌فرهنگی سخنرانی می‌کند و نمونه‌ای از کار خودش می‌آورد.","s":[{"de":"Sehr geehrte Damen und Herren, ich freue mich, heute auf dieser Personalkonferenz über interkulturelle Kompetenz sprechen zu dürfen.","fa":"خانم‌ها و آقایان محترم، خوشحالم که امروز در این همایش منابع انسانی می‌توانم درباره‌ی توانش میان‌فرهنگی صحبت کنم."},{"de":"In einer globalisierten Arbeitswelt gilt sie heute als eine der wichtigsten Schlüsselqualifikationen.","fa":"در دنیای کار جهانی‌شده، امروزه این توانش یکی از مهم‌ترین مهارت‌های کلیدی به شمار می‌رود."},{"de":"Doch was versteht man eigentlich darunter?","fa":"اما اصلاً منظور از آن چیست؟"},{"de":"Interkulturelle Kompetenz bedeutet, mit Menschen aus anderen Kulturen erfolgreich zu kommunizieren und zu kooperieren.","fa":"توانش میان‌فرهنگی یعنی بتوانیم با آدم‌هایی از فرهنگ‌های دیگر با موفقیت ارتباط برقرار کنیم و همکاری کنیم."},{"de":"Dazu gehört, sich auf andere Gewohnheiten einzulassen und die eigenen nicht für selbstverständlich zu halten.","fa":"بخشی از آن این است که با عادت‌های دیگر کنار بیاییم و عادت‌های خودمان را بدیهی ندانیم."},{"de":"Ich möchte Ihnen das an einem Beispiel aus meiner Beratungspraxis zeigen.","fa":"می‌خواهم این را با مثالی از کار مشاوره‌ام به شما نشان دهم."},{"de":"Vor einigen Jahren kam es zur Fusion eines deutschen Maschinenbauunternehmens mit einer Firma aus Japan.","fa":"چند سال پیش، یک شرکت ماشین‌سازی آلمانی با یک شرکت ژاپنی ادغام شد."},{"de":"Schon nach wenigen Monaten gab es große Probleme in der Zusammenarbeit.","fa":"فقط پس از چند ماه، مشکلات بزرگی در همکاری پیش آمد."},{"de":"Die deutschen Manager legten Wert auf direkte Kritik und schnelle Entscheidungen in Meetings.","fa":"مدیران آلمانی برای انتقاد مستقیم و تصمیم‌گیری سریع در جلسه‌ها اهمیت قائل بودند."},{"de":"Die japanischen Kollegen empfanden diese Direktheit als unhöflich und stimmten Entscheidungen lieber vorher in kleinen Gesprächen ab.","fa":"همکاران ژاپنی این رک‌گویی را بی‌ادبانه می‌دانستند و ترجیح می‌دادند تصمیم‌ها را از قبل در گفت‌وگوهای کوچک هماهنگ کنند."},{"de":"Es stellte sich heraus, dass beide Seiten völlig unterschiedliche Vorstellungen von Führungskultur hatten.","fa":"معلوم شد که دو طرف تصورهای کاملاً متفاوتی از فرهنگ مدیریت داشتند."},{"de":"Wäre das Management besser vorbereitet gewesen, hätte man viele Konflikte vermeiden können.","fa":"اگر مدیریت بهتر آماده شده بود، می‌شد از بسیاری از درگیری‌ها جلوگیری کرد."},{"de":"Wären die Mitarbeiter früher geschult worden, hätten auch zwei wichtige Fachkräfte das Unternehmen nicht verlassen.","fa":"اگر کارکنان زودتر آموزش داده شده بودند، دو متخصص مهم هم شرکت را ترک نمی‌کردند."},{"de":"Erst nach einem Jahr wurden interkulturelle Trainings für alle Führungskräfte eingeführt.","fa":"تازه پس از یک سال، دوره‌های آموزش میان‌فرهنگی برای همه‌ی مدیران راه‌اندازی شد."},{"de":"Danach verbesserte sich die Zusammenarbeit deutlich, und das gemeinsame Projekt wurde erfolgreich abgeschlossen.","fa":"پس از آن، همکاری به‌طور چشمگیری بهتر شد و پروژه‌ی مشترک با موفقیت به پایان رسید."},{"de":"Aus diesem Fall lassen sich drei Lehren ziehen.","fa":"از این نمونه می‌توان سه درس گرفت."},{"de":"Erstens sollte man sich vor einer Kooperation über die andere Kultur informieren.","fa":"اول اینکه پیش از هر همکاری باید درباره‌ی فرهنگ طرف مقابل اطلاعات کسب کرد."},{"de":"Zweitens hilft es, Missverständnisse offen anzusprechen, statt sie einfach stillschweigend zu tolerieren.","fa":"دوم اینکه کمک می‌کند سوءتفاهم‌ها را آشکارا مطرح کنیم، به جای اینکه فقط در سکوت تحملشان کنیم."},{"de":"Und drittens sollte man sich bewusst machen, dass es überall Unterschiede gibt, auch innerhalb eines Landes.","fa":"و سوم اینکه باید آگاه باشیم که همه‌جا تفاوت وجود دارد، حتی درون یک کشور."},{"de":"Interkulturelle Kompetenz ist also keine angeborene Eigenschaft, sondern etwas, das man lernen kann.","fa":"پس توانش میان‌فرهنگی ویژگی مادرزادی نیست، بلکه چیزی است که می‌توان یاد گرفت."},{"de":"Wenn alle Unternehmen das ernst nehmen würden, gäbe es deutlich weniger gescheiterte internationale Projekte.","fa":"اگر همه‌ی شرکت‌ها این را جدی می‌گرفتند، پروژه‌های بین‌المللیِ شکست‌خورده خیلی کمتر می‌شد."},{"de":"Vielen Dank für Ihre Aufmerksamkeit.","fa":"از توجه شما بسیار سپاسگزارم."}],"q":[{"q":"Wo hält die Sprecherin ihren Vortrag?","opts":["an einer Schule","in einem Radiostudio","auf einer Personalkonferenz"],"a":2,"fa":"سخنران در آغاز می‌گوید خوشحال است که در این همایش منابع انسانی صحبت می‌کند."},{"q":"Welche Unternehmen haben fusioniert?","opts":["zwei deutsche","ein deutsches und ein amerikanisches","ein deutsches und ein japanisches"],"a":2,"fa":"یک شرکت ماشین‌سازی آلمانی با یک شرکت ژاپنی ادغام شد."},{"q":"Wie empfanden die japanischen Kollegen die direkte Kritik?","opts":["als hilfreich","als lustig","als unhöflich"],"a":2,"fa":"همکاران ژاپنی رک‌گویی آلمانی‌ها را بی‌ادبانه می‌دانستند."},{"q":"Wann wurden interkulturelle Trainings eingeführt?","opts":["erst nach einem Jahr","gar nicht","schon vor der Fusion"],"a":0,"fa":"سخنران می‌گوید دوره‌های آموزش میان‌فرهنگی تازه پس از یک سال راه‌اندازی شد."},{"q":"Was sollte man laut der Sprecherin mit Missverständnissen tun?","opts":["sie offen ansprechen","sie ignorieren","sie dem Chef melden"],"a":0,"fa":"درس دوم این است که سوءتفاهم‌ها را آشکارا مطرح کنیم، نه اینکه در سکوت تحملشان کنیم."},{"q":"Was sagt die Sprecherin über interkulturelle Kompetenz?","opts":["Man hat sie von Geburt an.","Sie ist nur für Manager wichtig.","Man kann sie lernen."],"a":2,"fa":"به گفته‌ی سخنران، توانش میان‌فرهنگی مادرزادی نیست و می‌توان آن را یاد گرفت."}]},{"id":"h3","type":"Radiobeitrag","title":"Hass im Netz – was kann man tun?","title_fa":"نفرت در فضای مجازی؛ چه می‌توان کرد؟","intro_fa":"یک گزارش رادیویی درباره‌ی کامنت‌های نفرت‌آمیز در اینترنت، علت‌های آن و راه‌های مقابله با آن.","s":[{"de":"Beleidigungen, Drohungen und Lügen: Hasskommentare gehören für viele Menschen inzwischen zum Alltag im Internet.","fa":"توهین، تهدید و دروغ: کامنت‌های نفرت‌آمیز برای بسیاری از مردم دیگر بخشی از زندگی روزمره در اینترنت شده است."},{"de":"Laut einer aktuellen Studie haben fast vierzig Prozent der jungen Erwachsenen in Deutschland schon einmal Hass im Netz erlebt.","fa":"طبق یک پژوهش تازه، نزدیک به چهل درصد از جوانان در آلمان تا به حال دست‌کم یک بار نفرت در فضای مجازی را تجربه کرده‌اند."},{"de":"Besonders betroffen sind Politikerinnen, Journalisten und Menschen, die sich öffentlich für andere engagieren.","fa":"به‌ویژه سیاستمداران، روزنامه‌نگاران و کسانی که به‌طور علنی برای دیگران فعالیت می‌کنند، آسیب می‌بینند."},{"de":"Viele von ihnen ziehen sich deshalb aus den sozialen Medien zurück.","fa":"به همین دلیل بسیاری از آن‌ها از شبکه‌های اجتماعی کناره می‌گیرند."},{"de":"Das ist ein Problem für die Demokratie, denn so werden wichtige Stimmen leiser.","fa":"این برای دموکراسی مشکل است، چون به این ترتیب صداهای مهم ضعیف‌تر می‌شوند."},{"de":"Oft wird argumentiert, dass harte Kommentare einfach zur Meinungsfreiheit gehören.","fa":"اغلب استدلال می‌شود که کامنت‌های تند بخشی طبیعی از آزادی بیان هستند."},{"de":"Doch die Meinungsfreiheit hat Grenzen: Beleidigungen und Drohungen sind auch im Internet strafbar.","fa":"اما آزادی بیان حد و مرزی دارد: توهین و تهدید در اینترنت هم جرم است."},{"de":"Warum sind Menschen online so viel aggressiver als im direkten Gespräch?","fa":"چرا آدم‌ها در فضای آنلاین این‌قدر پرخاشگرتر از گفت‌وگوی رودررو هستند؟"},{"de":"Experten nennen vor allem die Anonymität und die fehlende Reaktion des Gegenübers.","fa":"کارشناسان بیش از همه به ناشناس بودن و نبودِ واکنش طرف مقابل اشاره می‌کنند."},{"de":"Würde man der betroffenen Person in die Augen sehen, würde man solche Sätze kaum sagen.","fa":"اگر آدم به چشم فرد آسیب‌دیده نگاه می‌کرد، به‌سختی چنین جمله‌هایی می‌گفت."},{"de":"Was kann man also tun, wenn man selbst Opfer wird oder Hasskommentare liest?","fa":"پس اگر خودمان قربانی شویم یا کامنت‌های نفرت‌آمیز بخوانیم، چه کاری می‌توانیم بکنیم؟"},{"de":"Erstens sollte man nicht im gleichen Ton antworten, denn das heizt die Diskussion nur weiter an.","fa":"اول اینکه نباید با همان لحن جواب داد، چون این کار فقط بحث را داغ‌تر می‌کند."},{"de":"Zweitens sollte man Screenshots machen, damit die Kommentare später als Beweis genutzt werden können.","fa":"دوم اینکه باید از صفحه عکس گرفت تا بعداً بتوان از کامنت‌ها به‌عنوان مدرک استفاده کرد."},{"de":"Drittens kann man die Beiträge bei der Plattform melden und in schweren Fällen Anzeige bei der Polizei erstatten.","fa":"سوم اینکه می‌توان پست‌ها را به پلتفرم گزارش داد و در موارد جدی به پلیس شکایت کرد."},{"de":"Außerdem gibt es Beratungsstellen, die Betroffene kostenlos unterstützen.","fa":"علاوه بر این، مراکز مشاوره‌ای هستند که به افراد آسیب‌دیده رایگان کمک می‌کنند."},{"de":"Auch Mitlesende können etwas bewirken, indem sie sachlich widersprechen und sich solidarisch zeigen.","fa":"خوانندگان دیگر هم می‌توانند تأثیر بگذارند، با اینکه منطقی مخالفت کنند و همبستگی نشان دهند."},{"de":"Eine Betroffene erzählte uns, dass ihr die unterstützenden Nachrichten fremder Menschen sehr geholfen haben.","fa":"یکی از آسیب‌دیدگان برای ما تعریف کرد که پیام‌های حمایت‌آمیز غریبه‌ها خیلی به او کمک کرده است."},{"de":"Hätte sie damals niemand unterstützt, hätte sie ihr Engagement wahrscheinlich aufgegeben.","fa":"اگر آن موقع کسی از او حمایت نکرده بود، احتمالاً فعالیتش را کنار می‌گذاشت."},{"de":"Kritiker fordern zudem, dass die Plattformen strenger kontrolliert werden.","fa":"منتقدان همچنین خواستار نظارت سخت‌گیرانه‌تر بر پلتفرم‌ها هستند."},{"de":"Viele Hasskommentare würden schneller gelöscht werden, wenn die Betreiber mehr Personal einsetzen würden.","fa":"اگر گردانندگان پلتفرم‌ها نیروی بیشتری به کار می‌گرفتند، بسیاری از کامنت‌های نفرت‌آمیز سریع‌تر پاک می‌شدند."},{"de":"Mehr Informationen und Adressen von Beratungsstellen finden Sie auf unserer Internetseite.","fa":"اطلاعات بیشتر و نشانی مراکز مشاوره را در وب‌سایت ما پیدا می‌کنید."}],"q":[{"q":"Wie viele junge Erwachsene haben schon Hass im Netz erlebt?","opts":["fast zehn Prozent","fast vierzig Prozent","über achtzig Prozent"],"a":1,"fa":"طبق پژوهش ذکرشده، نزدیک به چهل درصد از جوانان آلمان این تجربه را داشته‌اند."},{"q":"Warum ist der Rückzug aus den sozialen Medien ein Problem?","opts":["Weil wichtige Stimmen leiser werden.","Weil die Plattformen Geld verlieren.","Weil man dann keine Nachrichten mehr bekommt."],"a":0,"fa":"گزارش می‌گوید این برای دموکراسی مشکل است، چون صداهای مهم ضعیف‌تر می‌شوند."},{"q":"Welche Gründe nennen Experten für die Aggressivität im Netz?","opts":["Langeweile und zu viel Freizeit","schlechte Internetverbindungen","Anonymität und die fehlende Reaktion des Gegenübers"],"a":2,"fa":"کارشناسان به ناشناس بودن و نبودِ واکنش طرف مقابل اشاره می‌کنند."},{"q":"Warum soll man Screenshots machen?","opts":["um sie mit Freunden zu teilen","um sie später als Beweis zu nutzen","um sie dem Täter zu schicken"],"a":1,"fa":"عکس از صفحه لازم است تا بعداً بتوان از کامنت‌ها به‌عنوان مدرک استفاده کرد."},{"q":"Was können Mitlesende tun?","opts":["ihr eigenes Konto löschen","sachlich widersprechen","die Kommentare liken"],"a":1,"fa":"خوانندگان دیگر می‌توانند منطقی مخالفت کنند و همبستگی نشان دهند."},{"q":"Was fordern Kritiker?","opts":["ein Verbot sozialer Medien","mehr anonyme Konten","eine strengere Kontrolle der Plattformen"],"a":2,"fa":"منتقدان خواستار نظارت سخت‌گیرانه‌تر بر پلتفرم‌ها هستند."}]}],"2":[{"id":"h1","type":"Vortrag","title":"Wie wird die Stadt der Zukunft gestaltet?","title_fa":"شهر آینده چگونه شکل داده می‌شود؟","intro_fa":"یک کارشناس برنامه‌ریزی شهری در یک همایش دربارهٔ مهاجرت به شهرها، جذابیت و مشکلات کلان‌شهرها و ایده‌هایی برای آینده سخنرانی می‌کند.","s":[{"de":"Sehr geehrte Damen und Herren, in meinem Vortrag geht es darum, wie das Leben in der Stadt in Zukunft gestaltet werden kann.","fa":"خانم‌ها و آقایان محترم، سخنرانی من دربارهٔ این است که زندگی در شهر در آینده چگونه می‌تواند شکل داده شود."},{"de":"Ich spreche zuerst über die Landflucht, dann über die Attraktivität großer Städte, danach über Stressfaktoren und zum Schluss über Ideen für die Zukunft.","fa":"اول دربارهٔ مهاجرت از روستا صحبت می‌کنم، بعد دربارهٔ جذابیت شهرهای بزرگ، سپس دربارهٔ عوامل استرس‌زا و در پایان دربارهٔ ایده‌هایی برای آینده."},{"de":"Weltweit lebt heute schon mehr als die Hälfte der Menschen in Städten.","fa":"امروزه در سراسر جهان بیش از نیمی از مردم در شهرها زندگی می‌کنند."},{"de":"Nach Prognosen der Vereinten Nationen wird dieser Anteil bis 2050 auf fast siebzig Prozent steigen.","fa":"طبق پیش‌بینی‌های سازمان ملل، این سهم تا سال ۲۰۵۰ به نزدیک هفتاد درصد خواهد رسید."},{"de":"Vor allem in Asien und Afrika verlassen junge Menschen ihre Dörfer, weil dort kaum Arbeitsstellen angeboten werden.","fa":"به‌ویژه در آسیا و آفریقا جوانان روستاهایشان را ترک می‌کنند، چون در آنجا تقریباً هیچ شغلی عرضه نمی‌شود."},{"de":"Aber warum sind Großstädte eigentlich so attraktiv?","fa":"اما اصلاً چرا کلان‌شهرها این‌قدر جذاب هستند؟"},{"de":"In den Städten sind die meisten Bildungseinrichtungen, Kliniken und Kulturangebote konzentriert.","fa":"بیشتر مراکز آموزشی، بیمارستان‌ها و امکانات فرهنگی در شهرها متمرکز شده‌اند."},{"de":"Außerdem werden dort viele Startups gegründet, und Technologiefirmen suchen ständig gut ausgebildete Fachkräfte.","fa":"علاوه بر این، در آنجا استارتاپ‌های زیادی تأسیس می‌شود و شرکت‌های فناوری مدام به دنبال نیروی متخصص آموزش‌دیده هستند."},{"de":"In einer Umfrage gaben viele junge Leute an, dass sie das Leben in der Stadt einfach anregender finden.","fa":"در یک نظرسنجی، بسیاری از جوانان گفتند که زندگی در شهر را به‌سادگی هیجان‌انگیزتر می‌دانند."},{"de":"Doch der Run auf die Städte hat auch Schattenseiten.","fa":"اما هجوم به شهرها جنبه‌های منفی هم دارد."},{"de":"Verkehrslärm, Smog und die Abgase von Millionen Autos schädigen die Gesundheit der Bewohner.","fa":"سروصدای ترافیک، دود و آلودگی هوا و گازهای خروجی میلیون‌ها خودرو به سلامت ساکنان آسیب می‌زنند."},{"de":"In manchen Megastädten werden die Grenzwerte für Feinstaub an mehr als hundert Tagen im Jahr überschritten.","fa":"در برخی از ابرشهرها، حد مجاز ذرات معلق در بیش از صد روز از سال رد می‌شود."},{"de":"Hinzu kommen hohe Mieten und ein enges Zusammenleben auf wenig Raum.","fa":"اجاره‌بهای بالا و زندگی فشرده در فضایی کوچک هم به این مشکلات اضافه می‌شود."},{"de":"Wie können diese Probleme gelöst werden?","fa":"این مشکلات چگونه می‌توانند حل شوند؟"},{"de":"In vielen Städten wird bereits an Antworten gearbeitet.","fa":"در بسیاری از شهرها هم‌اکنون روی راه‌حل‌ها کار می‌شود."},{"de":"In Kopenhagen zum Beispiel wurde das Radwegenetz so stark ausgebaut, dass heute fast die Hälfte der Pendler mit dem Fahrrad zur Arbeit fährt.","fa":"برای نمونه در کپنهاگ شبکهٔ مسیرهای دوچرخه آن‌قدر گسترش داده شد که امروز تقریباً نیمی از رفت‌وآمدکنندگان با دوچرخه سر کار می‌روند."},{"de":"Andere Städte setzen auf die Digitalisierung: Ampeln, Busse und Parkplätze werden digital vernetzt, damit der Verkehr besser fließt.","fa":"شهرهای دیگر روی دیجیتالی‌سازی حساب می‌کنند: چراغ‌های راهنمایی، اتوبوس‌ها و پارکینگ‌ها به‌صورت دیجیتال به هم متصل می‌شوند تا ترافیک روان‌تر شود."},{"de":"Außerdem müssen mehr Grünflächen geschaffen werden, denn Parks und begrünte Dächer kühlen die Luft im Sommer.","fa":"همچنین باید فضای سبز بیشتری ایجاد شود، چون پارک‌ها و بام‌های سبز هوا را در تابستان خنک می‌کنند."},{"de":"Wichtig ist auch, dass die Bürger in die Stadtplanung einbezogen werden, zum Beispiel in Workshops.","fa":"این هم مهم است که شهروندان در برنامه‌ریزی شهری مشارکت داده شوند، مثلاً در کارگاه‌ها."},{"de":"Nur so können innovative Ideen entwickelt werden, die wirklich zu den einzelnen Vierteln passen.","fa":"فقط این‌طور می‌توان ایده‌های نوآورانه‌ای پرورش داد که واقعاً با هر محله سازگار باشند."},{"de":"Wenn wir also in die Zukunft blicken, sehe ich die Städte nicht nur als Problem, sondern auch als große Chance.","fa":"پس وقتی به آینده نگاه می‌کنیم، من شهرها را نه فقط یک مشکل، بلکه یک فرصت بزرگ هم می‌بینم."},{"de":"Vielen Dank für Ihre Aufmerksamkeit.","fa":"از توجه شما بسیار سپاسگزارم."}],"q":[{"q":"Welcher Anteil der Weltbevölkerung wird im Jahr 2050 voraussichtlich in Städten leben?","opts":["Mehr als neunzig Prozent.","Etwa die Hälfte.","Fast siebzig Prozent."],"a":2,"fa":"طبق پیش‌بینی سازمان ملل، این سهم تا ۲۰۵۰ به «نزدیک هفتاد درصد» می‌رسد؛ نیمی از مردم همین امروز در شهرها هستند."},{"q":"Warum verlassen viele junge Menschen ihre Dörfer?","opts":["Weil es dort zu laut ist.","Weil die Mieten dort zu hoch sind.","Weil es dort kaum Arbeitsstellen gibt."],"a":2,"fa":"سخنران گفت در روستاها «تقریباً هیچ شغلی عرضه نمی‌شود»."},{"q":"Was wird im Vortrag NICHT als Stressfaktor in Großstädten genannt?","opts":["Fehlende Kulturangebote.","Abgase.","Verkehrslärm."],"a":0,"fa":"سروصدا و گازهای خروجی جزو مشکلات بودند، اما امکانات فرهنگی در شهرها فراوان است و جزو جذابیت‌ها شمرده شد."},{"q":"Was wurde in Kopenhagen gemacht?","opts":["Neue Autobahnen wurden gebaut.","Das Radwegenetz wurde stark ausgebaut.","Alle Busse wurden abgeschafft."],"a":1,"fa":"در کپنهاگ شبکهٔ مسیرهای دوچرخه گسترش داده شد و حالا نزدیک نیمی از افراد با دوچرخه سر کار می‌روند."},{"q":"Warum sollen mehr Grünflächen geschaffen werden?","opts":["Damit mehr Parkplätze entstehen.","Damit mehr Touristen kommen.","Weil Parks und grüne Dächer die Luft kühlen."],"a":2,"fa":"دلیلش این بود که «پارک‌ها و بام‌های سبز هوا را در تابستان خنک می‌کنند»."},{"q":"Wie sieht der Redner die Städte am Ende?","opts":["Als unwichtig für die Zukunft.","Auch als große Chance.","Nur als großes Problem."],"a":1,"fa":"در پایان گفت شهرها را «نه فقط یک مشکل، بلکه یک فرصت بزرگ» می‌بیند."}]},{"id":"h2","type":"Präsentation","title":"Aus Alt mach Neu: der Speicher am Hafen","title_fa":"از کهنه، نو بساز: انبار غلهٔ کنار بندر","intro_fa":"یک زبان‌آموز در کلاس، ارائهٔ کوتاهی دربارهٔ یک انبار قدیمی در شهر زادگاهش دارد که به‌جای تخریب، بازسازی شد.","s":[{"de":"Hallo zusammen, ich möchte euch heute ein Gebäude vorstellen, das mich sehr beeindruckt hat: den alten Getreidespeicher am Hafen meiner Heimatstadt.","fa":"سلام به همه، امروز می‌خواهم ساختمانی را به شما معرفی کنم که خیلی تحت تأثیرم قرار داد: انبار قدیمی غله در بندر شهر زادگاهم."},{"de":"Zunächst erzähle ich etwas zur Geschichte, dann gehe ich auf den Umbau ein, und am Ende sage ich euch meine eigene Meinung.","fa":"اول کمی دربارهٔ تاریخچه می‌گویم، بعد به بازسازی می‌پردازم و در پایان نظر خودم را به شما می‌گویم."},{"de":"Der Speicher wurde 1910 aus roten Backsteinen gebaut und war damals eines der höchsten Gebäude der Stadt.","fa":"این انبار در سال ۱۹۱۰ از آجر قرمز ساخته شد و در آن زمان یکی از بلندترین ساختمان‌های شهر بود."},{"de":"Fast siebzig Jahre lang wurde dort Getreide gelagert, das mit Schiffen aus aller Welt gebracht wurde.","fa":"تقریباً هفتاد سال در آنجا غله‌ای نگهداری می‌شد که با کشتی از سراسر جهان آورده می‌شد."},{"de":"Seit den Achtzigerjahren stand das Gebäude leer, weil dieser Teil des Hafens nicht mehr gebraucht wurde.","fa":"از دههٔ هشتاد میلادی این ساختمان خالی ماند، چون دیگر به این بخش از بندر نیازی نبود."},{"de":"Vor etwa zehn Jahren wurde dann heftig diskutiert, ob der Speicher abgerissen werden sollte.","fa":"حدود ده سال پیش بحث داغی درگرفت که آیا انبار باید تخریب شود یا نه."},{"de":"Ein Investor wollte an seiner Stelle ein modernes Hochhaus mit Büros bauen.","fa":"یک سرمایه‌گذار می‌خواست به‌جای آن یک برج مدرن اداری بسازد."},{"de":"Viele Bürger waren jedoch dagegen, weil sie das historische Gebäude als Teil ihrer Identität sahen.","fa":"اما بسیاری از شهروندان مخالف بودند، چون این ساختمان تاریخی را بخشی از هویت خود می‌دانستند."},{"de":"Am Ende hat der Stadtrat entschieden, dass der Speicher nicht abgerissen werden darf, sondern umgebaut werden muss.","fa":"در نهایت شورای شهر تصمیم گرفت که انبار نباید تخریب شود، بلکه باید بازسازی شود."},{"de":"Wie ihr auf dem Foto links seht, ist die alte Fassade fast vollständig erhalten geblieben.","fa":"همان‌طور که در عکس سمت چپ می‌بینید، نمای قدیمی تقریباً به‌طور کامل حفظ شده است."},{"de":"Im Inneren wurde dagegen fast alles erneuert.","fa":"اما در داخل، تقریباً همه‌چیز نوسازی شد."},{"de":"Heute befinden sich dort rund 120 Wohnungen, eine Stadtbibliothek und ein kleines Café im Erdgeschoss.","fa":"امروز در آنجا حدود ۱۲۰ آپارتمان، یک کتابخانهٔ شهری و یک کافهٔ کوچک در طبقهٔ همکف قرار دارد."},{"de":"Auf dem Dach wurde ein Garten angelegt, der von allen Bewohnern genutzt werden kann.","fa":"روی بام باغی ساخته شد که همهٔ ساکنان می‌توانند از آن استفاده کنند."},{"de":"Die Architektin wollte zeigen, dass alte Industriegebäude nicht abgerissen werden müssen, nur weil sie nicht mehr modern sind.","fa":"معمار این پروژه می‌خواست نشان دهد که ساختمان‌های صنعتی قدیمی را لازم نیست فقط به این دلیل که دیگر مدرن نیستند تخریب کرد."},{"de":"Auch für die Umwelt war das gut, denn durch den Umbau konnten große Mengen an Beton und Energie gespart werden.","fa":"این کار برای محیط زیست هم خوب بود، چون با بازسازی، مقدار زیادی بتن و انرژی صرفه‌جویی شد."},{"de":"Natürlich gibt es auch Kritik.","fa":"البته انتقادهایی هم وجود دارد."},{"de":"Der Umbau hat fast doppelt so viel gekostet wie ursprünglich geplant.","fa":"هزینهٔ بازسازی تقریباً دو برابر مبلغی شد که در ابتدا برنامه‌ریزی شده بود."},{"de":"Außerdem sind die Wohnungen so teuer, dass sich normale Familien sie kaum leisten können.","fa":"علاوه بر این، آپارتمان‌ها آن‌قدر گران هستند که خانواده‌های معمولی به‌سختی از پس هزینه‌شان برمی‌آیند."},{"de":"So viel zu den Fakten, und damit komme ich zu meiner persönlichen Meinung.","fa":"این‌ها واقعیت‌ها بودند و حالا به نظر شخصی خودم می‌رسم."},{"de":"Ich finde, dass der Speicher ein gutes Beispiel dafür ist, wie Altes und Neues miteinander verbunden werden können.","fa":"به نظرم این انبار نمونهٔ خوبی است از اینکه چطور می‌توان قدیم و جدید را به هم پیوند داد."},{"de":"Allerdings hätte ich mir gewünscht, dass ein Teil der Wohnungen günstiger vermietet wird.","fa":"البته دوست داشتم بخشی از آپارتمان‌ها ارزان‌تر اجاره داده شود."},{"de":"Damit bin ich am Ende, vielen Dank für eure Aufmerksamkeit!","fa":"به این ترتیب ارائهٔ من به پایان رسید؛ از توجه شما خیلی ممنونم!"}],"q":[{"q":"Wofür wurde der Speicher früher genutzt?","opts":["Dort wurde Getreide gelagert.","Dort wurden Schiffe gebaut.","Dort befanden sich Büros."],"a":0,"fa":"گوینده گفت تقریباً هفتاد سال در آنجا «غله نگهداری می‌شد»."},{"q":"Warum stand das Gebäude seit den Achtzigerjahren leer?","opts":["Weil die Stadt es verkaufen wollte.","Weil dieser Teil des Hafens nicht mehr gebraucht wurde.","Weil es bei einem Brand beschädigt wurde."],"a":1,"fa":"دلیلش این بود که «دیگر به این بخش از بندر نیازی نبود»."},{"q":"Was wollte der Investor?","opts":["Ein Museum im alten Speicher eröffnen.","Einen großen Park anlegen.","Ein modernes Bürohochhaus bauen."],"a":2,"fa":"سرمایه‌گذار می‌خواست به‌جای انبار «یک برج مدرن اداری» بسازد."},{"q":"Was befindet sich heute im Speicher?","opts":["Ein Hotel mit Restaurant.","Nur Büros und Geschäfte.","Wohnungen, eine Bibliothek und ein Café."],"a":2,"fa":"امروز در آنجا حدود ۱۲۰ آپارتمان، یک کتابخانهٔ شهری و یک کافه هست."},{"q":"Welche Kritik wird an dem Projekt genannt?","opts":["Es war viel teurer als geplant, und die Wohnungen sind sehr teuer.","Die Bewohner dürfen den Dachgarten nicht nutzen.","Die alte Fassade wurde zerstört."],"a":0,"fa":"انتقادها این بود که هزینه تقریباً دو برابر شد و آپارتمان‌ها برای خانواده‌های معمولی گران‌اند؛ نما حفظ شده است."},{"q":"Was hätte sich der Sprecher gewünscht?","opts":["Dass der Speicher abgerissen wird.","Dass mehr Büros entstehen.","Dass ein Teil der Wohnungen günstiger ist."],"a":2,"fa":"او گفت دوست داشت «بخشی از آپارتمان‌ها ارزان‌تر اجاره داده شود»."}]},{"id":"h3","type":"Radiobeitrag","title":"Wohnungssuche in deutschen Großstädten","title_fa":"جست‌وجوی خانه در کلان‌شهرهای آلمان","intro_fa":"یک گزارش رادیویی دربارهٔ کمبود مسکن در شهرهای بزرگ آلمان، دلایل آن، گروه‌های آسیب‌دیده و راه‌حل‌های پیشنهادی.","s":[{"de":"In unserer Sendung „Stadtleben“ geht es heute um ein Thema, das viele Menschen in Deutschland beschäftigt: die Wohnungssuche in den Großstädten.","fa":"در برنامهٔ «زندگی شهری» امروز به موضوعی می‌پردازیم که ذهن بسیاری از مردم آلمان را مشغول کرده است: جست‌وجوی خانه در کلان‌شهرها."},{"de":"Im europäischen Vergleich ist Deutschland ein Land der Mieter.","fa":"در مقایسه با دیگر کشورهای اروپایی، آلمان کشور مستأجرهاست."},{"de":"Mehr als die Hälfte aller Haushalte wohnt zur Miete, während zum Beispiel in Spanien oder Polen die große Mehrheit eine eigene Wohnung besitzt.","fa":"بیش از نیمی از خانوارها مستأجرند، در حالی که برای نمونه در اسپانیا یا لهستان اکثریت بزرگی خانهٔ شخصی دارند."},{"de":"In Städten wie München, Frankfurt oder Berlin ist der Anteil der Mieter sogar noch deutlich höher.","fa":"در شهرهایی مانند مونیخ، فرانکفورت یا برلین سهم مستأجرها حتی خیلی بیشتر است."},{"de":"Lange Zeit war das kein großes Problem, denn Mietwohnungen waren relativ günstig.","fa":"مدت‌ها این مسئلهٔ بزرگی نبود، چون آپارتمان‌های اجاره‌ای نسبتاً ارزان بودند."},{"de":"In den letzten fünfzehn Jahren sind die Mieten in vielen Großstädten jedoch stark gestiegen, teilweise um mehr als fünfzig Prozent.","fa":"اما در پانزده سال گذشته اجاره‌ها در بسیاری از کلان‌شهرها به‌شدت بالا رفته‌اند، گاهی بیش از پنجاه درصد."},{"de":"Der wichtigste Grund dafür ist, dass zu wenige neue Wohnungen gebaut wurden, während immer mehr Menschen in die Städte zogen.","fa":"مهم‌ترین دلیلش این است که خانه‌های جدید بسیار کمی ساخته شد، در حالی که مردم بیشتر و بیشتری به شهرها نقل مکان کردند."},{"de":"Für eine freie Wohnung melden sich deshalb oft mehr als hundert Interessenten.","fa":"به همین دلیل برای یک آپارتمان خالی اغلب بیش از صد متقاضی پیدا می‌شود."},{"de":"Besonders betroffen sind Menschen mit geringem Einkommen, zum Beispiel Rentnerinnen und Rentner oder Alleinerziehende.","fa":"افراد کم‌درآمد بیش از همه آسیب می‌بینند، مثلاً بازنشستگان یا پدران و مادران تنها."},{"de":"Auch Studierende haben es schwer, weil die Plätze in Wohnheimen bei Weitem nicht ausreichen.","fa":"دانشجویان هم وضع سختی دارند، چون ظرفیت خوابگاه‌ها به هیچ وجه کافی نیست."},{"de":"Viele müssen deshalb einen großen Teil ihres Einkommens für die Miete ausgeben, manchmal mehr als vierzig Prozent.","fa":"به همین دلیل بسیاری مجبورند بخش بزرگی از درآمدشان را خرج اجاره کنند، گاهی بیش از چهل درصد."},{"de":"Was kann dagegen getan werden?","fa":"برای مقابله با این وضع چه می‌توان کرد؟"},{"de":"Politiker fordern seit Jahren, dass jedes Jahr mehrere hunderttausend neue Wohnungen gebaut werden sollen.","fa":"سیاستمداران سال‌هاست خواستار آن‌اند که هر سال چند صد هزار خانهٔ جدید ساخته شود."},{"de":"Dieses Ziel wurde bisher aber nicht erreicht, weil Bauland knapp ist und die Baukosten gestiegen sind.","fa":"اما این هدف تاکنون محقق نشده، چون زمین برای ساخت‌وساز کم است و هزینه‌های ساخت بالا رفته است."},{"de":"Fachleute schlagen deshalb vor, dass vorhandene Gebäude besser genutzt werden müssen.","fa":"به همین دلیل کارشناسان پیشنهاد می‌کنند که از ساختمان‌های موجود باید بهتر استفاده شود."},{"de":"So könnten leer stehende Büros in Wohnungen umgebaut werden, und auf viele Supermärkte könnten noch zwei oder drei Etagen gesetzt werden.","fa":"مثلاً می‌شود دفترهای خالی را به آپارتمان تبدیل کرد و روی بسیاری از سوپرمارکت‌ها دو یا سه طبقهٔ دیگر ساخت."},{"de":"Ein Vorteil dieser Lösung ist, dass keine neuen Flächen bebaut werden müssen.","fa":"یکی از مزایای این راه‌حل این است که لازم نیست زمین تازه‌ای زیر ساخت‌وساز برود."},{"de":"Kritiker weisen allerdings darauf hin, dass solche Umbauten oft teuer und technisch kompliziert sind.","fa":"البته منتقدان یادآوری می‌کنند که چنین تغییراتی اغلب پرهزینه و از نظر فنی پیچیده است."},{"de":"Andere setzen auf den sozialen Wohnungsbau, also auf Wohnungen, deren Miete vom Staat begrenzt wird.","fa":"عده‌ای دیگر به مسکن اجتماعی امید بسته‌اند، یعنی آپارتمان‌هایی که اجاره‌شان را دولت محدود می‌کند."},{"de":"Klar ist: Ohne neue Ideen wird sich die Lage in den Großstädten so schnell nicht entspannen.","fa":"یک چیز روشن است: بدون ایده‌های تازه، وضعیت در کلان‌شهرها به این زودی آرام نخواهد شد."},{"de":"Nach den Nachrichten sprechen wir darüber, wie Wohngemeinschaften für Jung und Alt funktionieren.","fa":"بعد از اخبار دربارهٔ این صحبت می‌کنیم که خانه‌های اشتراکی برای جوان و پیر چگونه کار می‌کنند."}],"q":[{"q":"Was ist typisch für Deutschland im europäischen Vergleich?","opts":["Fast alle Menschen besitzen eine eigene Wohnung.","Mehr als die Hälfte der Haushalte wohnt zur Miete.","Die Mieten sind die niedrigsten in Europa."],"a":1,"fa":"گفته شد آلمان «کشور مستأجرهاست» و بیش از نیمی از خانوارها اجاره‌نشین‌اند."},{"q":"Was ist laut Beitrag der wichtigste Grund für die steigenden Mieten?","opts":["Viele Touristen mieten Wohnungen.","Es gibt zu viele leere Büros.","Es wurden zu wenige Wohnungen gebaut, während mehr Menschen in die Städte zogen."],"a":2,"fa":"مهم‌ترین دلیل: خانهٔ جدید کم ساخته شد، در حالی که مردم بیشتری به شهرها آمدند."},{"q":"Welche Gruppen sind besonders betroffen?","opts":["Menschen mit hohem Einkommen.","Besitzer von großen Häusern.","Rentner, Alleinerziehende und Studierende."],"a":2,"fa":"افراد کم‌درآمد مثل بازنشستگان و والدین تنها، و همچنین دانشجویان، بیش از همه آسیب می‌بینند."},{"q":"Warum wurde das politische Ziel beim Wohnungsbau bisher nicht erreicht?","opts":["Weil niemand neue Wohnungen braucht.","Weil Bauland knapp ist und die Baukosten gestiegen sind.","Weil das Ziel zu niedrig war."],"a":1,"fa":"دلیلش کمبود زمین و افزایش هزینه‌های ساخت عنوان شد."},{"q":"Was schlagen Fachleute vor?","opts":["Alle alten Gebäude abzureißen.","Die Mieten ganz zu verbieten.","Vorhandene Gebäude besser zu nutzen."],"a":2,"fa":"کارشناسان پیشنهاد می‌کنند از ساختمان‌های موجود بهتر استفاده شود، مثلاً تبدیل دفترهای خالی به آپارتمان."},{"q":"Welchen Nachteil dieser Lösung nennen Kritiker?","opts":["Die Umbauten sind oft teuer und kompliziert.","Es gibt keine Interessenten für solche Wohnungen.","Es müssen zu viele neue Flächen bebaut werden."],"a":0,"fa":"منتقدان می‌گویند چنین تغییراتی «پرهزینه و از نظر فنی پیچیده» است؛ نیاز نداشتن به زمین تازه یک مزیت است."}]}],"3":[{"id":"h1","type":"Radiobeitrag","title":"Können Tiere lügen?","title_fa":"آیا حیوانات می‌توانند دروغ بگویند؟","intro_fa":"یک گزارش رادیویی در برنامه‌ای دربارهٔ طبیعت توضیح می‌دهد که حیوانات چگونه و به چه هدفی دیگران را فریب می‌دهند.","s":[{"de":"Willkommen bei „Natur im Fokus“, heute gehen wir einer ungewöhnlichen Frage nach: Können Tiere eigentlich lügen?","fa":"به برنامهٔ «طبیعت در کانون توجه» خوش آمدید؛ امروز به پرسشی غیرعادی می‌پردازیم: آیا حیوانات اصلاً می‌توانند دروغ بگویند؟"},{"de":"Die meisten Biologen sind sich einig, dass Tiere nicht bewusst und geplant lügen wie wir Menschen.","fa":"بیشتر زیست‌شناسان هم‌نظرند که حیوانات مثل ما انسان‌ها آگاهانه و برنامه‌ریزی‌شده دروغ نمی‌گویند."},{"de":"Dennoch täuschen und tricksen viele Arten, und das oft sehr geschickt.","fa":"با این حال، بسیاری از گونه‌ها فریب می‌دهند و حقه می‌زنند، آن هم اغلب بسیار ماهرانه."},{"de":"Bei uns Menschen hat das Flunkern häufig soziale Motive.","fa":"در ما انسان‌ها، دروغ‌های کوچک اغلب انگیزه‌های اجتماعی دارند."},{"de":"Wir loben zum Beispiel ein misslungenes Essen, um höflich zu sein und den Gastgeber nicht zu verletzen.","fa":"برای مثال، غذایی را که خوب از آب درنیامده تعریف می‌کنیم تا مؤدب باشیم و دل میزبان را نشکنیم."},{"de":"Manchmal schummeln wir aber auch, damit wir uns einen Vorteil verschaffen, etwa bei der Steuererklärung.","fa":"اما گاهی هم تقلب می‌کنیم تا برای خودمان امتیازی به دست آوریم، مثلاً در اظهارنامهٔ مالیاتی."},{"de":"Bei Tieren dagegen geht es fast immer ums Überleben.","fa":"اما در حیوانات، موضوع تقریباً همیشه بقاست."},{"de":"Ihre Täuschungen sind Überlebensstrategien, die sich über Millionen Jahre entwickelt haben.","fa":"فریب‌های آن‌ها راهبردهای بقایی هستند که در طول میلیون‌ها سال شکل گرفته‌اند."},{"de":"Ein schönes Beispiel ist der Sandregenpfeifer, ein kleiner Vogel, der am Strand brütet.","fa":"نمونهٔ جالب، پرندهٔ سلیم طوقی است، پرنده‌ای کوچک که در ساحل جوجه‌آوری می‌کند."},{"de":"Nähert sich ein Fuchs dem Nest, läuft der Vogel mit hängendem Flügel davon und tut so, als wäre er verletzt.","fa":"وقتی روباهی به لانه نزدیک می‌شود، پرنده با بالی آویزان دور می‌شود و وانمود می‌کند که زخمی است."},{"de":"Der Fuchs folgt der scheinbar leichten Beute, während die Jungen im Nest sicher bleiben.","fa":"روباه به دنبال این شکارِ به‌ظاهر آسان می‌رود، در حالی که جوجه‌ها در لانه در امان می‌مانند."},{"de":"Andere Tiere täuschen, um sich selbst zu schützen.","fa":"حیوانات دیگری فریب می‌دهند تا از خودشان محافظت کنند."},{"de":"Das Opossum in Amerika stellt sich bei Gefahr tot, damit der Feind das Interesse verliert.","fa":"اپوسوم در آمریکا هنگام خطر خودش را به مردن می‌زند تا دشمن علاقه‌اش را از دست بدهد."},{"de":"Der Kugelfisch macht genau das Gegenteil: Er pumpt sich mit Wasser auf, um größer und gefährlicher zu wirken, als er ist.","fa":"ماهی بادکنکی دقیقاً برعکس عمل می‌کند: خودش را با آب باد می‌کند تا بزرگ‌تر و خطرناک‌تر از آنچه هست به نظر برسد."},{"de":"Besonders raffiniert ist der Trick des Kuckucks.","fa":"حقهٔ فاخته به‌ویژه زیرکانه است."},{"de":"Das Weibchen legt seine Eier in die Nester anderer Vögel, damit diese die Jungen ausbrüten und füttern.","fa":"فاختهٔ ماده تخم‌هایش را در لانهٔ پرندگان دیگر می‌گذارد تا آن‌ها جوجه‌ها را از تخم درآورند و غذا بدهند."},{"de":"Die Eier sehen dabei den Eiern der fremden Vögel oft erstaunlich ähnlich.","fa":"این تخم‌ها اغلب به‌طرز شگفت‌آوری شبیه تخم‌های آن پرندگان دیگرند."},{"de":"So sichert der Kuckuck seine Fortpflanzung, ohne selbst Zeit und Energie in die Aufzucht zu stecken.","fa":"به این ترتیب فاخته تولید مثل خود را تضمین می‌کند، بی‌آنکه خودش برای بزرگ کردن جوجه‌ها وقت و انرژی بگذارد."},{"de":"Für die betrogenen Vogeleltern richtet das großen Schaden an, denn ihre eigenen Jungen überleben meistens nicht.","fa":"این کار به پرندگانِ فریب‌خورده آسیب بزرگی می‌زند، چون جوجه‌های خودشان معمولاً زنده نمی‌مانند."},{"de":"Man sieht also: Täuschung ist in der Natur weit verbreitet, während echte Lügen wohl eine menschliche Erfindung sind.","fa":"پس می‌بینیم: فریب در طبیعت بسیار رایج است، در حالی که دروغ واقعی احتمالاً اختراع انسان است."},{"de":"Im zweiten Teil unserer Sendung schauen wir uns an, ob auch Affen ihre Artgenossen bewusst hereinlegen können.","fa":"در بخش دوم برنامه بررسی می‌کنیم که آیا میمون‌ها هم می‌توانند هم‌نوعانشان را آگاهانه فریب دهند."}],"q":[{"q":"Welche Meinung vertreten die meisten Biologen?","opts":["Tiere täuschen niemals andere.","Tiere lügen genauso bewusst wie Menschen.","Tiere lügen nicht bewusst, aber sie täuschen."],"a":2,"fa":"زیست‌شناسان می‌گویند حیوانات آگاهانه دروغ نمی‌گویند، «با این حال» بسیاری از آن‌ها فریب می‌دهند."},{"q":"Warum loben Menschen manchmal ein misslungenes Essen?","opts":["Weil sie großen Hunger haben.","Um einen finanziellen Vorteil zu haben.","Um höflich zu sein."],"a":2,"fa":"گفته شد این کار را می‌کنیم «تا مؤدب باشیم و دل میزبان را نشکنیم»."},{"q":"Wozu dient das Verhalten des Sandregenpfeifers?","opts":["Er will seine Jungen schützen.","Er will einen Partner anlocken.","Er will Nahrung finden."],"a":0,"fa":"پرنده وانمود به زخمی بودن می‌کند تا روباه را از لانه دور کند و جوجه‌ها در امان بمانند."},{"q":"Warum stellt sich das Opossum tot?","opts":["Um Beute anzulocken.","Weil es sich ausruhen will.","Damit der Feind das Interesse verliert."],"a":2,"fa":"اپوسوم خودش را به مردن می‌زند «تا دشمن علاقه‌اش را از دست بدهد»."},{"q":"Was macht der Kugelfisch bei Gefahr?","opts":["Er stellt sich tot.","Er versteckt sich im Sand.","Er pumpt sich auf, um größer zu wirken."],"a":2,"fa":"ماهی بادکنکی خودش را با آب باد می‌کند تا بزرگ‌تر و خطرناک‌تر به نظر برسد."},{"q":"Worin besteht der Trick des Kuckucks?","opts":["Er frisst die Eier anderer Vögel.","Er baut Nester für andere Vögel.","Er legt seine Eier in fremde Nester."],"a":2,"fa":"فاختهٔ ماده تخم‌هایش را در لانهٔ پرندگان دیگر می‌گذارد تا آن‌ها جوجه‌ها را بزرگ کنند."}]},{"id":"h2","type":"Kurzvortrag","title":"Warum wir jeden Tag lügen","title_fa":"چرا هر روز دروغ می‌گوییم","intro_fa":"یک روان‌شناس در یک سخنرانی کوتاه، نتایج یک نظرسنجی دربارهٔ دروغ‌های روزمره را ارائه می‌کند و توضیح می‌دهد چرا دروغ این‌قدر رایج است.","s":[{"de":"Meine Damen und Herren, wann haben Sie zum letzten Mal gelogen?","fa":"خانم‌ها و آقایان، آخرین بار کی دروغ گفتید؟"},{"de":"Wenn Sie jetzt „noch nie“ denken, dann ist das vermutlich schon die erste Lüge des Tages.","fa":"اگر الان فکر می‌کنید «هیچ‌وقت»، احتمالاً همین اولین دروغ امروزتان است."},{"de":"In meinem Kurzvortrag möchte ich Ihnen zeigen, warum Lügen so alltäglich sind und welche Funktion sie haben.","fa":"در این سخنرانی کوتاه می‌خواهم نشان دهم چرا دروغ این‌قدر روزمره است و چه کارکردی دارد."},{"de":"Grundlage ist eine Online-Umfrage, an der etwa 2000 Erwachsene teilgenommen haben.","fa":"مبنای کار یک نظرسنجی اینترنتی است که حدود ۲۰۰۰ بزرگسال در آن شرکت کردند."},{"de":"Das Ergebnis ist überraschend: Mehr als die Hälfte der Befragten gab zu, am Vortag mindestens einmal gelogen zu haben.","fa":"نتیجه غافلگیرکننده است: بیش از نیمی از پاسخ‌دهندگان اعتراف کردند که روز قبل دست‌کم یک بار دروغ گفته‌اند."},{"de":"Dabei gab es einen deutlichen Unterschied zwischen den Altersgruppen.","fa":"در این میان، تفاوت روشنی میان گروه‌های سنی وجود داشت."},{"de":"Während bei den Jüngeren fast siebzig Prozent eine Lüge zugaben, waren es bei den über Sechzigjährigen nur knapp dreißig Prozent.","fa":"در حالی که در میان جوان‌ترها تقریباً هفتاد درصد به دروغ گفتن اعتراف کردند، این رقم در میان افراد بالای شصت سال فقط نزدیک سی درصد بود."},{"de":"Ob ältere Menschen ehrlicher sind oder es nur seltener zugeben, bleibt allerdings offen.","fa":"البته معلوم نیست که افراد مسن‌تر صادق‌ترند یا فقط کمتر به آن اعتراف می‌کنند."},{"de":"Interessant ist auch, wem gegenüber wir unehrlich sind.","fa":"این هم جالب است که با چه کسانی صادق نیستیم."},{"de":"Am häufigsten belügen wir flüchtige Bekannte, enge Freunde dagegen deutlich seltener.","fa":"بیشتر از همه به آشنایان دور دروغ می‌گوییم، اما به دوستان نزدیک خیلی کمتر."},{"de":"Auch das Medium spielt eine Rolle: Am Telefon und in Textnachrichten lügen Menschen leichter als im direkten Gespräch.","fa":"رسانه هم نقش دارد: مردم پشت تلفن و در پیام‌های متنی راحت‌تر از گفت‌وگوی رودررو دروغ می‌گویند."},{"de":"Der Grund ist wohl, dass uns im persönlichen Kontakt die Stimme und die Körpersprache schnell verraten können.","fa":"دلیلش احتمالاً این است که در ارتباط حضوری، صدا و زبان بدن ممکن است زود ما را لو بدهند."},{"de":"Aber warum lügen wir überhaupt so oft?","fa":"اما اصلاً چرا این‌قدر زیاد دروغ می‌گوییم؟"},{"de":"Die meisten Lügen sind keine großen Betrügereien, sondern kleine Notlügen.","fa":"بیشتر دروغ‌ها کلاه‌برداری‌های بزرگ نیستند، بلکه دروغ‌های مصلحتی کوچک‌اند."},{"de":"Wir sagen „Mir geht es gut“, obwohl wir müde sind, damit das Gespräch angenehm bleibt.","fa":"می‌گوییم «حالم خوب است»، با اینکه خسته‌ایم، تا گفت‌وگو دلپذیر بماند."},{"de":"Psychologen nennen solche Lügen prosozial, weil sie das Zusammenleben erleichtern und Beziehungen erhalten.","fa":"روان‌شناسان چنین دروغ‌هایی را «جامعه‌پسند» می‌نامند، چون زندگی جمعی را آسان‌تر می‌کنند و رابطه‌ها را حفظ می‌کنند."},{"de":"Andere Lügen sind dagegen eher egoistisch.","fa":"در مقابل، دروغ‌های دیگر بیشتر خودخواهانه‌اند."},{"de":"Fast jeder Vierte räumte zum Beispiel ein, im Lebenslauf schon einmal etwas schöner dargestellt zu haben, um eine Stelle zu bekommen.","fa":"برای نمونه، تقریباً از هر چهار نفر یک نفر پذیرفت که برای گرفتن یک شغل، چیزی را در رزومه‌اش بهتر از واقعیت جلوه داده است."},{"de":"Solche Beschönigungen können jedoch großen Schaden anrichten, wenn sie entdeckt werden.","fa":"اما چنین زیباسازی‌هایی اگر آشکار شوند، می‌توانند آسیب بزرگی بزنند."},{"de":"Mein Fazit lautet deshalb: Kleine Notlügen gehören zum Miteinander, bei egoistischen Lügen sollten wir dagegen vorsichtig sein.","fa":"پس نتیجه‌گیری من این است: دروغ‌های مصلحتی کوچک بخشی از زندگی با دیگران است، اما در مورد دروغ‌های خودخواهانه باید محتاط باشیم."},{"de":"Vielen Dank, und jetzt bin ich gespannt auf Ihre Fragen.","fa":"خیلی ممنونم، و حالا مشتاق شنیدن پرسش‌های شما هستم."}],"q":[{"q":"Wie viele Befragte haben zugegeben, am Vortag gelogen zu haben?","opts":["Etwa ein Zehntel.","Alle Befragten.","Mehr als die Hälfte."],"a":2,"fa":"سخنران گفت «بیش از نیمی» از پاسخ‌دهندگان به دروغ گفتن در روز قبل اعتراف کردند."},{"q":"Was zeigt der Vergleich der Altersgruppen?","opts":["Jüngere Menschen gaben deutlich häufiger eine Lüge zu.","Ältere Menschen gaben häufiger eine Lüge zu.","Es gab keinen Unterschied."],"a":0,"fa":"جوان‌ترها تقریباً هفتاد درصد و افراد بالای شصت سال فقط نزدیک سی درصد."},{"q":"Wen belügen wir laut Umfrage am häufigsten?","opts":["Flüchtige Bekannte.","Enge Freunde.","Unsere Eltern."],"a":0,"fa":"گفته شد بیشتر از همه به «آشنایان دور» دروغ می‌گوییم و به دوستان نزدیک خیلی کمتر."},{"q":"Warum lügen Menschen am Telefon leichter?","opts":["Weil Stimme und Körpersprache uns im persönlichen Gespräch verraten können.","Weil Telefongespräche kürzer sind.","Weil man am Telefon schneller vergisst."],"a":0,"fa":"دلیل احتمالی این است که در ارتباط حضوری، صدا و زبان بدن ما را لو می‌دهند."},{"q":"Was versteht man unter prosozialen Lügen?","opts":["Lügen im Lebenslauf.","Lügen, mit denen man Geld verdient.","Lügen, die das Zusammenleben erleichtern."],"a":2,"fa":"دروغ‌های جامعه‌پسند زندگی جمعی را آسان‌تر می‌کنند و رابطه‌ها را حفظ می‌کنند؛ دروغ در رزومه نمونهٔ دروغ خودخواهانه است."},{"q":"Was ist das Fazit des Redners?","opts":["Man sollte niemals lügen.","Egoistische Lügen sind harmlos.","Kleine Notlügen sind normal, bei egoistischen Lügen ist Vorsicht nötig."],"a":2,"fa":"او گفت دروغ‌های مصلحتی کوچک بخشی از زندگی جمعی است، اما در دروغ‌های خودخواهانه باید محتاط بود."}]},{"id":"h3","type":"Podcast-Folge","title":"Abschreiben verboten: Plagiate im Studium","title_fa":"رونویسی ممنوع: سرقت علمی در دانشگاه","intro_fa":"یک مشاور نگارش در پادکست مرکز نگارش دانشگاه توضیح می‌دهد سرقت علمی چیست، چرا رخ می‌دهد و دانشجویان چگونه می‌توانند از آن پرهیز کنند.","s":[{"de":"Willkommen beim Podcast unserer Schreibwerkstatt, ich bin Jonas und berate seit sechs Jahren Studierende beim Schreiben.","fa":"به پادکست کارگاه نگارش ما خوش آمدید؛ من یوناس هستم و شش سال است که به دانشجویان در نوشتن مشاوره می‌دهم."},{"de":"Heute geht es um ein heikles Thema: Plagiate, also das Übernehmen fremder Gedanken oder Formulierungen, ohne die Quelle zu nennen.","fa":"امروز دربارهٔ موضوعی حساس صحبت می‌کنیم: سرقت علمی، یعنی برداشتن افکار یا جمله‌بندی‌های دیگران بدون ذکر منبع."},{"de":"Zuerst kurz zu unserem Angebot: Wir schreiben keine Texte für euch, sondern geben Tipps und beantworten eure Fragen.","fa":"اول کوتاه دربارهٔ خدمات ما: ما به‌جای شما متن نمی‌نویسیم، بلکه راهنمایی می‌کنیم و به پرسش‌هایتان پاسخ می‌دهیم."},{"de":"Die Beratung ist kostenlos und wird von speziell ausgebildeten Studierenden aus höheren Semestern durchgeführt.","fa":"مشاوره رایگان است و دانشجویان ترم‌های بالاتر که آموزش ویژه دیده‌اند آن را انجام می‌دهند."},{"de":"Viele, die zu uns kommen, sind beim Thema Plagiat sehr unsicher.","fa":"بسیاری از کسانی که پیش ما می‌آیند، در موضوع سرقت علمی خیلی نامطمئن‌اند."},{"de":"Das liegt meistens nicht daran, dass sie betrügen wollen, sondern daran, dass sie nicht genau wissen, wie man korrekt zitiert.","fa":"علتش معمولاً این نیست که می‌خواهند تقلب کنند، بلکه این است که دقیقاً نمی‌دانند چطور باید درست نقل‌قول کرد."},{"de":"Wann muss ich eine Quelle angeben, und wann ist etwas Allgemeinwissen?","fa":"چه وقت باید منبع را ذکر کنم و چه وقت چیزی دانش عمومی است؟"},{"de":"Solche Fragen klären wir gemeinsam, damit niemand aus Versehen ein Plagiat abgibt.","fa":"چنین پرسش‌هایی را با هم روشن می‌کنیم تا هیچ‌کس ناخواسته کاری کپی‌شده تحویل ندهد."},{"de":"Natürlich gibt es aber auch Fälle, in denen bewusst getäuscht wird.","fa":"اما طبیعتاً مواردی هم هست که در آن‌ها آگاهانه فریبکاری می‌شود."},{"de":"Bei einer anonymen Befragung an mehreren Hochschulen gab etwa jeder sechste Studierende zu, schon einmal Textstellen ohne Quellenangabe kopiert zu haben.","fa":"در یک نظرسنجی ناشناس در چند دانشگاه، تقریباً از هر شش دانشجو یک نفر اعتراف کرد که دست‌کم یک بار بخش‌هایی از متنی را بدون ذکر منبع کپی کرده است."},{"de":"Als Motive wurden vor allem Zeitdruck und schlechte Planung genannt.","fa":"به‌عنوان انگیزه، بیش از همه به کمبود وقت و برنامه‌ریزی ضعیف اشاره شد."},{"de":"Viele glauben außerdem, dass ihre eigenen Formulierungen nicht gut genug sind, während die Sätze aus Fachbüchern viel professioneller klingen.","fa":"علاوه بر این، بسیاری فکر می‌کنند جمله‌بندی‌های خودشان به اندازهٔ کافی خوب نیست، در حالی که جمله‌های کتاب‌های تخصصی خیلی حرفه‌ای‌تر به نظر می‌رسند."},{"de":"Dabei wird im Grundstudium gar nicht erwartet, dass man völlig neue, geniale Ideen präsentiert.","fa":"در حالی که در دورهٔ پایه اصلاً انتظار نمی‌رود که آدم ایده‌های کاملاً تازه و نبوغ‌آمیز ارائه کند."},{"de":"Stattdessen sollt ihr zeigen, dass ihr die vorhandene Fachliteratur versteht, zusammenfassen und kritisch diskutieren könnt.","fa":"به‌جای آن باید نشان دهید که منابع تخصصی موجود را می‌فهمید و می‌توانید آن‌ها را خلاصه کنید و نقادانه بررسی کنید."},{"de":"Ein Plagiat ist also nicht nur unehrlich, sondern auch unnötig.","fa":"پس سرقت علمی نه تنها کاری غیرصادقانه، بلکه غیرضروری هم هست."},{"de":"Außerdem wird es heute leicht entdeckt, denn die meisten Hochschulen prüfen Hausarbeiten mit spezieller Software.","fa":"علاوه بر این، امروزه به‌راحتی کشف می‌شود، چون بیشتر دانشگاه‌ها مقاله‌های درسی را با نرم‌افزار ویژه بررسی می‌کنند."},{"de":"Die Folgen können ernst sein: Die Arbeit wird als nicht bestanden bewertet, und im schlimmsten Fall wird man exmatrikuliert.","fa":"پیامدها می‌تواند جدی باشد: کار مردود اعلام می‌شود و در بدترین حالت دانشجو از دانشگاه اخراج می‌شود."},{"de":"Mein wichtigster Rat lautet: Notiert schon beim Lesen zu jedem Gedanken sofort die Quelle mit Seitenzahl.","fa":"مهم‌ترین توصیهٔ من این است: همان هنگام خواندن، برای هر ایده فوراً منبع را همراه با شمارهٔ صفحه یادداشت کنید."},{"de":"Fangt außerdem früh genug an, um am Ende nicht in Panik zu geraten.","fa":"همچنین به اندازهٔ کافی زود شروع کنید تا در پایان دچار وحشت نشوید."},{"de":"Und vergesst nicht, dass das Schreiben selbst eine sehr gute Lernmethode ist, weil man den Stoff dabei gründlich durchdenkt.","fa":"و فراموش نکنید که خود نوشتن روش یادگیری بسیار خوبی است، چون در حین آن مطلب را عمیقاً بررسی می‌کنید."},{"de":"Wer also ehrlich schreibt, bereitet sich gleichzeitig auf die Prüfungen vor.","fa":"پس کسی که صادقانه می‌نویسد، هم‌زمان برای امتحان‌ها هم آماده می‌شود."},{"de":"Unsere Sprechstunden findet ihr auf der Webseite der Schreibwerkstatt, kommt einfach vorbei!","fa":"ساعت‌های مشاورهٔ ما را در وب‌سایت کارگاه نگارش پیدا می‌کنید؛ راحت سری به ما بزنید!"}],"q":[{"q":"Welche Unterstützung bietet die Schreibwerkstatt an?","opts":["Dort beraten nur Professoren.","Sie schreibt Hausarbeiten für die Studierenden.","Sie gibt Tipps und beantwortet Fragen."],"a":2,"fa":"یوناس گفت «ما به‌جای شما متن نمی‌نویسیم، بلکه راهنمایی می‌کنیم»؛ مشاوران دانشجویان ترم بالا هستند."},{"q":"Warum sind viele Studierende beim Thema Plagiat unsicher?","opts":["Weil sie Angst vor der Software haben.","Weil sie absichtlich betrügen wollen.","Weil sie nicht genau wissen, wie man korrekt zitiert."],"a":2,"fa":"علت معمولاً این است که «دقیقاً نمی‌دانند چطور باید درست نقل‌قول کرد»، نه قصد تقلب."},{"q":"Was ergab die anonyme Befragung?","opts":["Jeder zweite Studierende hat schon einmal betrogen.","Niemand hat jemals Textstellen kopiert.","Etwa jeder sechste hat schon einmal ohne Quellenangabe kopiert."],"a":2,"fa":"طبق نظرسنجی، «تقریباً از هر شش دانشجو یک نفر» بدون ذکر منبع کپی کرده است."},{"q":"Welche Motive für Plagiate werden vor allem genannt?","opts":["Zeitdruck und schlechte Planung.","Geldprobleme.","Langeweile und fehlendes Interesse."],"a":0,"fa":"به‌عنوان انگیزه بیش از همه به «کمبود وقت و برنامه‌ریزی ضعیف» اشاره شد."},{"q":"Was wird von Studierenden im Grundstudium erwartet?","opts":["Völlig neue, geniale Ideen.","Die Fachliteratur zu verstehen, zusammenzufassen und kritisch zu diskutieren.","Möglichst viele Sätze aus Fachbüchern zu übernehmen."],"a":1,"fa":"گفته شد ایدهٔ نبوغ‌آمیز انتظار نمی‌رود، بلکه درک، خلاصه کردن و بررسی نقادانهٔ منابع موجود."},{"q":"Was ist der wichtigste Rat von Jonas?","opts":["Schon beim Lesen sofort die Quelle mit Seitenzahl zu notieren.","Die Quellen erst am Ende zu suchen.","Ohne Quellen zu schreiben, um Zeit zu sparen."],"a":0,"fa":"مهم‌ترین توصیه این بود که همان هنگام خواندن، منبع را با شمارهٔ صفحه یادداشت کنید."}]}],"4":[{"id":"h1","type":"Präsentation","title":"Lernbrücke – ein Start-up stellt sich vor","title_fa":"لرن‌بروکه – معرفی یک استارت‌آپ","intro_fa":"یکی از بنیان‌گذاران یک پلتفرم آنلاین تدریس خصوصی، در غرفهٔ شرکتش در یک نمایشگاه کار، شرکت و فرصت‌های شغلی آن را معرفی می‌کند.","s":[{"de":"Guten Tag und herzlich willkommen an unserem Stand hier auf der Jobmesse.","fa":"روز بخیر، به غرفهٔ ما در این نمایشگاه کار خیلی خوش آمدید."},{"de":"Mein Name ist Jonas Berger, und ich bin einer der beiden Gründer von Lernbrücke, einer Online-Plattform für Nachhilfe.","fa":"اسم من یوناس برگر است و یکی از دو بنیان‌گذار «لرن‌بروکه» هستم؛ یک پلتفرم آنلاین برای تدریس خصوصی."},{"de":"Zuerst ein paar Worte zu mir: Nach meinem Studium habe ich drei Jahre bei einer großen Softwarefirma gearbeitet, deren Produkte Sie wahrscheinlich alle kennen.","fa":"اول چند کلمه دربارهٔ خودم: بعد از تحصیلاتم سه سال در یک شرکت بزرگ نرم‌افزاری کار کردم که احتمالاً همهٔ شما محصولاتش را می‌شناسید."},{"de":"Dort habe ich Apps für Banken entwickelt, was technisch spannend war, mich aber nie wirklich begeistert hat.","fa":"آنجا برای بانک‌ها اپلیکیشن طراحی می‌کردم؛ کاری که از نظر فنی جذاب بود، ولی هیچ‌وقت واقعاً مرا به وجد نیاورد."},{"de":"Die Idee zu Lernbrücke hatte meine Schwester, die damals als Mathematiklehrerin an einem Gymnasium unterrichtete.","fa":"ایدهٔ لرن‌بروکه از خواهرم بود که آن موقع معلم ریاضی یک دبیرستان بود."},{"de":"Sie hat oft erzählt, dass viele Eltern eine gute Nachhilfe für ihre Kinder suchen, aber niemanden finden.","fa":"او اغلب تعریف می‌کرد که بسیاری از والدین دنبال یک معلم خصوصی خوب برای بچه‌هایشان می‌گردند، اما کسی را پیدا نمی‌کنند."},{"de":"Gleichzeitig gibt es Tausende Studierende, die gern unterrichten würden und dafür einen flexiblen Nebenjob brauchen.","fa":"در عین حال هزاران دانشجو هستند که دوست دارند تدریس کنند و برای این کار به یک شغل پاره‌وقت انعطاف‌پذیر نیاز دارند."},{"de":"Genau das ist der Punkt, worauf unsere Plattform aufbaut: Wir bringen beide Seiten online zusammen.","fa":"پلتفرم ما دقیقاً بر همین نکته بنا شده است: ما دو طرف را به‌صورت آنلاین به هم وصل می‌کنیم."},{"de":"Heute sind bei uns rund 4000 Lehrkräfte registriert, die Unterricht in über 30 Fächern anbieten.","fa":"امروز حدود ۴۰۰۰ معلم در سایت ما ثبت‌نام کرده‌اند که در بیش از ۳۰ درس کلاس ارائه می‌دهند."},{"de":"Unsere Hauptkunden sind Familien mit Schulkindern, aber immer mehr Erwachsene buchen bei uns auch Sprachkurse oder Prüfungsvorbereitung.","fa":"مشتریان اصلی ما خانواده‌هایی با بچه‌های مدرسه‌ای هستند، اما بزرگسالان بیشتر و بیشتری هم از طریق ما کلاس زبان یا آمادگی آزمون رزرو می‌کنند."},{"de":"Der Unterricht findet per Videochat statt, wobei beide gemeinsam auf einer digitalen Tafel schreiben können.","fa":"کلاس‌ها از طریق تماس تصویری برگزار می‌شوند و هر دو طرف می‌توانند با هم روی یک تختهٔ دیجیتال بنویسند."},{"de":"Neu ist eine Funktion, mit der die Eltern nach jeder Stunde eine kurze Einschätzung zum Lernfortschritt erhalten.","fa":"قابلیت جدید ما امکانی است که با آن والدین بعد از هر جلسه یک ارزیابی کوتاه از پیشرفت درسی دریافت می‌کنند."},{"de":"Natürlich spielt auch der Datenschutz eine große Rolle, denn wir arbeiten mit Minderjährigen, deren Daten besonders geschützt werden müssen.","fa":"البته حفاظت از داده‌ها هم نقش بزرگی دارد، چون ما با افراد زیر سن قانونی کار می‌کنیم که داده‌هایشان باید به‌طور ویژه محافظت شود."},{"de":"Alle Daten werden deshalb ausschließlich auf Servern in Deutschland gespeichert.","fa":"به همین دلیل همهٔ داده‌ها فقط روی سرورهایی در آلمان ذخیره می‌شوند."},{"de":"Im letzten Jahr hat sich unser Umsatz verdoppelt, und deshalb wollen wir unser Team jetzt deutlich vergrößern.","fa":"سال گذشته فروش ما دو برابر شد و به همین دلیل حالا می‌خواهیم تیممان را به‌طور چشمگیری بزرگ‌تر کنیم."},{"de":"Damit komme ich zu dem, was Sie wahrscheinlich am meisten interessiert: unseren offenen Stellen.","fa":"با این توضیح می‌رسم به چیزی که احتمالاً بیشتر از همه برایتان جالب است: فرصت‌های شغلی خالی ما."},{"de":"Wir suchen zwei Softwareentwickler, die Erfahrung mit mobilen Anwendungen haben und gern im Team arbeiten.","fa":"ما دنبال دو برنامه‌نویس هستیم که در زمینهٔ اپلیکیشن‌های موبایل تجربه داشته باشند و کار تیمی را دوست داشته باشند."},{"de":"Außerdem brauchen wir Verstärkung im Kundenservice, wo man vor allem Eltern berät und Fragen zur Buchung beantwortet.","fa":"علاوه بر این در بخش خدمات مشتریان به نیروی کمکی نیاز داریم؛ جایی که آدم بیشتر والدین را راهنمایی می‌کند و به سؤال‌ها دربارهٔ رزرو جواب می‌دهد."},{"de":"Für unser Marketing-Team suchen wir jemanden, der kreativ ist und gern Beiträge in sozialen Netzwerken postet.","fa":"برای تیم بازاریابی‌مان دنبال کسی هستیم که خلاق باشد و دوست داشته باشد در شبکه‌های اجتماعی مطلب پست کند."},{"de":"Wenn Sie Fragen haben, kommen Sie gern nach der Präsentation zu mir oder zu meiner Kollegin an den Stand.","fa":"اگر سؤالی دارید، بعد از ارائه با کمال میل پیش من یا همکارم به غرفه بیایید."},{"de":"Vielen Dank für Ihre Aufmerksamkeit!","fa":"از توجه شما بسیار سپاسگزارم!"}],"q":[{"q":"Was hat Jonas Berger vor der Gründung von Lernbrücke gemacht?","opts":["Er hat als Mathematiklehrer gearbeitet.","Er hat Apps für Banken entwickelt.","Er hat Nachhilfe für Schüler gegeben."],"a":1,"fa":"او گفت که سه سال در یک شرکت نرم‌افزاری برای بانک‌ها اپلیکیشن طراحی می‌کرد؛ معلم ریاضی خواهرش بود."},{"q":"Von wem stammt die Idee für die Plattform?","opts":["Von Eltern, die Nachhilfe suchten.","Von seiner Schwester, einer Lehrerin.","Von einem Kollegen aus der Softwarefirma."],"a":1,"fa":"«ایدهٔ لرن‌بروکه از خواهرم بود که معلم ریاضی بود.»"},{"q":"Wer sind die wichtigsten Kunden von Lernbrücke?","opts":["Studierende, die einen Nebenjob suchen.","Familien mit Kindern, die zur Schule gehen.","Erwachsene, die Sprachkurse buchen."],"a":1,"fa":"مشتریان اصلی خانواده‌هایی با بچه‌های مدرسه‌ای هستند؛ بزرگسالان فقط «بیشتر و بیشتر» اضافه می‌شوند."},{"q":"Was ist neu auf der Plattform?","opts":["Unterricht in über 30 Fächern.","Eine kurze Rückmeldung für die Eltern nach jeder Stunde.","Eine digitale Tafel für den Unterricht."],"a":1,"fa":"قابلیت جدید این است که والدین بعد از هر جلسه یک ارزیابی کوتاه از پیشرفت درسی می‌گیرند."},{"q":"Wo werden die Daten der Nutzer gespeichert?","opts":["Bei einer großen Softwarefirma.","Nur auf Servern in Deutschland.","Auf den Computern der Lehrkräfte."],"a":1,"fa":"«همهٔ داده‌ها فقط روی سرورهایی در آلمان ذخیره می‌شوند.»"},{"q":"Was gehört zu den Aufgaben im Kundenservice?","opts":["Eltern beraten und Fragen zur Buchung beantworten.","Mobile Anwendungen entwickeln.","Beiträge in sozialen Netzwerken posten."],"a":0,"fa":"در خدمات مشتریان بیشتر والدین را راهنمایی می‌کنند و به سؤال‌های رزرو جواب می‌دهند؛ پست کردن کار تیم بازاریابی است."}]},{"id":"h2","type":"Vortrag","title":"Ein Roboter, der für kranke Kinder in die Schule geht","title_fa":"رباتی که به جای کودکان بیمار به مدرسه می‌رود","intro_fa":"مدیر یک پروژه در یک دورهٔ آموزشی برای معلمان، یک ربات حضور از راه دور را معرفی می‌کند که به دانش‌آموزان بیمار کمک می‌کند در کلاس حاضر باشند.","s":[{"de":"Liebe Lehrerinnen und Lehrer, heute stelle ich Ihnen ein Projekt vor, an dem wir seit drei Jahren arbeiten.","fa":"معلمان عزیز، امروز پروژه‌ای را به شما معرفی می‌کنم که سه سال است روی آن کار می‌کنیم."},{"de":"Es geht um Kinder und Jugendliche, die wegen einer schweren Erkrankung monatelang nicht in die Schule gehen können.","fa":"موضوع کودکان و نوجوانانی است که به دلیل یک بیماری سخت، ماه‌ها نمی‌توانند به مدرسه بروند."},{"de":"Viele denken zuerst an die medizinische Behandlung, doch die Betroffenen erzählen uns etwas anderes.","fa":"بسیاری اول به درمان پزشکی فکر می‌کنند، اما خود این بچه‌ها چیز دیگری به ما می‌گویند."},{"de":"Am meisten leiden sie darunter, dass der Kontakt zu ihrer Klasse verloren geht und sie sich isoliert fühlen.","fa":"بیشترین رنجشان از این است که ارتباطشان با همکلاسی‌ها قطع می‌شود و احساس تنهایی و انزوا می‌کنند."},{"de":"Genau hier setzt unser Telepräsenzroboter an, den wir kurz Max nennen.","fa":"ربات حضور از راه دور ما، که به اختصار «ماکس» صدایش می‌کنیم، دقیقاً همین‌جا وارد عمل می‌شود."},{"de":"Max ist etwa 30 Zentimeter groß und hat eine Kamera, ein Mikrofon und einen Lautsprecher.","fa":"ماکس حدود ۳۰ سانتی‌متر قد دارد و یک دوربین، یک میکروفون و یک بلندگو دارد."},{"de":"Er steht im Klassenzimmer auf dem Platz des kranken Kindes, das ihn von zu Hause oder vom Krankenhaus aus mit einer App steuert.","fa":"او در کلاس سر جای کودک بیمار قرار می‌گیرد و کودک از خانه یا بیمارستان با یک اپلیکیشن او را کنترل می‌کند."},{"de":"So kann das Kind dem Unterricht live folgen, sich melden und Fragen stellen, als ob es selbst im Raum wäre.","fa":"به این ترتیب کودک می‌تواند کلاس را زنده دنبال کند، دست بلند کند و سؤال بپرسد، انگار که خودش در کلاس است."},{"de":"Der Roboter lernt also nicht für das Kind, sondern er ermöglicht ihm, aktiv am Unterricht teilzunehmen.","fa":"پس ربات به جای کودک درس نمی‌خواند، بلکه به او امکان می‌دهد فعالانه در کلاس شرکت کند."},{"de":"Das Besondere daran ist, dass die Kommunikation in beide Richtungen funktioniert: Das Kind sieht die Klasse, und die Klasse hört das Kind.","fa":"نکتهٔ ویژه این است که ارتباط دوطرفه است: کودک کلاس را می‌بیند و کلاس صدای کودک را می‌شنود."},{"de":"Ein Bild des Kindes wird allerdings nicht übertragen, was vielen Patienten wichtig ist.","fa":"البته تصویر کودک منتقل نمی‌شود؛ چیزی که برای بسیاری از بیماران مهم است."},{"de":"Wenn das Kind eine Pause braucht, schaltet es eine blaue Lampe ein, die bedeutet: Ich mache Pause, bin aber noch dabei.","fa":"وقتی کودک به استراحت نیاز دارد، یک چراغ آبی روشن می‌کند که معنایش این است: دارم استراحت می‌کنم، ولی هنوز اینجا هستم."},{"de":"Auch außerhalb des Unterrichts kann Max eingesetzt werden, zum Beispiel bei einem Schulausflug, wohin die Mitschüler ihn mitnehmen.","fa":"از ماکس بیرون از کلاس هم می‌شود استفاده کرد، مثلاً در یک اردوی مدرسه، که همکلاسی‌ها او را با خود می‌برند."},{"de":"Ein Roboter kostet etwa 3500 Euro, und dazu kommen monatliche Gebühren für die Datenübermittlung.","fa":"هر ربات حدود ۳۵۰۰ یورو قیمت دارد و هزینه‌های ماهانه برای انتقال داده هم به آن اضافه می‌شود."},{"de":"Das ist viel Geld, aber ein Gerät kann nacheinander von mehreren Kindern genutzt werden.","fa":"این پول زیادی است، اما یک دستگاه را چند کودک می‌توانند پشت سر هم استفاده کنند."},{"de":"In vielen Fällen übernehmen Stiftungen oder Elternvereine die Kosten, sodass für die Schule kaum Ausgaben entstehen.","fa":"در بسیاری از موارد بنیادهای خیریه یا انجمن‌های اولیا هزینه را می‌پردازند، طوری که برای مدرسه تقریباً هزینه‌ای پیش نمی‌آید."},{"de":"Die Erfahrungen, worüber uns Lehrkräfte berichten, sind fast ausschließlich positiv.","fa":"تجربه‌هایی که معلمان دربارهٔ آن به ما گزارش می‌دهند تقریباً همه مثبت است."},{"de":"Die kranken Schüler verpassen weniger Stoff, und die Rückkehr in die Klasse fällt ihnen deutlich leichter.","fa":"دانش‌آموزان بیمار درس کمتری از دست می‌دهند و بازگشت به کلاس برایشان خیلی آسان‌تر است."},{"de":"Mit meinem Vortrag möchte ich Sie vor allem darüber informieren, welche Hilfen es für Ihre kranken Schüler gibt.","fa":"با این سخنرانی بیشتر می‌خواهم شما را در جریان بگذارم که چه کمک‌هایی برای دانش‌آموزان بیمارتان وجود دارد."},{"de":"Auf unserer Website erfahren Sie, wie Sie einen Roboter für Ihre Schule beantragen können.","fa":"در وب‌سایت ما می‌فهمید که چطور می‌توانید برای مدرسه‌تان درخواست ربات بدهید."}],"q":[{"q":"Was ist nach Aussage der Rednerin das größte Problem für langzeitkranke Kinder?","opts":["Die medizinische Behandlung.","Der fehlende Kontakt zur Klasse.","Der lange Weg zum Krankenhaus."],"a":1,"fa":"او گفت بچه‌ها بیشتر از همه از قطع ارتباط با کلاس و احساس انزوا رنج می‌برند، نه از درمان."},{"q":"Wie hilft der Roboter den Kindern beim Lernen?","opts":["Er ermöglicht dem Kind, aktiv am Unterricht teilzunehmen.","Er macht die Hausaufgaben für das Kind.","Er erklärt dem Kind den Stoff noch einmal."],"a":0,"fa":"«ربات به جای کودک درس نمی‌خواند، بلکه به او امکان می‌دهد فعالانه در کلاس شرکت کند.»"},{"q":"Was wird vom kranken Kind nicht übertragen?","opts":["Seine Fragen.","Seine Stimme.","Sein Bild."],"a":2,"fa":"تصویر کودک منتقل نمی‌شود؛ کلاس فقط صدای او را می‌شنود."},{"q":"Was bedeutet die blaue Lampe am Roboter?","opts":["Das Kind macht eine Pause, ist aber noch verbunden.","Das Kind möchte etwas fragen.","Die Internetverbindung ist unterbrochen."],"a":0,"fa":"چراغ آبی یعنی: «دارم استراحت می‌کنم، ولی هنوز اینجا هستم.»"},{"q":"Was sagt die Rednerin zu den Kosten?","opts":["Die Schulen müssen alle Kosten selbst tragen.","Sie sind hoch, aber oft bezahlen Stiftungen oder Elternvereine.","Sie sind so niedrig, dass jede Schule einen Roboter kaufen kann."],"a":1,"fa":"او قبول دارد که ۳۵۰۰ یورو پول زیادی است، اما می‌گوید اغلب بنیادها یا انجمن‌های اولیا هزینه را می‌پردازند."},{"q":"Welches Ziel hat der Vortrag?","opts":["Über technische Probleme mit dem Roboter zu diskutieren.","Lehrkräfte über Hilfen für kranke Schüler zu informieren.","Roboter an Eltern zu verkaufen."],"a":1,"fa":"در پایان خودش می‌گوید هدفش آگاه کردن معلمان از کمک‌های موجود برای دانش‌آموزان بیمار است."}]},{"id":"h3","type":"Erklärvideo-Text","title":"Telemedizin – Für und Wider","title_fa":"پزشکی از راه دور – موافق و مخالف","intro_fa":"گویندهٔ یک ویدیوی آموزشی توضیح می‌دهد پزشکی از راه دور چیست و چه مزایا و معایبی دارد.","s":[{"de":"Hallo und willkommen zu unserem Erklärvideo, in dem es heute um Telemedizin geht.","fa":"سلام و به ویدیوی آموزشی ما خوش آمدید؛ موضوع امروز پزشکی از راه دور است."},{"de":"Was ist Telemedizin eigentlich?","fa":"اصلاً پزشکی از راه دور چیست؟"},{"de":"Damit ist gemeint, dass Ärzte digitale Technologien einsetzen, um Patienten zu beraten oder zu behandeln, ohne dass beide am selben Ort sind.","fa":"منظور این است که پزشکان از فناوری‌های دیجیتال استفاده می‌کنند تا بیماران را راهنمایی یا درمان کنند، بدون اینکه هر دو در یک مکان باشند."},{"de":"Das bekannteste Beispiel ist die Videosprechstunde, bei der man per Videochat mit seiner Ärztin über seine Beschwerden spricht.","fa":"شناخته‌شده‌ترین نمونه، ویزیت تصویری است که در آن آدم از طریق تماس تصویری با پزشکش دربارهٔ ناراحتی‌هایش صحبت می‌کند."},{"de":"Aber auch Fitnessarmbänder, deren Daten automatisch an eine Praxis geschickt werden, gehören dazu.","fa":"اما مچ‌بندهای ورزشی هوشمند هم که داده‌هایشان خودکار به مطب فرستاده می‌شود، جزو آن هستند."},{"de":"Kommen wir zuerst zu den Vorteilen.","fa":"اول برویم سراغ مزایا."},{"de":"Der größte Nutzen zeigt sich auf dem Land, wo es immer weniger Arztpraxen gibt und die Wege oft sehr weit sind.","fa":"بیشترین فایده در روستاها و شهرهای کوچک دیده می‌شود، جایی که مطب‌ها روزبه‌روز کمتر می‌شوند و راه‌ها اغلب خیلی طولانی است."},{"de":"Patienten sparen Zeit, weil sie nicht stundenlang im Wartezimmer sitzen müssen.","fa":"بیماران در وقت صرفه‌جویی می‌کنند، چون لازم نیست ساعت‌ها در اتاق انتظار بنشینند."},{"de":"Außerdem stecken sie sich dort nicht bei anderen Kranken an, was besonders für ältere Menschen wichtig ist.","fa":"علاوه بر این، آنجا از بیماران دیگر بیماری نمی‌گیرند؛ چیزی که مخصوصاً برای سالمندان مهم است."},{"de":"Bei chronischen Erkrankungen wie Diabetes können wichtige Werte regelmäßig von zu Hause aus übermittelt werden.","fa":"در بیماری‌های مزمن مثل دیابت می‌توان شاخص‌های مهم را به‌طور منظم از خانه ارسال کرد."},{"de":"Verschlechtern sich die Werte, kann der Arzt schnell reagieren, bevor ein Notfall entsteht.","fa":"اگر این شاخص‌ها بدتر شوند، پزشک می‌تواند پیش از آنکه وضعیت اورژانسی پیش بیاید سریع واکنش نشان دهد."},{"de":"Und Spezialisten, die in großen Kliniken arbeiten, können Kollegen in kleinen Krankenhäusern bei einer schwierigen Diagnose unterstützen.","fa":"و متخصصانی که در بیمارستان‌های بزرگ کار می‌کنند، می‌توانند در تشخیص‌های دشوار به همکارانشان در بیمارستان‌های کوچک کمک کنند."},{"de":"Doch es gibt auch Nachteile, über die man sprechen muss.","fa":"اما معایبی هم هست که باید درباره‌شان صحبت کرد."},{"de":"Eine Ärztin kann über den Bildschirm nicht alles erkennen, denn sie kann den Patienten weder abhören noch abtasten.","fa":"پزشک از پشت صفحه نمی‌تواند همه چیز را تشخیص دهد، چون نه می‌تواند با گوشی صدای بدن بیمار را بشنود و نه او را معاینهٔ لمسی کند."},{"de":"Manche Symptome werden deshalb falsch eingeschätzt oder gar nicht bemerkt.","fa":"به همین دلیل بعضی علائم اشتباه ارزیابی می‌شوند یا اصلاً دیده نمی‌شوند."},{"de":"Ein weiteres Problem ist die Datensicherheit, da Gesundheitsdaten sehr sensibel sind und gehackt werden können.","fa":"مشکل دیگر امنیت داده‌هاست، چون اطلاعات سلامت بسیار حساس است و ممکن است هک شود."},{"de":"Außerdem haben nicht alle Menschen eine stabile Internetverbindung oder kommen mit der Technik gut zurecht.","fa":"علاوه بر این، همه اینترنت پایدار ندارند یا با فناوری به‌خوبی کنار نمی‌آیند."},{"de":"Gerade ältere Patienten, für die Telemedizin eigentlich besonders nützlich wäre, brauchen oft Hilfe bei der Anwendung.","fa":"مخصوصاً بیماران مسن، که پزشکی از راه دور در واقع برایشان بسیار مفید است، اغلب در استفاده از آن به کمک نیاز دارند."},{"de":"Schließlich fehlt vielen der persönliche Kontakt, was für das Vertrauen zwischen Arzt und Patient sehr wichtig ist.","fa":"و در آخر، خیلی‌ها ارتباط حضوری را کم دارند؛ چیزی که برای اعتماد میان پزشک و بیمار بسیار مهم است."},{"de":"Was ist also unser Fazit?","fa":"خب، نتیجه‌گیری ما چیست؟"},{"de":"Telemedizin kann den Besuch in der Praxis nicht vollständig ersetzen, aber sie ist eine sinnvolle Ergänzung.","fa":"پزشکی از راه دور نمی‌تواند به‌طور کامل جای مراجعه به مطب را بگیرد، اما مکمل مفیدی است."},{"de":"Für Kontrolltermine und einfache Fragen ist sie ideal, bei neuen oder unklaren Beschwerden sollte man aber lieber persönlich zum Arzt gehen.","fa":"برای ویزیت‌های کنترلی و سؤال‌های ساده ایده‌آل است، اما با ناراحتی‌های تازه یا نامشخص بهتر است حضوری پیش پزشک رفت."},{"de":"Danke fürs Zuschauen, und bis zum nächsten Video!","fa":"ممنون که تماشا کردید، تا ویدیوی بعدی!"}],"q":[{"q":"Was versteht man unter Telemedizin?","opts":["Behandlung, bei der Arzt und Patient nicht am selben Ort sind.","Medikamente, die man im Internet bestellt.","Gesundheitstipps in sozialen Netzwerken."],"a":0,"fa":"طبق تعریف ویدیو، پزشک با فناوری دیجیتال بیمار را درمان یا راهنمایی می‌کند بدون اینکه هر دو در یک مکان باشند."},{"q":"Wo ist der Nutzen von Telemedizin besonders groß?","opts":["In großen Städten mit vielen Kliniken.","In Krankenhäusern mit vielen Spezialisten.","Auf dem Land, wo es wenige Arztpraxen gibt."],"a":2,"fa":"«بیشترین فایده در روستاهاست، جایی که مطب‌ها کمتر می‌شوند و راه‌ها طولانی است.»"},{"q":"Welchen Vorteil haben Menschen mit chronischen Erkrankungen?","opts":["Ihre Werte können regelmäßig von zu Hause übermittelt werden.","Sie brauchen keine Medikamente mehr.","Sie bekommen schneller einen Termin bei Spezialisten."],"a":0,"fa":"در بیماری‌های مزمن شاخص‌ها از خانه ارسال می‌شوند و پزشک در صورت بدتر شدن سریع واکنش نشان می‌دهد."},{"q":"Warum kann es bei der Videosprechstunde zu Fehlern kommen?","opts":["Weil die Sprechstunde zu kurz ist.","Weil die Patienten falsche Angaben machen.","Weil die Ärztin den Patienten nicht abhören oder abtasten kann."],"a":2,"fa":"پزشک از پشت صفحه نه می‌تواند صدای بدن را بشنود نه معاینهٔ لمسی کند، پس بعضی علائم دیده نمی‌شوند."},{"q":"Welches Problem wird bei älteren Patienten genannt?","opts":["Sie brauchen oft Hilfe bei der Technik.","Sie lehnen Videosprechstunden grundsätzlich ab.","Sie haben selten chronische Erkrankungen."],"a":0,"fa":"در ویدیو گفته شد سالمندان اغلب در استفاده از این فناوری به کمک نیاز دارند."},{"q":"Was empfiehlt das Video bei neuen oder unklaren Beschwerden?","opts":["Die Werte per App zu schicken.","Persönlich zum Arzt zu gehen.","Eine Videosprechstunde zu buchen."],"a":1,"fa":"نتیجه‌گیری: برای ناراحتی‌های تازه یا نامشخص بهتر است حضوری پیش پزشک رفت."}]}],"5":[{"id":"h1","type":"Radiobeitrag","title":"Meteorologie – vom Telegrafen zum Supercomputer","title_fa":"هواشناسی – از تلگراف تا ابررایانه","intro_fa":"گویندهٔ یک برنامهٔ علمی رادیو دربارهٔ تاریخچهٔ پیش‌بینی هوا، کار سازمان هواشناسی آلمان و اهمیت پیش‌بینی دقیق برای اقتصاد صحبت می‌کند.","s":[{"de":"Willkommen zu unserer Wissenschaftssendung, in der es heute um eine Frage geht, die uns täglich beschäftigt: Wie wird das Wetter?","fa":"به برنامهٔ علمی ما خوش آمدید؛ امروز موضوع سؤالی است که هر روز ذهن ما را مشغول می‌کند: هوا چطور خواهد شد؟"},{"de":"Die Wissenschaft, die sich mit dieser Frage beschäftigt, heißt Meteorologie.","fa":"علمی که به این سؤال می‌پردازد، هواشناسی نام دارد."},{"de":"Der Begriff kommt aus dem Griechischen und bedeutet ungefähr die Lehre von den Erscheinungen in der Luft.","fa":"این واژه از یونانی می‌آید و تقریباً به معنای دانش پدیده‌های جوّی است."},{"de":"Schon in der Antike haben Menschen den Himmel beobachtet, doch echte Vorhersagen waren lange Zeit unmöglich.","fa":"مردم از دوران باستان آسمان را زیر نظر داشتند، اما تا مدت‌ها پیش‌بینی واقعی غیرممکن بود."},{"de":"Erst im neunzehnten Jahrhundert änderte sich das, und zwar durch die Erfindung des Telegrafen.","fa":"این وضعیت تازه در قرن نوزدهم تغییر کرد، آن هم با اختراع تلگراف."},{"de":"Plötzlich konnten Messdaten von vielen Orten gleichzeitig gesammelt werden, sodass man erkennen konnte, wie sich Wetterlagen bewegen.","fa":"ناگهان می‌شد داده‌های اندازه‌گیری را از جاهای مختلف هم‌زمان جمع کرد، طوری که می‌شد دید وضعیت‌های جوّی چطور حرکت می‌کنند."},{"de":"In Deutschland ist heute der Deutsche Wetterdienst mit Sitz in Offenbach für die offizielle Wettervorhersage zuständig.","fa":"امروز در آلمان سازمان هواشناسی آلمان، با مقر در اوفنباخ، مسئول پیش‌بینی رسمی هواست."},{"de":"Er bekommt seine Daten von rund 2000 Messstationen, aber auch von Wetterballons, Radargeräten, Satelliten und sogar von Verkehrsflugzeugen.","fa":"این سازمان داده‌هایش را از حدود ۲۰۰۰ ایستگاه اندازه‌گیری، و همچنین از بالن‌های هواشناسی، رادارها، ماهواره‌ها و حتی هواپیماهای مسافربری می‌گیرد."},{"de":"Gemessen werden unter anderem Temperatur, Luftdruck, Luftfeuchtigkeit und Niederschlag sowie Windrichtung und Windgeschwindigkeit.","fa":"از جمله دما، فشار هوا، رطوبت هوا، بارش و همچنین جهت و سرعت باد اندازه‌گیری می‌شوند."},{"de":"Diese riesigen Datenmengen werden von Supercomputern verarbeitet, die daraus Modelle für die nächsten Tage berechnen.","fa":"این حجم عظیم داده را ابررایانه‌ها پردازش می‌کنند و از آن مدل‌هایی برای روزهای آینده محاسبه می‌کنند."},{"de":"Präzise Vorhersagen sind vor allem für die Wirtschaft wichtig.","fa":"پیش‌بینی دقیق بیش از همه برای اقتصاد مهم است."},{"de":"Landwirte zum Beispiel müssen wissen, ob sie ihr Getreide ernten können, bevor der nächste Regen kommt.","fa":"مثلاً کشاورزان باید بدانند آیا می‌توانند پیش از باران بعدی غلاتشان را برداشت کنند یا نه."},{"de":"Sinken die Temperaturen unter null Grad, müssen die Straßendienste rechtzeitig Salz streuen.","fa":"اگر دما به زیر صفر درجه برسد، خدمات راهداری باید به‌موقع نمک بپاشند."},{"de":"Auch Energieunternehmen sind auf genaue Prognosen angewiesen, denn sie müssen wissen, wie viel Strom Wind- und Solaranlagen am nächsten Tag liefern.","fa":"شرکت‌های انرژی هم به پیش‌بینی دقیق وابسته‌اند، چون باید بدانند توربین‌های بادی و نیروگاه‌های خورشیدی فردا چقدر برق تولید می‌کنند."},{"de":"Und sollte ein Sturm drohen, verschieben Veranstalter große Konzerte oder Sportereignisse.","fa":"و اگر خطر طوفان باشد، برگزارکنندگان کنسرت‌ها یا رویدادهای ورزشی بزرگ را به تعویق می‌اندازند."},{"de":"Wie genau sind die Vorhersagen heute eigentlich?","fa":"حالا پیش‌بینی‌ها امروز واقعاً چقدر دقیق هستند؟"},{"de":"In den sechziger Jahren war eine Prognose für den nächsten Tag ungefähr so zuverlässig wie heute eine Prognose für fünf Tage.","fa":"در دههٔ شصت میلادی، پیش‌بینی برای فردا تقریباً همان‌قدر قابل اعتماد بود که امروز پیش‌بینی برای پنج روز آینده."},{"de":"Eine Vorhersage für drei Tage trifft inzwischen in etwa 90 Prozent der Fälle zu.","fa":"امروزه پیش‌بینی سه‌روزه در حدود ۹۰ درصد موارد درست از آب درمی‌آید."},{"de":"Schwieriger bleibt es bei lokalen Ereignissen wie Hagel oder Starkregen, die oft nur wenige Kilometer betreffen.","fa":"اما در مورد رویدادهای محلی مثل تگرگ یا بارش شدید، که اغلب فقط چند کیلومتر را دربرمی‌گیرند، کار همچنان دشوارتر است."},{"de":"Experten erwarten jedoch, dass künstliche Intelligenz und noch schnellere Computer die Vorhersagen in Zukunft weiter verbessern.","fa":"با این حال کارشناسان انتظار دارند هوش مصنوعی و رایانه‌های سریع‌تر در آینده پیش‌بینی‌ها را باز هم بهتر کنند."},{"de":"Vielleicht wissen wir dann schon zwei Wochen vorher, ob es am Wochenende regnet.","fa":"شاید آن موقع از دو هفته قبل بدانیم که آخر هفته باران می‌آید یا نه."},{"de":"Bis dahin gilt: Wer sicher sein will, nimmt lieber einen Regenschirm mit.","fa":"تا آن زمان یک قاعده برقرار است: هر کس می‌خواهد خیالش راحت باشد، بهتر است چتر همراهش ببرد."}],"q":[{"q":"Was bedeutet das Wort Meteorologie ursprünglich?","opts":["Die Messung von Temperaturen.","Die Lehre von den Erscheinungen in der Luft.","Die Kunst, die Sterne zu beobachten."],"a":1,"fa":"گوینده گفت این واژه از یونانی است و تقریباً یعنی «دانش پدیده‌های جوّی»."},{"q":"Warum wurden im neunzehnten Jahrhundert echte Wettervorhersagen möglich?","opts":["Weil man die ersten Satelliten hatte.","Weil das Thermometer erfunden wurde.","Weil man mit dem Telegrafen Daten von vielen Orten gleichzeitig sammeln konnte."],"a":2,"fa":"با اختراع تلگراف، داده‌ها از جاهای مختلف هم‌زمان جمع می‌شد و حرکت وضعیت هوا قابل دیدن بود."},{"q":"Welche Datenquelle des Deutschen Wetterdienstes wird im Beitrag genannt?","opts":["Private Wetter-Apps.","Verkehrsflugzeuge.","Die Smartphones der Bürger."],"a":1,"fa":"منابع ذکرشده: ایستگاه‌ها، بالن‌ها، رادارها، ماهواره‌ها و «حتی هواپیماهای مسافربری»."},{"q":"Warum brauchen Energieunternehmen genaue Prognosen?","opts":["Um die Strompreise zu senken.","Um zu wissen, wie viel Strom Wind- und Solaranlagen liefern.","Um ihre Kraftwerke vor Stürmen zu schützen."],"a":1,"fa":"آن‌ها باید بدانند توربین‌های بادی و نیروگاه‌های خورشیدی فردا چقدر برق تولید می‌کنند."},{"q":"Wie zuverlässig ist heute eine Vorhersage für drei Tage?","opts":["Sie ist so unsicher wie früher eine Prognose für einen Tag.","Sie stimmt in etwa 90 Prozent der Fälle.","Sie ist nur bei Hagel und Starkregen genau."],"a":1,"fa":"«پیش‌بینی سه‌روزه در حدود ۹۰ درصد موارد درست است.»"},{"q":"Was ist auch heute noch schwer vorherzusagen?","opts":["Der Luftdruck.","Die Temperatur am nächsten Tag.","Lokale Ereignisse wie Hagel oder Starkregen."],"a":2,"fa":"گوینده گفت رویدادهای محلی مثل تگرگ یا بارش شدید همچنان دشوارتر پیش‌بینی می‌شوند."}]},{"id":"h2","type":"Nachrichten","title":"Unwetterwarnung: Orkan über Norddeutschland","title_fa":"هشدار هوای نامساعد: تندباد در شمال آلمان","intro_fa":"گویندهٔ اخبار رادیو دربارهٔ یک طوفان شدید در شمال آلمان و پیامدهای آن برای مدرسه‌ها، قطارها، پروازها و ساحل خبر می‌دهد.","s":[{"de":"Und nun zum Wetter, das heute alle anderen Themen verdrängt.","fa":"و حالا می‌رسیم به وضع هوا که امروز همهٔ موضوعات دیگر را تحت‌الشعاع قرار داده است."},{"de":"Der Deutsche Wetterdienst hat für weite Teile Norddeutschlands die höchste Warnstufe ausgerufen.","fa":"سازمان هواشناسی آلمان برای بخش‌های وسیعی از شمال آلمان بالاترین سطح هشدار را اعلام کرده است."},{"de":"Ab dem frühen Nachmittag zieht ein Sturmtief vom Atlantik heran, und an der Küste werden Orkanböen mit bis zu 140 Kilometern pro Stunde erwartet.","fa":"از اوایل بعدازظهر یک سامانهٔ کم‌فشار طوفانی از اقیانوس اطلس نزدیک می‌شود و در ساحل تندبادهایی با سرعت تا ۱۴۰ کیلومتر در ساعت انتظار می‌رود."},{"de":"Auch im Landesinneren kann der Wind so stark werden, dass Bäume umstürzen und Dächer beschädigt werden.","fa":"در مناطق داخلی هم باد ممکن است آن‌قدر شدید شود که درخت‌ها بیفتند و سقف‌ها آسیب ببینند."},{"de":"Dazu kommen kräftige Regenschauer und einzelne Gewitter, die örtlich auch Hagel bringen können.","fa":"علاوه بر آن رگبارهای شدید و رعدوبرق‌های پراکنده هم پیش‌بینی می‌شود که در بعضی نقاط ممکن است تگرگ هم به همراه داشته باشد."},{"de":"Die Behörden bitten die Bevölkerung deshalb, ab 14 Uhr möglichst zu Hause zu bleiben.","fa":"به همین دلیل مقامات از مردم می‌خواهند از ساعت ۱۴ تا جای ممکن در خانه بمانند."},{"de":"Wer trotzdem unterwegs ist, sollte Wälder und Parks meiden.","fa":"کسی که با این حال بیرون است، باید از جنگل‌ها و پارک‌ها دوری کند."},{"de":"In mehreren Landkreisen an der Küste bleiben die Schulen heute geschlossen, sodass rund achtzigtausend Kinder zu Hause bleiben.","fa":"در چند شهرستان ساحلی مدرسه‌ها امروز تعطیل هستند، به‌طوری که حدود هشتاد هزار کودک در خانه می‌مانند."},{"de":"Die Bahn hat den Fernverkehr zwischen Hamburg und Berlin bereits eingestellt, damit keine Züge auf offener Strecke stehen bleiben.","fa":"راه‌آهن قطارهای مسافت طولانی بین هامبورگ و برلین را از هم‌اکنون متوقف کرده است تا هیچ قطاری وسط مسیر نماند."},{"de":"Auch im Regionalverkehr ist mit erheblichen Verspätungen und Ausfällen zu rechnen.","fa":"در قطارهای منطقه‌ای هم باید منتظر تأخیرها و لغوهای قابل توجه بود."},{"de":"Am Flughafen Hamburg wurden bis jetzt etwa 60 Flüge gestrichen, die übrigen Verbindungen finden vorerst statt.","fa":"در فرودگاه هامبورگ تاکنون حدود ۶۰ پرواز لغو شده است؛ بقیهٔ پروازها فعلاً انجام می‌شوند."},{"de":"Reisende sollten sich vor der Fahrt zum Flughafen im Internet über den Status ihres Fluges informieren.","fa":"مسافران باید پیش از رفتن به فرودگاه وضعیت پروازشان را در اینترنت بررسی کنند."},{"de":"An der Nordseeküste wird außerdem eine Sturmflut erwartet, sodass das Wasser bis zu zwei Meter über den normalen Stand steigen kann.","fa":"علاوه بر این در ساحل دریای شمال انتظار طغیان طوفانی دریا می‌رود، به‌طوری که آب ممکن است تا دو متر بالاتر از سطح عادی برسد."},{"de":"Die Fähren zu den Inseln fahren deshalb seit heute Morgen nicht mehr.","fa":"به همین دلیل کشتی‌های مسافربری به جزیره‌ها از امروز صبح دیگر حرکت نمی‌کنند."},{"de":"Bewohner tief liegender Gebiete werden gebeten, Keller und Garagen zu räumen.","fa":"از ساکنان مناطق کم‌ارتفاع خواسته می‌شود زیرزمین‌ها و پارکینگ‌ها را خالی کنند."},{"de":"Wer Gegenstände auf dem Balkon oder im Garten hat, sollte sie jetzt festbinden oder ins Haus bringen.","fa":"هر کس وسایلی در بالکن یا باغ دارد، باید همین حالا آن‌ها را محکم ببندد یا به داخل خانه ببرد."},{"de":"Die Feuerwehr ist mit zusätzlichen Kräften im Einsatz und bittet darum, den Notruf nur in echten Notfällen zu wählen.","fa":"آتش‌نشانی با نیروی اضافی در حال خدمت است و درخواست می‌کند فقط در موارد واقعاً اضطراری با شمارهٔ اورژانس تماس بگیرید."},{"de":"In der Nacht zieht der Sturm nach Osten weiter, infolgedessen wird es morgen früh auch in Brandenburg und Sachsen sehr stürmisch.","fa":"طوفان شب به سمت شرق می‌رود و در نتیجه فردا صبح در براندنبورگ و زاکسن هم هوا بسیار طوفانی خواهد بود."},{"de":"Erst am Donnerstag beruhigt sich die Lage, sodass dann wieder Sonnenschein und Temperaturen um 12 Grad zu erwarten sind.","fa":"وضعیت تازه روز پنجشنبه آرام می‌شود، به‌طوری که آن موقع دوباره آفتاب و دمای حدود ۱۲ درجه انتظار می‌رود."},{"de":"Meteorologen zufolge ist ein so starker Sturm im Oktober ungewöhnlich, durch den Klimawandel könnten solche Ereignisse aber häufiger werden.","fa":"به گفتهٔ هواشناسان، چنین طوفان شدیدی در ماه اکتبر غیرعادی است، اما ممکن است به دلیل تغییرات اقلیمی این رویدادها بیشتر شوند."},{"de":"Aktuelle Informationen zur Sturmlage hören Sie bei uns jede halbe Stunde.","fa":"اطلاعات تازه دربارهٔ وضعیت طوفان را هر نیم ساعت از ما بشنوید."}],"q":[{"q":"Worum geht es in der Meldung?","opts":["Um einen Rückblick auf das Wetter im letzten Monat.","Um die Folgen einer langen Hitzewelle.","Um eine Warnung vor einem starken Sturm."],"a":2,"fa":"سازمان هواشناسی بالاترین سطح هشدار را به دلیل یک طوفان شدید اعلام کرده است."},{"q":"Was sollen die Menschen ab 14 Uhr tun?","opts":["Möglichst zu Hause bleiben.","In den Wald oder Park gehen.","Zum Flughafen fahren."],"a":0,"fa":"«مقامات از مردم می‌خواهند از ساعت ۱۴ تا جای ممکن در خانه بمانند.»"},{"q":"Was gilt heute für die Schulen?","opts":["Alle Schulen in Deutschland sind geschlossen.","Der Unterricht beginnt zwei Stunden später.","In einigen Landkreisen an der Küste sind die Schulen geschlossen."],"a":2,"fa":"فقط در چند شهرستان ساحلی مدرسه‌ها تعطیل هستند، نه همه‌جا."},{"q":"Was wird über den Flughafen Hamburg gesagt?","opts":["Der Flughafen schließt ab 14 Uhr.","Etwa 60 Flüge fallen aus, die anderen finden vorerst statt.","Alle Flüge sind gestrichen."],"a":1,"fa":"حدود ۶۰ پرواز لغو شده و «بقیهٔ پروازها فعلاً انجام می‌شوند»."},{"q":"Warum fahren die Fähren zu den Inseln nicht?","opts":["Wegen einer erwarteten Sturmflut.","Weil es Gewitter mit Hagel gibt.","Weil die Häfen beschädigt sind."],"a":0,"fa":"در ساحل دریای شمال طغیان طوفانی دریا انتظار می‌رود و «به همین دلیل» کشتی‌ها حرکت نمی‌کنند."},{"q":"Wann soll sich das Wetter wieder beruhigen?","opts":["Am Donnerstag.","Morgen früh.","Heute in der Nacht."],"a":0,"fa":"«وضعیت تازه روز پنجشنبه آرام می‌شود»؛ فردا صبح طوفان به شرق می‌رسد."}]},{"id":"h3","type":"Vortrag","title":"Anpassung an den Klimawandel in unseren Städten","title_fa":"سازگاری شهرهای ما با تغییرات اقلیمی","intro_fa":"یک کارشناس محیط زیست در یک سخنرانی دربارهٔ پیامدهای تغییرات اقلیمی در آلمان و راه‌های سازگاری با آن صحبت می‌کند.","s":[{"de":"Sehr geehrte Damen und Herren, in meinem Vortrag geht es um die Folgen des Klimawandels in Deutschland und darum, wie wir uns anpassen können.","fa":"خانم‌ها و آقایان محترم، سخنرانی من دربارهٔ پیامدهای تغییرات اقلیمی در آلمان است و اینکه چطور می‌توانیم با آن سازگار شویم."},{"de":"Zunächst einige Fakten: Seit 1881 ist die durchschnittliche Temperatur in Deutschland um fast zwei Grad gestiegen.","fa":"اول چند واقعیت: از سال ۱۸۸۱ میانگین دما در آلمان نزدیک به دو درجه بالا رفته است."},{"de":"Damit erwärmt sich unser Land deutlich stärker als der weltweite Durchschnitt.","fa":"بنابراین کشور ما به‌طور محسوسی بیشتر از میانگین جهانی گرم می‌شود."},{"de":"Die Folgen sind schon heute spürbar, denn Hitzewellen werden häufiger und länger, und Starkregen nimmt zu.","fa":"پیامدها همین حالا هم محسوس است، چون موج‌های گرما بیشتر و طولانی‌تر می‌شوند و بارش‌های شدید افزایش می‌یابد."},{"de":"Besonders in Städten wird die Hitze zum Problem, weil Beton und Asphalt die Wärme speichern, sodass es nachts kaum abkühlt.","fa":"گرما به‌ویژه در شهرها مشکل‌ساز می‌شود، چون بتن و آسفالت گرما را در خود نگه می‌دارند، به‌طوری که شب‌ها هوا تقریباً خنک نمی‌شود."},{"de":"Für ältere und kranke Menschen bedeutet das eine ernste Gefahr für die Gesundheit.","fa":"این برای سالمندان و بیماران خطر جدی برای سلامتی است."},{"de":"Gleichzeitig führt die Trockenheit im Sommer dazu, dass Böden austrocknen und Wälder unter Wassermangel leiden.","fa":"هم‌زمان خشکی تابستان باعث می‌شود خاک خشک شود و جنگل‌ها از کم‌آبی رنج ببرند."},{"de":"Wenn dann plötzlich große Mengen Regen fallen, kann der harte Boden das Wasser nicht aufnehmen.","fa":"وقتی بعد ناگهان مقدار زیادی باران ببارد، خاک سفت نمی‌تواند آب را جذب کند."},{"de":"Die Kanalisation ist dann so überlastet, dass Straßen und Keller innerhalb weniger Minuten überschwemmt werden.","fa":"آن وقت شبکهٔ فاضلاب آن‌قدر زیر فشار است که خیابان‌ها و زیرزمین‌ها در عرض چند دقیقه زیر آب می‌روند."},{"de":"Was können wir also tun?","fa":"پس چه کار می‌توانیم بکنیم؟"},{"de":"Natürlich ist es am wichtigsten, weniger Treibhausgase auszustoßen, doch das allein reicht nicht mehr.","fa":"البته مهم‌ترین کار کاهش انتشار گازهای گلخانه‌ای است، اما این به‌تنهایی دیگر کافی نیست."},{"de":"Wir müssen uns auch an die Veränderungen anpassen, die bereits unvermeidbar sind.","fa":"ما باید خودمان را با تغییراتی هم که دیگر اجتناب‌ناپذیرند، سازگار کنیم."},{"de":"Ein vielversprechendes Konzept ist die sogenannte Schwammstadt.","fa":"یک طرح امیدوارکننده، به اصطلاح «شهر اسفنجی» است."},{"de":"Dabei werden mehr Grünflächen, Parks und begrünte Dächer geschaffen, die Regenwasser wie ein Schwamm speichern.","fa":"در این طرح فضاهای سبز، پارک‌ها و بام‌های سبز بیشتری ساخته می‌شود که آب باران را مثل اسفنج در خود نگه می‌دارند."},{"de":"Bei Hitze verdunstet dieses Wasser wieder, infolgedessen kühlt sich die Umgebung spürbar ab.","fa":"در هوای گرم این آب دوباره تبخیر می‌شود و در نتیجه محیط اطراف به‌طور محسوسی خنک می‌شود."},{"de":"Nach Ansicht vieler Experten ist das wirksamer als ein immer größerer Ausbau der Kanalisation.","fa":"به نظر بسیاری از کارشناسان، این روش مؤثرتر از گسترش مداوم شبکهٔ فاضلاب است."},{"de":"In Küstenregionen und an Flüssen experimentiert man außerdem mit schwimmenden Häusern, die bei Hochwasser einfach mit dem Wasser steigen.","fa":"علاوه بر این، در مناطق ساحلی و کنار رودخانه‌ها خانه‌های شناور را آزمایش می‌کنند که هنگام سیل به سادگی همراه آب بالا می‌آیند."},{"de":"In den Niederlanden gibt es bereits ganze Siedlungen dieser Art, allerdings kostet ein solches Haus bisher deutlich mehr als ein normales.","fa":"در هلند همین حالا شهرک‌های کاملی از این نوع وجود دارد، البته چنین خانه‌ای فعلاً خیلی گران‌تر از یک خانهٔ معمولی است."},{"de":"Ich möchte noch einen Aspekt erwähnen, der oft vergessen wird: die Vorsorge jedes Einzelnen.","fa":"می‌خواهم به جنبهٔ دیگری هم اشاره کنم که اغلب فراموش می‌شود: پیشگیری و آمادگی تک‌تک افراد."},{"de":"Wer sein Haus gegen Hitze und Wasser schützt, bei Hitze viel trinkt und auf ältere Nachbarn achtet, leistet schon einen wichtigen Beitrag.","fa":"کسی که خانه‌اش را در برابر گرما و آب محافظت می‌کند، در گرما زیاد آب می‌نوشد و حواسش به همسایه‌های مسن هست، همین حالا سهم مهمی ادا می‌کند."},{"de":"Zusammenfassend kann man sagen, dass Klimaschutz und Anpassung zusammengehören.","fa":"به‌طور خلاصه می‌توان گفت که حفاظت از اقلیم و سازگاری با آن به هم وابسته‌اند."},{"de":"Vielen Dank für Ihre Aufmerksamkeit, ich freue mich jetzt auf Ihre Fragen.","fa":"از توجه شما سپاسگزارم؛ حالا با کمال میل به سؤال‌هایتان گوش می‌دهم."}],"q":[{"q":"Was wird über die Erwärmung in Deutschland gesagt?","opts":["Sie ist genau so stark wie im Rest der Welt.","Sie ist geringer als der weltweite Durchschnitt.","Sie beträgt fast zwei Grad und ist stärker als weltweit."],"a":2,"fa":"از ۱۸۸۱ نزدیک به دو درجه گرم شده و «بیشتر از میانگین جهانی»."},{"q":"Warum ist Hitze in Städten besonders problematisch?","opts":["Weil es in Städten seltener regnet.","Weil dort mehr ältere Menschen wohnen.","Weil Beton und Asphalt Wärme speichern und es nachts kaum abkühlt."],"a":2,"fa":"سخنران گفت بتن و آسفالت گرما را نگه می‌دارند و شب‌ها هوا خنک نمی‌شود."},{"q":"Warum kommt es nach Trockenheit leicht zu Überschwemmungen?","opts":["Weil die Wälder kein Wasser mehr brauchen.","Weil die Flüsse zu wenig Wasser haben.","Weil der harte Boden das Regenwasser nicht aufnehmen kann."],"a":2,"fa":"«خاک سفت نمی‌تواند آب را جذب کند» و شبکهٔ فاضلاب زیر فشار می‌رود."},{"q":"Was ist das Prinzip der Schwammstadt?","opts":["Man baut größere Kanäle für das Regenwasser.","Man baut Häuser, die auf dem Wasser schwimmen.","Grünflächen und begrünte Dächer speichern das Regenwasser."],"a":2,"fa":"در شهر اسفنجی فضای سبز و بام‌های سبز آب باران را مثل اسفنج نگه می‌دارند؛ گسترش فاضلاب را کمتر مؤثر می‌دانند."},{"q":"Was erfährt man über schwimmende Häuser?","opts":["Sie sind bei Hochwasser gefährlich.","Es gibt sie in Deutschland schon überall.","Sie sind teurer als normale Häuser."],"a":2,"fa":"«چنین خانه‌ای فعلاً خیلی گران‌تر از خانهٔ معمولی است.»"},{"q":"Welche Meinung vertritt der Redner am Ende?","opts":["Klimaschutz und Anpassung gehören zusammen.","Der Einzelne kann nichts gegen die Folgen tun.","Anpassung ist wichtiger als Klimaschutz."],"a":0,"fa":"جمع‌بندی سخنران: «حفاظت از اقلیم و سازگاری به هم وابسته‌اند.»"}]}],"6":[{"id":"h1","type":"Radiobeitrag","title":"Vom Hörsaal in die Werkstatt","title_fa":"از کلاس دانشگاه به کارگاه","intro_fa":"یک گزارش رادیویی در برنامهٔ «آموزش و شغل» دربارهٔ دانشجویانی که تحصیل را رها می‌کنند و وارد آموزش حرفه‌ای می‌شوند.","s":[{"de":"Herzlich willkommen zu unserer Sendung „Bildung und Beruf“, heute geht es um ein Thema, über das selten offen gesprochen wird: den Studienabbruch.","fa":"به برنامهٔ «آموزش و شغل» خوش آمدید؛ امروز موضوع ما چیزی است که کمتر آشکارا درباره‌اش صحبت می‌شود: ترک تحصیل دانشگاهی."},{"de":"Etwa jeder vierte Studierende in Deutschland beendet sein Bachelorstudium ohne Abschluss.","fa":"تقریباً از هر چهار دانشجو در آلمان یک نفر دورهٔ کارشناسی‌اش را بدون مدرک به پایان می‌رساند."},{"de":"Viele Studienaussteiger empfinden das zunächst als Karriereknick oder sogar als persönliches Scheitern.","fa":"بسیاری از کسانی که تحصیل را رها می‌کنند، این را در ابتدا افت شغلی یا حتی شکست شخصی می‌دانند."},{"de":"Doch Fachleute sehen das inzwischen ganz anders.","fa":"اما متخصصان امروزه نظر کاملاً متفاوتی دارند."},{"de":"Die Gründe für einen Abbruch sind vielfältig: Manche merken nach zwei oder drei Semestern, dass die Fachrichtung nicht zu ihnen passt.","fa":"دلایل ترک تحصیل متنوع است: بعضی‌ها بعد از دو یا سه ترم متوجه می‌شوند که رشته با آن‌ها جور نیست."},{"de":"Andere vermissen den Praxisbezug, denn im Hörsaal wird vor allem Theorie vermittelt.","fa":"عده‌ای دیگر جای ارتباط با کار عملی را خالی می‌بینند، چون در کلاس دانشگاه بیشتر نظریه آموزش داده می‌شود."},{"de":"Und wieder andere haben finanzielle Probleme, weil sie neben dem Studium zu viel arbeiten müssen.","fa":"و عده‌ای هم مشکلات مالی دارند، چون باید در کنار تحصیل بیش از حد کار کنند."},{"de":"Genau für diese Gruppe gibt es seit einigen Jahren spezielle Programme, die von den Handwerkskammern angeboten werden.","fa":"دقیقاً برای این گروه، چند سالی است که برنامه‌های ویژه‌ای وجود دارد که اتاق‌های اصناف ارائه می‌کنند."},{"de":"Ihr Ziel ist es, Studienaussteiger möglichst schnell in eine betriebliche Ausbildung zu bringen.","fa":"هدف آن‌ها این است که ترک‌تحصیل‌کرده‌ها را هرچه سریع‌تر وارد یک دورهٔ آموزش حرفه‌ای در محیط کار کنند."},{"de":"Das Besondere daran: Wer bereits Studienleistungen vorweisen kann, darf die Lehre oft um ein ganzes Jahr verkürzen.","fa":"نکتهٔ ویژهٔ آن این است که کسی که بتواند واحدهای گذرانده‌اش را نشان دهد، اغلب می‌تواند دورهٔ کارآموزی را یک سال کامل کوتاه‌تر کند."},{"de":"Statt drei Jahren dauert die Ausbildung dann nur noch zwei.","fa":"در این صورت آموزش به‌جای سه سال فقط دو سال طول می‌کشد."},{"de":"Ein Beispiel ist Jonas, 24 Jahre alt, der vier Semester Informatik studiert hat.","fa":"یک نمونه یوناس است، ۲۴ ساله، که چهار ترم انفورماتیک خوانده است."},{"de":"Heute macht er eine Ausbildung zum Elektroniker in einem kleinen Handwerksbetrieb in Kassel.","fa":"او امروز در یک کارگاه کوچک در کاسل دورهٔ آموزش الکترونیک‌کار را می‌گذراند."},{"de":"Darüber, dass er die Uni verlassen hat, ärgert er sich nicht mehr.","fa":"او دیگر از اینکه دانشگاه را ترک کرده ناراحت نیست."},{"de":"Im Gegenteil: Er verdient bereits Geld und sieht jeden Tag, wofür er arbeitet.","fa":"برعکس: او همین حالا پول درمی‌آورد و هر روز می‌بیند برای چه کار می‌کند."},{"de":"Auch die Betriebe profitieren davon, denn im Handwerk fehlen bundesweit Zehntausende Fachkräfte.","fa":"کارگاه‌ها هم از این موضوع سود می‌برند، چون در مشاغل فنی و صنعتی در سراسر کشور ده‌ها هزار نیروی متخصص کم است."},{"de":"Studienaussteiger gelten als besonders motiviert, weil sie sich ganz bewusst für diesen Weg entschieden haben.","fa":"ترک‌تحصیل‌کرده‌ها افرادی بسیار باانگیزه به شمار می‌آیند، چون کاملاً آگاهانه این مسیر را انتخاب کرده‌اند."},{"de":"Kritiker weisen allerdings darauf hin, dass die gesellschaftliche Anerkennung von Handwerksberufen immer noch zu gering ist.","fa":"البته منتقدان به این نکته اشاره می‌کنند که احترام اجتماعی به مشاغل فنی و صنعتی هنوز هم خیلی کم است."},{"de":"Viele Eltern wünschen sich für ihre Kinder nach wie vor einen Studienabschluss.","fa":"بسیاری از والدین همچنان برای فرزندانشان مدرک دانشگاهی آرزو می‌کنند."},{"de":"Dabei sind die Perspektiven gut: Wer später den Meister macht, kann einen eigenen Betrieb gründen oder als Führungskraft arbeiten.","fa":"در حالی که چشم‌انداز خوب است: کسی که بعداً مدرک استادکاری بگیرد، می‌تواند کارگاه خودش را تأسیس کند یا در جایگاه مدیر کار کند."},{"de":"Wer unsicher ist, sollte sich früh beraten lassen, zum Beispiel bei der Studienberatung der Hochschule oder direkt bei der Handwerkskammer.","fa":"کسی که مطمئن نیست، بهتر است زود مشاوره بگیرد، مثلاً در مرکز مشاورهٔ تحصیلی دانشگاه یا مستقیماً در اتاق اصناف."},{"de":"Nach der Pause sprechen wir darüber, worauf man bei der Suche nach einem Ausbildungsplatz achten sollte.","fa":"بعد از وقفه دربارهٔ این صحبت می‌کنیم که در جست‌وجوی جای کارآموزی به چه چیزی باید توجه کرد."}],"q":[{"q":"Wie viele Studierende brechen laut Beitrag ihr Bachelorstudium ab?","opts":["etwa die Hälfte","etwa jeder vierte","etwa jeder zehnte"],"a":1,"fa":"گوینده می‌گوید «تقریباً از هر چهار دانشجو یک نفر» کارشناسی را بدون مدرک تمام می‌کند."},{"q":"Welcher Grund für einen Studienabbruch wird NICHT genannt?","opts":["zu wenig Praxisbezug","zu hohe Studiengebühren","die falsche Fachrichtung"],"a":1,"fa":"از رشتهٔ نامناسب، کمبود ارتباط با کار عملی و مشکلات مالی به‌خاطر کار زیاد صحبت شد، اما از شهریهٔ بالا حرفی زده نشد."},{"q":"Was ist das Besondere an den Programmen der Handwerkskammern?","opts":["Die Ausbildung kann oft um ein Jahr verkürzt werden.","Die Teilnehmer bekommen sofort einen Meistertitel.","Die Ausbildung findet nur an der Universität statt."],"a":0,"fa":"گفته شد کسی که واحدهای دانشگاهی دارد، اغلب می‌تواند کارآموزی را یک سال کوتاه‌تر کند: دو سال به‌جای سه سال."},{"q":"Was erfährt man über Jonas?","opts":["Er hat vier Semester Informatik studiert.","Er arbeitet in einem großen Konzern.","Er bereut seine Entscheidung sehr."],"a":0,"fa":"یوناس چهار ترم انفورماتیک خوانده، از تصمیمش ناراحت نیست و در یک کارگاه کوچک کار می‌کند."},{"q":"Warum sind Studienaussteiger bei den Betrieben beliebt?","opts":["Weil sie schon alles über das Handwerk wissen.","Weil sie weniger Geld verdienen wollen.","Weil sie sich bewusst für den Weg entschieden haben und motiviert sind."],"a":2,"fa":"در متن آمده که آن‌ها بسیار باانگیزه‌اند، چون آگاهانه این مسیر را انتخاب کرده‌اند."},{"q":"Was kritisieren manche Fachleute?","opts":["Handwerksberufe haben zu wenig gesellschaftliche Anerkennung.","Die Meisterprüfung ist zu leicht.","Es gibt zu viele Ausbildungsplätze."],"a":0,"fa":"منتقدان می‌گویند احترام اجتماعی به مشاغل فنی و صنعتی هنوز خیلی کم است."}]},{"id":"h2","type":"Erfahrungsbericht","title":"Mein duales Studium: Hörsaal und Betrieb","title_fa":"تحصیل دوگانهٔ من: دانشگاه و شرکت","intro_fa":"لوکاس، دانشجوی ترم پنجم، در یک جلسهٔ اطلاع‌رسانی برای دانش‌آموزان از تجربه‌هایش در تحصیل دوگانه تعریف می‌کند.","s":[{"de":"Hallo, ich heiße Lukas, ich bin 22 und studiere im fünften Semester Wirtschaftsingenieurwesen an einer dualen Hochschule.","fa":"سلام، اسم من لوکاس است، ۲۲ ساله‌ام و ترم پنجم مهندسی صنایع را در یک دانشگاه دوگانه می‌خوانم."},{"de":"Man hat mich gebeten, von meinen Erfahrungen zu berichten, und das mache ich gern.","fa":"از من خواسته‌اند از تجربه‌هایم بگویم و با کمال میل این کار را می‌کنم."},{"de":"Ein duales Studium kombiniert ein Hochschulstudium mit praktischen Phasen in einem Unternehmen.","fa":"تحصیل دوگانه، تحصیل دانشگاهی را با دوره‌های عملی در یک شرکت ترکیب می‌کند."},{"de":"Bei mir wechseln sich jeweils drei Monate Theorie und drei Monate Praxis ab.","fa":"در مورد من هر بار سه ماه نظریه و سه ماه کار عملی به نوبت پشت سر هم می‌آیند."},{"de":"Mein Praxispartner ist ein mittelständischer Hersteller von Windkraftanlagen in der Nähe von Bremen.","fa":"شریک عملی من یک شرکت متوسط تولیدکنندهٔ توربین‌های بادی در نزدیکی برمن است."},{"de":"Darauf, dass ich dort eine Stelle bekommen habe, bin ich bis heute stolz, denn es gab über hundert Bewerbungen.","fa":"هنوز هم به اینکه آنجا جایی گرفتم افتخار می‌کنم، چون بیش از صد درخواست رسیده بود."},{"de":"Der größte Vorteil liegt für mich auf der Hand: Ich verdiene vom ersten Tag an Geld.","fa":"بزرگ‌ترین مزیت برای من روشن است: از روز اول پول درمی‌آورم."},{"de":"Mein Gehalt liegt im Moment bei etwa 1200 Euro im Monat, und das Unternehmen bezahlt auch die Studiengebühren.","fa":"حقوق من در حال حاضر حدود ۱۲۰۰ یورو در ماه است و شرکت شهریه را هم می‌پردازد."},{"de":"Außerdem sammle ich schon während des Studiums Berufspraxis, die anderen Absolventen oft fehlt.","fa":"علاوه بر این، از همان دوران تحصیل تجربهٔ کاری جمع می‌کنم؛ چیزی که فارغ‌التحصیلان دیگر اغلب ندارند."},{"de":"In den Praxisphasen arbeite ich in echten Projekten mit und kann so wichtige Kontakte knüpfen.","fa":"در دوره‌های عملی در پروژه‌های واقعی همکاری می‌کنم و به این ترتیب می‌توانم ارتباط‌های مهمی برقرار کنم."},{"de":"Dieses Netzwerk wird mir später sicher helfen, egal, ob ich im Unternehmen bleibe oder nicht.","fa":"این شبکهٔ ارتباطی بعداً حتماً به من کمک می‌کند، فرقی نمی‌کند در شرکت بمانم یا نه."},{"de":"Allerdings möchte ich auch nicht verschweigen, dass das duale Studium sehr anstrengend ist.","fa":"البته نمی‌خواهم این را هم پنهان کنم که تحصیل دوگانه خیلی طاقت‌فرساست."},{"de":"Semesterferien, wie sie andere Studierende haben, gibt es für mich nicht.","fa":"تعطیلات بین ترم، آن‌طور که دانشجویان دیگر دارند، برای من وجود ندارد."},{"de":"Ich habe nur 30 Urlaubstage im Jahr, und in den Theoriephasen schreibe ich viele Prüfungen in kurzer Zeit.","fa":"من فقط ۳۰ روز مرخصی در سال دارم و در دوره‌های نظری در مدت کوتاهی امتحان‌های زیادی می‌دهم."},{"de":"Ohne viel Disziplin und eine gute Zeitplanung schafft man das kaum.","fa":"بدون انضباط زیاد و برنامه‌ریزی خوب زمانی، به‌سختی می‌شود از پسش برآمد."},{"de":"Zwei Kommilitonen aus meinem Jahrgang haben deshalb schon aufgegeben.","fa":"به همین دلیل دو نفر از هم‌دوره‌ای‌هایم تا حالا کنار کشیده‌اند."},{"de":"Ein weiterer Punkt, worüber man vorher nachdenken sollte, ist die Bindung an das Unternehmen.","fa":"نکتهٔ دیگری که باید از قبل درباره‌اش فکر کرد، تعهد به شرکت است."},{"de":"In meinem Vertrag steht, dass ich nach dem Abschluss mindestens zwei Jahre dort arbeiten muss.","fa":"در قرارداد من نوشته شده که بعد از فارغ‌التحصیلی باید دست‌کم دو سال آنجا کار کنم."},{"de":"Wer früher geht, muss einen Teil der Studiengebühren zurückzahlen.","fa":"کسی که زودتر برود، باید بخشی از شهریه را پس بدهد."},{"de":"Für mich ist das kein Problem, weil mir die Arbeit Spaß macht und die Aufstiegschancen gut sind.","fa":"برای من این مشکلی نیست، چون از کارم لذت می‌برم و فرصت‌های پیشرفت خوب است."},{"de":"Mein Tipp: Informiert euch genau über den Praxispartner, bevor ihr unterschreibt.","fa":"توصیهٔ من: پیش از امضا کردن، دربارهٔ شریک عملی دقیق اطلاعات کسب کنید."},{"de":"Fragt am besten Studierende, die schon dort sind, denn die können euch am ehrlichsten sagen, wie es wirklich ist.","fa":"بهتر است از دانشجویانی بپرسید که الان آنجا هستند، چون آن‌ها از همه صادقانه‌تر می‌توانند بگویند اوضاع واقعاً چطور است."}],"q":[{"q":"Wie ist das Studium von Lukas organisiert?","opts":["Er studiert am Wochenende und arbeitet unter der Woche.","Theorie und Praxis wechseln sich alle drei Monate ab.","Er macht erst das Studium und danach ein Praktikum."],"a":1,"fa":"لوکاس می‌گوید هر بار سه ماه نظریه و سه ماه کار عملی به نوبت می‌آیند."},{"q":"Warum ist Lukas stolz auf seinen Platz?","opts":["Weil das Unternehmen sehr berühmt ist.","Weil es über hundert Bewerbungen gab.","Weil er die beste Note hatte."],"a":1,"fa":"او می‌گوید افتخار می‌کند، چون بیش از صد درخواست رسیده بود."},{"q":"Was sagt Lukas über das Geld?","opts":["Er verdient erst ab dem dritten Semester Geld.","Er verdient etwa 1200 Euro und das Unternehmen bezahlt die Studiengebühren.","Er muss die Studiengebühren selbst bezahlen."],"a":1,"fa":"او از روز اول حدود ۱۲۰۰ یورو در ماه درمی‌آورد و شرکت شهریه را هم می‌پردازد."},{"q":"Welchen Nachteil nennt Lukas?","opts":["Er hat keinen Kontakt zu Kollegen.","Er hat keine normalen Semesterferien.","Die Arbeit im Betrieb ist langweilig."],"a":1,"fa":"او می‌گوید تعطیلات بین ترم مثل دانشجویان دیگر ندارد و فقط ۳۰ روز مرخصی دارد."},{"q":"Was passiert, wenn man das Unternehmen zu früh verlässt?","opts":["Man verliert den Studienabschluss.","Man darf nie wieder dual studieren.","Man muss einen Teil der Studiengebühren zurückzahlen."],"a":2,"fa":"طبق قرارداد، کسی که زودتر از دو سال برود باید بخشی از شهریه را پس بدهد."},{"q":"Was empfiehlt Lukas?","opts":["Studierende zu fragen, die schon beim Praxispartner sind","sofort zu unterschreiben","nur die Internetseite des Unternehmens zu lesen"],"a":0,"fa":"توصیهٔ او این است که از دانشجویانی بپرسید که الان آنجا هستند، چون صادقانه‌تر جواب می‌دهند."}]},{"id":"h3","type":"Vortrag","title":"Welcher Karriereweg passt zu mir?","title_fa":"کدام مسیر شغلی مناسب من است؟","intro_fa":"یک مشاور شغلی ادارهٔ کار در یک شب اطلاع‌رسانی برای دانش‌آموزان و والدین، مسیرهای مختلف آموزشی و شغلی و امکان مشاوره را معرفی می‌کند.","s":[{"de":"Guten Abend, meine Damen und Herren, liebe Schülerinnen und Schüler, schön, dass Sie heute zu unserem Informationsabend gekommen sind.","fa":"عصر بخیر خانم‌ها و آقایان، دانش‌آموزان عزیز، خوشحالم که امروز به شب اطلاع‌رسانی ما آمده‌اید."},{"de":"Mein Name ist Peter Wagner, und ich arbeite seit fünfzehn Jahren als Berufsberater bei der Agentur für Arbeit.","fa":"اسم من پتر واگنر است و پانزده سال است که در ادارهٔ کار مشاور شغلی هستم."},{"de":"In den nächsten zwanzig Minuten möchte ich Ihnen einen Überblick über die wichtigsten Karrierewege geben.","fa":"در بیست دقیقهٔ آینده می‌خواهم مروری کلی بر مهم‌ترین مسیرهای شغلی برایتان ارائه کنم."},{"de":"Viele junge Menschen glauben, dass sie sich nach der Schule ein für alle Mal entscheiden müssen.","fa":"بسیاری از جوانان فکر می‌کنند که بعد از مدرسه باید یک بار برای همیشه تصمیم بگیرند."},{"de":"Das ist ein Irrtum, denn eine berufliche Laufbahn verläuft heute selten geradlinig.","fa":"این اشتباه است، چون مسیر شغلی امروزه به‌ندرت در یک خط مستقیم پیش می‌رود."},{"de":"Der erste Weg, den ich Ihnen vorstellen möchte, ist die klassische Berufsausbildung.","fa":"اولین راهی که می‌خواهم به شما معرفی کنم، آموزش حرفه‌ای کلاسیک است."},{"de":"Dabei lernen die Auszubildenden drei bis vier Tage pro Woche im Betrieb und ein bis zwei Tage in der Berufsschule.","fa":"در این روش، کارآموزان سه تا چهار روز در هفته در محل کار و یک تا دو روز در هنرستان حرفه‌ای آموزش می‌بینند."},{"de":"In Deutschland gibt es rund 320 anerkannte Ausbildungsberufe, vom Bäcker bis zur Mechatronikerin.","fa":"در آلمان حدود ۳۲۰ حرفهٔ آموزشی رسمی وجود دارد، از نانوا تا متخصص مکاترونیک."},{"de":"Nach der Gesellenprüfung kann man sich weiter fortbilden, zum Beispiel zum Meister oder zur Technikerin.","fa":"بعد از آزمون پایان کارآموزی می‌توان آموزش تکمیلی دید، مثلاً برای استادکار یا تکنسین شدن."},{"de":"Der Meistertitel ist übrigens die Voraussetzung dafür, in vielen Handwerksberufen einen eigenen Betrieb zu führen.","fa":"ضمناً عنوان استادکاری در بسیاری از مشاغل فنی و صنعتی پیش‌شرط اداره کردن کارگاه شخصی است."},{"de":"Der zweite Weg ist das Studium an einer Universität oder Fachhochschule, das vor allem für theoretisch interessierte Menschen geeignet ist.","fa":"راه دوم تحصیل در دانشگاه یا دانشگاه علوم کاربردی است که بیشتر برای افراد علاقه‌مند به مباحث نظری مناسب است."},{"de":"Wer beides verbinden möchte, für den ist ein duales Studium eine gute Alternative.","fa":"برای کسی که می‌خواهد هر دو را با هم داشته باشد، تحصیل دوگانه گزینهٔ خوبی است."},{"de":"Hier sind die Plätze allerdings knapp, und man muss sich oft schon ein Jahr vor dem Schulabschluss bewerben.","fa":"البته در اینجا ظرفیت محدود است و اغلب باید یک سال قبل از پایان مدرسه درخواست داد."},{"de":"Was ist nun der richtige Weg für Sie?","fa":"حالا راه درست برای شما کدام است؟"},{"de":"Darauf gibt es leider keine allgemeine Antwort, denn es hängt von Ihren Stärken und Interessen ab.","fa":"متأسفانه برای این سؤال پاسخ کلی وجود ندارد، چون به توانایی‌ها و علایق شما بستگی دارد."},{"de":"Deshalb bieten wir kostenlose Einzelgespräche an, in denen wir gemeinsam Ihre Möglichkeiten besprechen.","fa":"به همین دلیل ما جلسه‌های مشاورهٔ فردی رایگان برگزار می‌کنیم که در آن‌ها با هم امکانات شما را بررسی می‌کنیم."},{"de":"Vorher können Sie online einen Test machen, der Ihnen zeigt, welche Berufsfelder zu Ihnen passen könnten.","fa":"پیش از آن می‌توانید آنلاین آزمونی بدهید که نشان می‌دهد چه حوزه‌های شغلی ممکن است با شما جور باشد."},{"de":"Bringen Sie zum Beratungsgespräch am besten Ihr letztes Zeugnis und, falls vorhanden, Praktikumsbescheinigungen mit.","fa":"بهتر است برای جلسهٔ مشاوره آخرین کارنامه‌تان و اگر دارید، گواهی‌های کارآموزی را همراه بیاورید."},{"de":"Einen Termin bekommen Sie telefonisch oder über unsere Internetseite, die Wartezeit beträgt im Moment etwa zwei Wochen.","fa":"وقت مشاوره را تلفنی یا از طریق وب‌سایت ما می‌گیرید؛ زمان انتظار در حال حاضر حدود دو هفته است."},{"de":"Und noch ein letzter Rat: Machen Sie so viele Praktika wie möglich, denn nichts hilft bei der Entscheidung mehr als echte Erfahrung.","fa":"و یک توصیهٔ آخر: تا جایی که می‌توانید کارآموزی کوتاه‌مدت انجام دهید، چون هیچ چیز به اندازهٔ تجربهٔ واقعی در تصمیم‌گیری کمک نمی‌کند."},{"de":"Jetzt beantworte ich gern Ihre Fragen.","fa":"حالا با کمال میل به سؤال‌های شما پاسخ می‌دهم."}],"q":[{"q":"Welchen Irrtum haben viele junge Menschen laut Herrn Wagner?","opts":["Sie glauben, eine Ausbildung sei zu teuer.","Sie glauben, sie müssten sich nach der Schule für immer entscheiden.","Sie glauben, ein Studium dauere nur zwei Jahre."],"a":1,"fa":"به گفتهٔ او بسیاری فکر می‌کنند باید «یک بار برای همیشه» تصمیم بگیرند، اما مسیر شغلی به‌ندرت مستقیم است."},{"q":"Wo lernen Auszubildende in der klassischen Ausbildung?","opts":["an der Universität","im Betrieb und in der Berufsschule","nur in der Berufsschule"],"a":1,"fa":"کارآموزان سه تا چهار روز در محل کار و یک تا دو روز در هنرستان حرفه‌ای آموزش می‌بینند."},{"q":"Wofür braucht man in vielen Handwerksberufen den Meistertitel?","opts":["um eine Berufsschule zu besuchen","um studieren zu dürfen","um einen eigenen Betrieb zu führen"],"a":2,"fa":"او می‌گوید عنوان استادکاری پیش‌شرط اداره کردن کارگاه شخصی است."},{"q":"Was sagt Herr Wagner über das duale Studium?","opts":["Es ist nur für theoretisch interessierte Menschen.","Es gibt sehr viele freie Plätze.","Man muss sich oft ein Jahr vor dem Schulabschluss bewerben."],"a":2,"fa":"ظرفیت محدود است و اغلب باید یک سال قبل از پایان مدرسه درخواست داد."},{"q":"Was sollte man zum Beratungsgespräch mitbringen?","opts":["das letzte Zeugnis und Praktikumsbescheinigungen","einen Brief der Eltern","ein Empfehlungsschreiben der Universität"],"a":0,"fa":"او توصیه می‌کند آخرین کارنامه و در صورت وجود، گواهی‌های کارآموزی را بیاورید."},{"q":"Wie lange muss man zurzeit auf einen Termin warten?","opts":["etwa zwei Wochen","etwa zwei Monate","etwa zwei Tage"],"a":0,"fa":"گفته شد زمان انتظار در حال حاضر حدود دو هفته است."}]}],"7":[{"id":"h1","type":"Podcast-Folge","title":"Ernährungsindividualisten: Warum essen wir so verschieden?","title_fa":"فردگرایان تغذیه: چرا این‌قدر متفاوت غذا می‌خوریم؟","intro_fa":"دانیل در پادکست «خوب خوردن» دربارهٔ شیوه‌های مختلف تغذیه مثل وگانیسم، خام‌خواری و روزه‌داری و انگیزه‌های پشت آن‌ها صحبت می‌کند.","s":[{"de":"Hallo und willkommen zu einer neuen Folge von „Gut gegessen“, dem Podcast rund um Ernährung und Genuss.","fa":"سلام و به قسمت تازه‌ای از «خوب خوردن»، پادکستی دربارهٔ تغذیه و لذت غذا، خوش آمدید."},{"de":"Ich bin Daniel, und heute geht es um ein Phänomen, das man inzwischen überall beobachten kann.","fa":"من دانیل هستم و امروز موضوع ما پدیده‌ای است که حالا همه‌جا می‌شود دید."},{"de":"Wenn ich heute mit Freunden essen gehe, isst fast jeder etwas anderes.","fa":"امروز وقتی با دوستانم بیرون غذا می‌خورم، تقریباً هر کس چیز متفاوتی می‌خورد."},{"de":"Eine Freundin isst vegan, ein Freund verzichtet auf Gluten, und ein Dritter fastet gerade bis zwölf Uhr mittags.","fa":"یکی از دوستانم وگان است، دوست دیگری گلوتن نمی‌خورد و سومی فعلاً تا ساعت دوازده ظهر چیزی نمی‌خورد."},{"de":"Ernährungswissenschaftler nennen solche Menschen Ernährungsindividualisten.","fa":"متخصصان تغذیه چنین افرادی را «فردگرایان تغذیه» می‌نامند."},{"de":"Laut einer aktuellen Umfrage ernähren sich in Deutschland etwa zehn Prozent der Bevölkerung vegetarisch und rund zwei Prozent vegan.","fa":"بر اساس یک نظرسنجی جدید، در آلمان حدود ده درصد مردم گیاه‌خوار و حدود دو درصد وگان هستند."},{"de":"Bei den unter Dreißigjährigen sind es sogar deutlich mehr.","fa":"در میان افراد زیر سی سال این رقم حتی به‌مراتب بیشتر است."},{"de":"Doch was sind die Motive dafür?","fa":"اما انگیزه‌های این کار چیست؟"},{"de":"Die Autoren der Studie schreiben, die Gesundheit sei für die meisten Befragten der wichtigste Faktor.","fa":"نویسندگان پژوهش می‌نویسند که سلامتی برای بیشتر پاسخ‌دهندگان مهم‌ترین عامل است."},{"de":"An zweiter Stelle stehe das Tierwohl, gefolgt vom Klimaschutz.","fa":"به گفتهٔ آن‌ها رفاه حیوانات در جای دوم قرار دارد و پس از آن حفاظت از اقلیم."},{"de":"Viele Anhänger des Veganismus sagen, sie wollten Billigfleisch und Massentierhaltung nicht unterstützen.","fa":"بسیاری از طرفداران وگانیسم می‌گویند که نمی‌خواهند از گوشت ارزان و دامداری صنعتی حمایت کنند."},{"de":"Ein Soziologe, dessen Buch ich gerade lese, sieht aber noch einen anderen Grund.","fa":"اما یک جامعه‌شناس که الان کتابش را می‌خوانم، دلیل دیگری هم می‌بیند."},{"de":"Er schreibt, Essen sei heute auch ein Mittel, um die eigene Identität zu zeigen.","fa":"او می‌نویسد که غذا امروز وسیله‌ای برای نشان دادن هویت شخصی هم هست."},{"de":"Früher habe die Familie diktiert, was auf den Tisch kommt, heute entscheide jeder selbst.","fa":"به گفتهٔ او، قبلاً خانواده تعیین می‌کرد چه چیزی سر سفره بیاید، اما امروز هر کس خودش تصمیم می‌گیرد."},{"de":"Mir ist aufgefallen, dass das auch zu Problemen führen kann.","fa":"من متوجه شده‌ام که این موضوع می‌تواند مشکلاتی هم به وجود بیاورد."},{"de":"Wer zum Beispiel ein Familienfest organisiert, muss heute oft drei verschiedene Menüs planen.","fa":"مثلاً کسی که یک جشن خانوادگی ترتیب می‌دهد، امروز اغلب باید سه منوی متفاوت برنامه‌ریزی کند."},{"de":"Und nicht jedes Konzept ist aus medizinischer Sicht sinnvoll.","fa":"و از نظر پزشکی هم هر رویکردی معقول نیست."},{"de":"Eine Ärztin aus Köln warnt, wer sich ausschließlich von Rohkost ernähre, riskiere eine Mangelernährung.","fa":"یک پزشک از کلن هشدار می‌دهد که هر کس فقط خام‌خواری کند، خود را در خطر سوءتغذیه قرار می‌دهد."},{"de":"Bei einer veganen Ernährung sei vor allem Vitamin B12 wichtig, das man zusätzlich einnehmen müsse.","fa":"به گفتهٔ او در تغذیهٔ وگان به‌ویژه ویتامین ب۱۲ اهمیت دارد که باید به‌صورت مکمل مصرف شود."},{"de":"Mein persönliches Fazit: Ausprobieren ist erlaubt, aber man sollte sich gut informieren.","fa":"جمع‌بندی شخصی من: امتحان کردن اشکالی ندارد، اما باید خوب اطلاعات کسب کرد."},{"de":"Und vielleicht sollten wir trotz aller Unterschiede wieder öfter gemeinsam am Tisch sitzen.","fa":"و شاید باید با وجود همهٔ تفاوت‌ها دوباره بیشتر دور یک میز بنشینیم."},{"de":"In der nächsten Folge geht es um die Frage, ob Essen wirklich nur Privatsache ist.","fa":"در قسمت بعد به این پرسش می‌پردازیم که آیا غذا واقعاً فقط یک موضوع شخصی است."}],"q":[{"q":"Welches Beispiel nennt Daniel am Anfang?","opts":["Er kocht jeden Tag für seine Familie.","Seine Freunde essen alle vegan.","Beim Essen mit Freunden isst fast jeder etwas anderes."],"a":2,"fa":"دانیل می‌گوید وقتی با دوستانش بیرون غذا می‌خورد، تقریباً هر کس چیز متفاوتی می‌خورد."},{"q":"Wie viele Menschen in Deutschland ernähren sich laut Umfrage vegan?","opts":["etwa zwanzig Prozent","rund zwei Prozent","etwa zehn Prozent"],"a":1,"fa":"ده درصد گیاه‌خوار و حدود دو درصد وگان هستند."},{"q":"Was ist laut Studie das wichtigste Motiv?","opts":["die Gesundheit","das Tierwohl","der Klimaschutz"],"a":0,"fa":"طبق پژوهش، سلامتی مهم‌ترین عامل است؛ رفاه حیوانات دوم و حفاظت از اقلیم سوم است."},{"q":"Welchen weiteren Grund sieht der Soziologe?","opts":["Die Familie diktiert heute das Essen.","Essen ist billiger geworden.","Mit dem Essen zeigt man seine Identität."],"a":2,"fa":"به نظر جامعه‌شناس، غذا امروز وسیلهٔ نشان دادن هویت است؛ دیکته کردن خانواده مربوط به گذشته است."},{"q":"Wovor warnt die Ärztin?","opts":["vor dem Fasten am Morgen","vor Mangelernährung bei reiner Rohkost","vor zu viel Vitamin B12"],"a":1,"fa":"پزشک کلنی هشدار می‌دهد که خام‌خواری محض خطر سوءتغذیه دارد."},{"q":"Was ist Daniels Fazit?","opts":["Jeder sollte vegan leben.","Man sollte neue Ernährungsformen verbieten.","Man darf ausprobieren, sollte sich aber gut informieren."],"a":2,"fa":"جمع‌بندی او این است: امتحان کردن اشکالی ندارد، اما باید خوب اطلاعات کسب کرد."}]},{"id":"h2","type":"Nachrichten","title":"Nachrichten am Mittag: Ernährung und Politik","title_fa":"اخبار ظهر: تغذیه و سیاست","intro_fa":"گویندهٔ رادیو در اخبار ظهر خبرهایی دربارهٔ عوارض نوشیدنی‌های شیرین، یارانهٔ کشاورزی، گرسنگی جهانی و یک طرح محلی غذای مدرسه می‌خواند.","s":[{"de":"Guten Tag, Sie hören die Nachrichten.","fa":"روز بخیر، اخبار را می‌شنوید."},{"de":"Die Debatte über eine Abgabe auf stark gezuckerte Getränke geht weiter.","fa":"بحث دربارهٔ وضع عوارض بر نوشیدنی‌های پرشکر ادامه دارد."},{"de":"Mehrere Ärzteverbände fordern, die Politik müsse endlich mehr gegen Übergewicht bei Kindern tun.","fa":"چند انجمن پزشکی خواستار آن شده‌اند که سیاستمداران بالاخره برای مقابله با اضافه‌وزن کودکان کار بیشتری بکنند."},{"de":"Inzwischen soll fast jedes siebte Kind in Deutschland übergewichtig sein.","fa":"گفته می‌شود اکنون تقریباً از هر هفت کودک در آلمان یکی اضافه‌وزن دارد."},{"de":"Ein Sprecher der Getränkeindustrie erklärte dagegen, eine solche Steuer sei unfair und bringe nichts.","fa":"در مقابل، سخنگوی صنعت نوشیدنی اعلام کرد که چنین مالیاتی ناعادلانه است و فایده‌ای ندارد."},{"de":"Die Verbraucher müssten selbst entscheiden können, was sie trinken.","fa":"به گفتهٔ او مصرف‌کنندگان باید خودشان بتوانند تصمیم بگیرند چه بنوشند."},{"de":"In Großbritannien hat eine ähnliche Abgabe allerdings dazu geführt, dass die Hersteller deutlich weniger Zucker verwenden.","fa":"البته در بریتانیا عوارض مشابهی باعث شده که تولیدکنندگان به‌طور چشمگیری شکر کمتری مصرف کنند."},{"de":"Auch beim Thema Tierhaltung gibt es neue Diskussionen.","fa":"در موضوع دامداری هم بحث‌های تازه‌ای در جریان است."},{"de":"Umweltverbände kritisieren, die Subventionen für die Landwirtschaft unterstützten vor allem große Betriebe.","fa":"انجمن‌های محیط زیست انتقاد می‌کنند که یارانه‌های کشاورزی بیشتر به واحدهای بزرگ کمک می‌کند."},{"de":"Das Geld solle stattdessen in eine artgerechte Tierhaltung fließen.","fa":"به گفتهٔ آن‌ها این پول باید به‌جای آن صرف نگهداری حیوانات به شیوه‌ای متناسب با نیازشان شود."},{"de":"Billigfleisch sei nur deshalb so billig, weil die wahren Kosten für Umwelt und Tiere nicht im Preis enthalten seien.","fa":"به گفتهٔ آن‌ها گوشت ارزان فقط به این دلیل این‌قدر ارزان است که هزینه‌های واقعی برای محیط زیست و حیوانات در قیمت لحاظ نشده است."},{"de":"Der Bauernverband warnt dagegen vor höheren Preisen für die Verbraucher.","fa":"در مقابل، اتحادیهٔ کشاورزان دربارهٔ گران‌تر شدن قیمت‌ها برای مصرف‌کنندگان هشدار می‌دهد."},{"de":"Viele Familien könnten sich Fleisch dann kaum noch leisten, heißt es in einer Mitteilung.","fa":"در اطلاعیه‌ای آمده است که در آن صورت بسیاری از خانواده‌ها دیگر به‌سختی می‌توانند گوشت بخرند."},{"de":"Und nun zu einer internationalen Meldung.","fa":"و حالا یک خبر بین‌المللی."},{"de":"Nach Angaben der Vereinten Nationen hungern weltweit noch immer mehr als 700 Millionen Menschen.","fa":"بر اساس اعلام سازمان ملل متحد، هنوز هم در سراسر جهان بیش از ۷۰۰ میلیون نفر گرسنه‌اند."},{"de":"Ein Grund dafür sollen Spekulationen mit Nahrungsmitteln an den Börsen sein, die die Preise in die Höhe treiben.","fa":"گفته می‌شود یکی از دلایل آن سفته‌بازی با مواد غذایی در بورس‌هاست که قیمت‌ها را بالا می‌برد."},{"de":"Hilfsorganisationen fordern, solche Geschäfte stärker zu kontrollieren.","fa":"سازمان‌های امدادی خواستار نظارت بیشتر بر چنین معاملاتی هستند."},{"de":"Das Welthungerproblem sei keine Frage der Menge, sondern eine Frage der Gerechtigkeit, heißt es in einer gemeinsamen Erklärung.","fa":"در یک بیانیهٔ مشترک آمده است که مشکل گرسنگی جهانی مسئلهٔ مقدار غذا نیست، بلکه مسئلهٔ عدالت است."},{"de":"Weltweit würden nämlich genug Lebensmittel für alle Menschen produziert.","fa":"چون به گفتهٔ آن‌ها در جهان به اندازهٔ کافی غذا برای همهٔ انسان‌ها تولید می‌شود."},{"de":"Zum Schluss noch eine Meldung aus unserer Stadt.","fa":"در پایان یک خبر از شهر خودمان."},{"de":"Gestern hat hier die erste Schulkantine eröffnet, in der alle Kinder kostenlos ein gesundes Mittagessen bekommen.","fa":"دیروز اینجا اولین غذاخوری مدرسه افتتاح شد که در آن همهٔ بچه‌ها رایگان یک ناهار سالم می‌گیرند."},{"de":"Das Projekt soll zunächst zwei Jahre lang laufen und wird mit einer halben Million Euro gefördert.","fa":"قرار است این طرح ابتدا دو سال اجرا شود و با نیم میلیون یورو حمایت مالی می‌شود."},{"de":"Das Wetter: Heute ist es sonnig bei Temperaturen bis 18 Grad.","fa":"وضع هوا: امروز آفتابی است و دما تا ۱۸ درجه می‌رسد."}],"q":[{"q":"Was fordern die Ärzteverbände?","opts":["Die Politik soll mehr gegen Übergewicht bei Kindern tun.","Kinder sollen mehr Fleisch essen.","Zuckerhaltige Getränke sollen billiger werden."],"a":0,"fa":"انجمن‌های پزشکی می‌خواهند سیاستمداران علیه اضافه‌وزن کودکان کار بیشتری بکنند."},{"q":"Was meint der Sprecher der Getränkeindustrie?","opts":["Die Steuer sei eine gute Idee.","Die Hersteller wollten weniger Zucker verwenden.","Die Steuer sei unfair und bringe nichts."],"a":2,"fa":"سخنگوی صنعت نوشیدنی گفت این مالیات ناعادلانه است و فایده‌ای ندارد."},{"q":"Was ist in Großbritannien passiert?","opts":["Die Abgabe wurde wieder abgeschafft.","Die Hersteller verwenden deutlich weniger Zucker.","Die Menschen trinken mehr Limonade."],"a":1,"fa":"در بریتانیا عوارض مشابه باعث شد تولیدکنندگان شکر خیلی کمتری مصرف کنند."},{"q":"Was kritisieren die Umweltverbände?","opts":["Es gebe zu wenige Bauern.","Fleisch sei zu teuer.","Die Subventionen unterstützten vor allem große Betriebe."],"a":2,"fa":"انجمن‌های محیط زیست انتقاد می‌کنند که یارانه‌ها بیشتر به واحدهای بزرگ می‌رسد."},{"q":"Was soll laut Meldung ein Grund für den Hunger in der Welt sein?","opts":["zu wenig Produktion von Lebensmitteln","Spekulationen mit Nahrungsmitteln an den Börsen","das schlechte Wetter"],"a":1,"fa":"گفته می‌شود سفته‌بازی با مواد غذایی در بورس قیمت‌ها را بالا می‌برد؛ طبق بیانیه، غذا به اندازهٔ کافی تولید می‌شود."},{"q":"Wie lange soll das Kantinenprojekt zunächst laufen?","opts":["zwei Jahre","ein halbes Jahr","fünf Jahre"],"a":0,"fa":"قرار است طرح غذاخوری مدرسه ابتدا دو سال اجرا شود."}]},{"id":"h3","type":"Radiobeitrag","title":"Zu gut für die Tonne: Das Problem mit den Resten","title_fa":"حیف است دور ریخته شود: مشکل غذاهای باقی‌مانده","intro_fa":"یک گزارش رادیویی دربارهٔ هدر رفتن مواد غذایی در آلمان، دلایل آن و راه‌هایی که هر کس می‌تواند برای کم کردنش به کار ببرد.","s":[{"de":"Ein halbes Brot, ein Joghurt, der gestern abgelaufen ist, und Reste vom Abendessen: Vieles davon landet im Müll.","fa":"نصف یک نان، ماستی که تاریخش دیروز گذشته و باقی‌ماندهٔ شام: بسیاری از این‌ها سر از سطل زباله درمی‌آورند."},{"de":"In Deutschland werden jedes Jahr rund elf Millionen Tonnen Lebensmittel weggeworfen.","fa":"در آلمان هر سال حدود یازده میلیون تن مواد غذایی دور ریخته می‌شود."},{"de":"Mehr als die Hälfte davon stammt nicht aus Supermärkten oder Restaurants, sondern aus privaten Haushalten.","fa":"بیش از نیمی از آن نه از سوپرمارکت‌ها یا رستوران‌ها، بلکه از خانه‌های مردم است."},{"de":"Pro Kopf sind das etwa 78 Kilogramm im Jahr.","fa":"این یعنی حدود ۷۸ کیلوگرم برای هر نفر در سال."},{"de":"Warum werfen wir so viel weg?","fa":"چرا این‌قدر دور می‌ریزیم؟"},{"de":"Ein wichtiger Grund ist, dass viele Menschen das Mindesthaltbarkeitsdatum falsch verstehen.","fa":"یک دلیل مهم این است که بسیاری از مردم «تاریخ حداقل ماندگاری» را اشتباه می‌فهمند."},{"de":"Dieses Datum bedeutet nämlich nicht, dass ein Produkt danach verdorben ist.","fa":"این تاریخ در واقع به این معنا نیست که محصول بعد از آن خراب شده است."},{"de":"Es garantiert nur, dass Geschmack und Qualität bis zu diesem Tag unverändert bleiben.","fa":"فقط تضمین می‌کند که طعم و کیفیت تا آن روز بدون تغییر می‌ماند."},{"de":"Joghurt, Nudeln oder Reis kann man oft noch Tage oder sogar Monate später essen.","fa":"ماست، ماکارونی یا برنج را اغلب می‌شود روزها یا حتی ماه‌ها بعد هم خورد."},{"de":"Anders ist es beim Verbrauchsdatum, das zum Beispiel auf frischem Hackfleisch steht.","fa":"اما «تاریخ مصرف» که مثلاً روی گوشت چرخ‌کردهٔ تازه نوشته می‌شود، فرق دارد."},{"de":"Nach diesem Datum sollte man das Produkt wirklich nicht mehr essen.","fa":"بعد از این تاریخ واقعاً نباید آن محصول را خورد."},{"de":"Ein weiterer Grund ist unser Einkaufsverhalten.","fa":"دلیل دیگر، رفتار ما هنگام خرید است."},{"de":"Wer hungrig und ohne Einkaufszettel in den Supermarkt geht, kauft meistens mehr, als er braucht.","fa":"کسی که گرسنه و بدون فهرست خرید به سوپرمارکت برود، معمولاً بیش از نیازش خرید می‌کند."},{"de":"Auch Sonderangebote wie „Drei zum Preis von zwei“ verführen dazu, große Mengen zu kaufen.","fa":"پیشنهادهای ویژه‌ای مثل «سه تا به قیمت دو تا» هم آدم را به خرید مقدار زیاد وسوسه می‌کنند."},{"de":"Dabei ist Lebensmittelverschwendung nicht nur ein ethisches Problem, sondern auch ein ökologisches.","fa":"در حالی که هدر دادن غذا نه‌تنها یک مشکل اخلاقی، بلکه یک مشکل زیست‌محیطی هم هست."},{"de":"Für die Produktion werden nämlich Wasser, Energie und Ackerflächen verbraucht, die am Ende umsonst genutzt wurden.","fa":"چون برای تولید آن آب، انرژی و زمین کشاورزی مصرف می‌شود که در نهایت بیهوده به کار رفته است."},{"de":"Inzwischen gibt es aber viele Initiativen, die etwas dagegen tun.","fa":"اما امروزه ابتکارهای زیادی هست که برای مقابله با این وضع کاری انجام می‌دهند."},{"de":"Beim sogenannten Foodsharing geben Privatleute und Geschäfte übrig gebliebene Lebensmittel kostenlos weiter.","fa":"در روشی به نام «اشتراک غذا»، افراد و فروشگاه‌ها مواد غذایی اضافه را رایگان به دیگران می‌دهند."},{"de":"Mit speziellen Apps kann man außerdem in Restaurants und Bäckereien Reste zu einem günstigen Preis kaufen.","fa":"علاوه بر این با اپلیکیشن‌های مخصوص می‌شود غذاهای باقی‌ماندهٔ رستوران‌ها و نانوایی‌ها را ارزان خرید."},{"de":"Und auch zu Hause kann jeder etwas tun: Aus altem Brot lassen sich zum Beispiel Knödel oder Croutons machen.","fa":"در خانه هم هر کسی می‌تواند کاری بکند: مثلاً از نان بیات می‌شود کوفته‌نان یا کروتون درست کرد."},{"de":"Die Bundesregierung hat sich das Ziel gesetzt, die Lebensmittelabfälle bis 2030 zu halbieren.","fa":"دولت فدرال هدف گذاشته است که تا سال ۲۰۳۰ ضایعات مواد غذایی را نصف کند."},{"de":"Ob das gelingt, hängt also auch von jedem Einzelnen von uns ab.","fa":"پس اینکه این کار موفق شود یا نه، به تک‌تک ما هم بستگی دارد."}],"q":[{"q":"Woher kommt der größte Teil der weggeworfenen Lebensmittel?","opts":["aus Supermärkten","aus Restaurants","aus privaten Haushalten"],"a":2,"fa":"در گزارش آمده که بیش از نیمی از آن از خانه‌های مردم است، نه از سوپرمارکت‌ها یا رستوران‌ها."},{"q":"Was bedeutet das Mindesthaltbarkeitsdatum?","opts":["Geschmack und Qualität bleiben bis zu diesem Tag garantiert.","Das Produkt ist danach sofort giftig.","Man muss das Produkt genau an diesem Tag essen."],"a":0,"fa":"این تاریخ فقط تضمین می‌کند که طعم و کیفیت تا آن روز تغییر نمی‌کند."},{"q":"Bei welchem Produkt sollte man das Datum besonders ernst nehmen?","opts":["bei Nudeln","bei Reis","bei frischem Hackfleisch"],"a":2,"fa":"روی گوشت چرخ‌کردهٔ تازه «تاریخ مصرف» نوشته می‌شود و بعد از آن نباید آن را خورد."},{"q":"Warum kaufen viele Menschen zu viel?","opts":["Weil sie hungrig und ohne Einkaufszettel einkaufen.","Weil Lebensmittel sehr teuer sind.","Weil die Supermärkte früh schließen."],"a":0,"fa":"کسی که گرسنه و بدون فهرست خرید برود، معمولاً بیش از نیاز می‌خرد."},{"q":"Was ist Foodsharing?","opts":["Man gibt übrig gebliebene Lebensmittel kostenlos weiter.","Man kocht gemeinsam in einem Restaurant.","Man verkauft Lebensmittel teurer weiter."],"a":0,"fa":"در «اشتراک غذا» افراد و فروشگاه‌ها غذای اضافه را رایگان به دیگران می‌دهند."},{"q":"Welches Ziel hat sich die Bundesregierung gesetzt?","opts":["alle Lebensmittel billiger zu machen","die Lebensmittelabfälle bis 2030 zu halbieren","Lebensmittelabfälle bis 2030 ganz zu verbieten"],"a":1,"fa":"هدف دولت این است که ضایعات غذایی تا سال ۲۰۳۰ نصف شود."}]}],"8":[{"id":"h1","type":"Radiobeitrag","title":"Fünf Ringe für Skaten und Surfen","title_fa":"پنج حلقه برای اسکیت و موج‌سواری","intro_fa":"یک گزارش رادیویی دربارهٔ ورود رشته‌های ورزشی پرطرفدار مثل اسکیت‌بورد و موج‌سواری به المپیک و موافقان و مخالفان آن.","s":[{"de":"Lange galten Skateboarden und Surfen als Freizeitbeschäftigung für junge Leute, die mit traditionellen Sportarten wenig anfangen konnten.","fa":"مدت‌ها اسکیت‌بورد و موج‌سواری سرگرمی جوانانی به شمار می‌رفت که با رشته‌های ورزشی سنتی میانهٔ خوبی نداشتند."},{"de":"Doch seit den Sommerspielen in Tokio gehören beide Sportarten offiziell zum olympischen Programm.","fa":"اما از زمان بازی‌های تابستانی توکیو، هر دو رشته رسماً جزو برنامهٔ المپیک هستند."},{"de":"Auch Sportklettern war dort zum ersten Mal dabei, und in Paris kam später noch Breaking hinzu, also eine Form des Breakdance.","fa":"سنگ‌نوردی ورزشی هم آنجا برای اولین بار حضور داشت و بعدها در پاریس «بریکینگ»، یعنی نوعی بریک‌دنس، هم اضافه شد."},{"de":"Warum nimmt das Internationale Olympische Komitee solche Trendsportarten auf?","fa":"چرا کمیتهٔ بین‌المللی المپیک چنین رشته‌های ورزشی مُدِ روز را می‌پذیرد؟"},{"de":"Der wichtigste Grund dürfte das Publikum sein.","fa":"احتمالاً مهم‌ترین دلیل، مخاطبان هستند."},{"de":"Viele junge Menschen schauen sich klassische Disziplinen wie Rudern oder Leichtathletik kaum noch im Fernsehen an.","fa":"بسیاری از جوانان رشته‌های کلاسیکی مثل قایقرانی یا دوومیدانی را دیگر به‌ندرت در تلویزیون تماشا می‌کنند."},{"de":"Indem man neue Sportarten ins Programm holt, möchte man diese Zielgruppe zurückgewinnen.","fa":"با وارد کردن رشته‌های جدید به برنامه، می‌خواهند این گروه مخاطب را دوباره جذب کنند."},{"de":"Die Rechnung könnte aufgehen, denn die Wettkämpfe im Skaten wurden nach Angaben der Veranstalter online besonders oft angesehen.","fa":"این حساب ممکن است درست از آب دربیاید، چون به گفتهٔ برگزارکنندگان مسابقات اسکیت در اینترنت بسیار زیاد دیده شد."},{"de":"In der Szene selbst ist die Freude allerdings nicht ungeteilt.","fa":"البته در میان اهالی خود این ورزش، همه به یک اندازه خوشحال نیستند."},{"de":"Viele Skater sehen ihren Sport eher als Lebensgefühl und nicht als Leistungssport.","fa":"بسیاری از اسکیت‌بازها ورزششان را بیشتر یک سبک زندگی می‌دانند تا ورزش قهرمانی."},{"de":"Sie befürchten, dass Verbände, Trainingspläne und Kampfrichter die Kreativität zerstören.","fa":"آن‌ها نگران‌اند که فدراسیون‌ها، برنامه‌های تمرینی و داوران خلاقیت را از بین ببرند."},{"de":"Ein Skater aus Berlin hat es so formuliert: Beim Skaten gehe es um Freiheit, nicht um Medaillen.","fa":"یک اسکیت‌باز اهل برلین این‌طور گفته است: در اسکیت موضوع آزادی است، نه مدال."},{"de":"Andere sehen vor allem die Chancen.","fa":"عده‌ای دیگر بیشتر فرصت‌ها را می‌بینند."},{"de":"Seit der Aufnahme ins olympische Programm fließt deutlich mehr Geld in neue Skateparks und in die Förderung von Talenten.","fa":"از زمان ورود به برنامهٔ المپیک، پول بسیار بیشتری صرف پارک‌های اسکیت جدید و حمایت از استعدادها می‌شود."},{"de":"Davon profitieren auch Mädchen, die früher in der Szene kaum sichtbar waren.","fa":"دخترانی هم که قبلاً در این فضا به‌ندرت دیده می‌شدند، از این موضوع سود می‌برند."},{"de":"Beim Surfen gibt es dagegen ein ganz praktisches Problem: Man ist von den Wellen abhängig.","fa":"در مقابل، موج‌سواری یک مشکل کاملاً عملی دارد: آدم به موج‌ها وابسته است."},{"de":"Deshalb fanden die Surfwettbewerbe der Spiele von Paris gar nicht in Frankreich statt, sondern auf Tahiti im Pazifik.","fa":"به همین دلیل مسابقات موج‌سواری بازی‌های پاریس اصلاً در خاک اصلی فرانسه برگزار نشد، بلکه در تاهیتی در اقیانوس آرام."},{"de":"Die Entfernung von Paris dorthin beträgt rund fünfzehntausend Kilometer.","fa":"فاصلهٔ پاریس تا آنجا حدود پانزده هزار کیلومتر است."},{"de":"In Zukunft könnten auch künstliche Wellenanlagen genutzt werden, die heute schon in einigen Städten gebaut werden.","fa":"در آینده ممکن است از دستگاه‌های موج مصنوعی هم استفاده شود که امروز در برخی شهرها ساخته می‌شوند."},{"de":"Ob Breaking auch in Zukunft olympisch bleibt, ist dagegen unsicher.","fa":"در مقابل، معلوم نیست بریکینگ در آینده هم رشتهٔ المپیکی بماند."},{"de":"Für die Spiele in Los Angeles wurde die Sportart jedenfalls nicht wieder ausgewählt.","fa":"به هر حال این رشته برای بازی‌های لس‌آنجلس دوباره انتخاب نشد."},{"de":"Das zeigt: Nicht jeder Trend muss sich langfristig durchsetzen.","fa":"این نشان می‌دهد که هر مُدی لزوماً در درازمدت جا نمی‌افتد."}],"q":[{"q":"Seit wann gehören Skaten und Surfen zum olympischen Programm?","opts":["seit den Spielen in Los Angeles","seit den Spielen in Tokio","seit den Spielen in Berlin"],"a":1,"fa":"در گزارش آمده که هر دو رشته از بازی‌های تابستانی توکیو جزو برنامهٔ المپیک‌اند."},{"q":"Was ist laut Beitrag vermutlich der wichtigste Grund für die neuen Sportarten?","opts":["Die Athleten haben es gefordert.","Man möchte junges Publikum zurückgewinnen.","Sie sind billiger als andere Sportarten."],"a":1,"fa":"«مهم‌ترین دلیل احتمالاً مخاطبان است»: جوانان رشته‌های کلاسیک را کمتر تماشا می‌کنند و می‌خواهند آن‌ها را دوباره جذب کنند."},{"q":"Was befürchten viele Skater?","opts":["Dass Verbände und Kampfrichter die Kreativität zerstören.","Dass es zu wenige Skateparks gibt.","Dass Skaten zu gefährlich wird."],"a":0,"fa":"اسکیت‌بازها نگران‌اند که فدراسیون‌ها، برنامه‌های تمرینی و داوران خلاقیت را از بین ببرند."},{"q":"Welchen Vorteil der olympischen Teilnahme nennt der Beitrag?","opts":["Die Wettkämpfe werden kürzer.","Es fließt mehr Geld in Skateparks und Talentförderung.","Skater müssen nicht mehr trainieren."],"a":1,"fa":"از زمان ورود به المپیک پول بیشتری صرف پارک‌های اسکیت و حمایت از استعدادها می‌شود."},{"q":"Wo fanden die Surfwettbewerbe der Spiele von Paris statt?","opts":["auf Tahiti","an der Atlantikküste Frankreichs","in einer künstlichen Wellenanlage in Paris"],"a":0,"fa":"مسابقات موج‌سواری در تاهیتی در اقیانوس آرام برگزار شد، حدود پانزده هزار کیلومتر دور از پاریس."},{"q":"Was erfährt man über Breaking?","opts":["Es ist seit Tokio olympisch.","Es wird in Los Angeles wieder ausgetragen.","Es wurde für Los Angeles nicht wieder ausgewählt."],"a":2,"fa":"بریکینگ در پاریس اضافه شد، اما برای بازی‌های لس‌آنجلس دوباره انتخاب نشد."}]},{"id":"h2","type":"Erklärvideo-Text","title":"Fit genug? So checkst du deine Werte","title_fa":"به اندازهٔ کافی آماده‌ای؟ این‌طور شاخص‌هایت را بسنج","intro_fa":"یک مربی ورزشی در یک ویدئوی آموزشی توضیح می‌دهد که چطور می‌شود ضربان استراحت، استقامت و انعطاف‌پذیری را سنجید و بهتر کرد.","s":[{"de":"Hallo zusammen, in diesem Video zeige ich euch, wie ihr herausfinden könnt, wie fit ihr wirklich seid.","fa":"سلام به همه، در این ویدئو نشانتان می‌دهم چطور می‌توانید بفهمید واقعاً چقدر آمادگی جسمانی دارید."},{"de":"Viele von euch tragen wahrscheinlich eine Fitnessuhr, die jeden Tag Schritte, Puls und Schlaf misst.","fa":"احتمالاً بسیاری از شما ساعت ورزشی دارید که هر روز تعداد قدم‌ها، نبض و خواب را اندازه می‌گیرد."},{"de":"Aber was bedeuten diese Zahlen eigentlich?","fa":"اما این اعداد در واقع چه معنایی دارند؟"},{"de":"Fangen wir mit dem Ruhepuls an, also der Zahl der Herzschläge pro Minute, wenn ihr entspannt seid.","fa":"با ضربان استراحت شروع کنیم، یعنی تعداد ضربان قلب در دقیقه وقتی آرام هستید."},{"de":"Am besten messt ihr ihn morgens direkt nach dem Aufwachen, noch bevor ihr aufsteht.","fa":"بهتر است آن را صبح بلافاصله بعد از بیدار شدن و پیش از بلند شدن از رختخواب اندازه بگیرید."},{"de":"Bei Erwachsenen liegt er normalerweise zwischen 60 und 80 Schlägen pro Minute.","fa":"در بزرگسالان این عدد معمولاً بین ۶۰ تا ۸۰ ضربه در دقیقه است."},{"de":"Gut trainierte Ausdauersportler haben oft sogar einen Ruhepuls von unter 50.","fa":"ورزشکاران استقامتیِ خوب‌تمرین‌کرده اغلب حتی ضربان استراحتی زیر ۵۰ دارند."},{"de":"Das liegt daran, dass ihr Herz durch das Training stärker geworden ist und mit jedem Schlag mehr Blut pumpt.","fa":"دلیلش این است که قلبشان با تمرین قوی‌تر شده و با هر ضربه خون بیشتری پمپ می‌کند."},{"de":"Der zweite Wert ist die Ausdauer, die ihr ganz einfach mit dem sogenannten Zwölf-Minuten-Lauf testen könnt.","fa":"شاخص دوم استقامت است که می‌توانید خیلی ساده با «دوی دوازده‌دقیقه‌ای» آن را بسنجید."},{"de":"Dabei lauft ihr zwölf Minuten lang so schnell wie möglich und messt danach die Strecke.","fa":"در این آزمون دوازده دقیقه تا جایی که می‌توانید سریع می‌دوید و بعد مسافت را اندازه می‌گیرید."},{"de":"Wer als junger Erwachsener mehr als 2400 Meter schafft, ist schon ziemlich gut in Form.","fa":"کسی که در جوانی بیش از ۲۴۰۰ متر بدود، آمادگی جسمانی نسبتاً خوبی دارد."},{"de":"Drittens solltet ihr eure Beweglichkeit nicht vergessen.","fa":"سوم اینکه نباید انعطاف‌پذیری بدنتان را فراموش کنید."},{"de":"Setzt euch mit gestreckten Beinen auf den Boden und versucht, mit den Händen eure Füße zu berühren.","fa":"با پاهای صاف روی زمین بنشینید و سعی کنید با دست‌ها نوک پاهایتان را لمس کنید."},{"de":"Wenn ihr das nicht schafft, müsst ihr euch keine Sorgen machen, aber ihr solltet regelmäßig dehnen.","fa":"اگر نتوانستید، لازم نیست نگران شوید، اما باید مرتب حرکات کششی انجام دهید."},{"de":"Und wie könnt ihr eure Werte verbessern?","fa":"و چطور می‌توانید این شاخص‌ها را بهتر کنید؟"},{"de":"Eure Ausdauer steigert ihr am besten, indem ihr dreimal pro Woche mindestens 30 Minuten joggt, schwimmt oder Rad fahrt.","fa":"بهترین راه بالا بردن استقامت این است که هفته‌ای سه بار دست‌کم ۳۰ دقیقه بدوید، شنا کنید یا دوچرخه‌سواری کنید."},{"de":"Dadurch, dass ihr langsam anfangt und die Belastung Schritt für Schritt erhöht, vermeidet ihr Verletzungen.","fa":"با آرام شروع کردن و بیشتر کردن قدم‌به‌قدم فشار تمرین، از آسیب‌دیدگی جلوگیری می‌کنید."},{"de":"Ein wichtiger Hinweis zum Schluss: Fitnessuhren sind keine medizinischen Geräte.","fa":"یک نکتهٔ مهم در پایان: ساعت‌های ورزشی دستگاه پزشکی نیستند."},{"de":"Ihre Messungen können ungenau sein, besonders beim Puls während intensiver Bewegung.","fa":"اندازه‌گیری‌هایشان ممکن است دقیق نباشد، به‌خصوص اندازه‌گیری نبض هنگام فعالیت شدید."},{"de":"Wenn euer Ruhepuls über längere Zeit sehr hoch ist oder ihr beim Sport Schmerzen in der Brust habt, geht bitte zum Arzt.","fa":"اگر ضربان استراحتتان مدت طولانی خیلی بالا باشد یا هنگام ورزش درد قفسهٔ سینه داشته باشید، لطفاً به پزشک مراجعه کنید."},{"de":"Und vergesst nicht: Zahlen sind nur ein Teil der Wahrheit, entscheidend ist, dass euch die Bewegung Spaß macht.","fa":"و فراموش نکنید: اعداد فقط بخشی از حقیقت‌اند؛ مهم این است که از تحرک لذت ببرید."},{"de":"Wenn euch das Video gefallen hat, abonniert gern meinen Kanal.","fa":"اگر این ویدئو را دوست داشتید، کانال من را دنبال کنید."}],"q":[{"q":"Wann sollte man den Ruhepuls am besten messen?","opts":["morgens nach dem Aufwachen, vor dem Aufstehen","direkt nach dem Sport","abends vor dem Schlafengehen"],"a":0,"fa":"گوینده می‌گوید بهتر است ضربان استراحت را صبح بلافاصله بعد از بیدار شدن و پیش از بلند شدن اندازه بگیرید."},{"q":"Warum haben Ausdauersportler oft einen niedrigen Ruhepuls?","opts":["Weil ihr Herz stärker ist und mit jedem Schlag mehr Blut pumpt.","Weil ihre Fitnessuhren falsch messen.","Weil sie weniger schlafen."],"a":0,"fa":"قلب آن‌ها با تمرین قوی‌تر شده و با هر ضربه خون بیشتری پمپ می‌کند."},{"q":"Wie funktioniert der Zwölf-Minuten-Lauf?","opts":["Man läuft zwölf Minuten so schnell wie möglich und misst die Strecke.","Man geht zwölf Minuten langsam spazieren.","Man läuft zwölf Kilometer und misst die Zeit."],"a":0,"fa":"دوازده دقیقه تا حد امکان سریع می‌دوید و بعد مسافت را اندازه می‌گیرید."},{"q":"Wie kann man laut Video die Ausdauer verbessern?","opts":["indem man jeden Tag zwei Stunden trainiert","indem man nur dehnt","indem man dreimal pro Woche mindestens 30 Minuten Ausdauersport macht"],"a":2,"fa":"توصیه این است: هفته‌ای سه بار دست‌کم ۳۰ دقیقه دویدن، شنا یا دوچرخه‌سواری."},{"q":"Wie vermeidet man Verletzungen?","opts":["dadurch, dass man langsam anfängt und die Belastung schrittweise erhöht","dadurch, dass man nur am Wochenende trainiert","dadurch, dass man eine Fitnessuhr trägt"],"a":0,"fa":"گوینده می‌گوید با آرام شروع کردن و افزایش قدم‌به‌قدم فشار تمرین از آسیب جلوگیری می‌شود."},{"q":"Was sagt der Sprecher über Fitnessuhren?","opts":["Sie sind keine medizinischen Geräte und können ungenau messen.","Sie messen immer ganz genau.","Sie ersetzen den Arzt."],"a":0,"fa":"او تأکید می‌کند که ساعت‌های ورزشی دستگاه پزشکی نیستند و ممکن است نادقیق اندازه بگیرند."}]},{"id":"h3","type":"Kurzvortrag","title":"Krankenversicherung individuell?","title_fa":"بیمهٔ درمانی شخصی‌سازی‌شده؟","intro_fa":"یک کارشناس سلامت در یک سخنرانی کوتاه دربارهٔ برنامه‌های پاداش صندوق‌های بیمهٔ درمانی و مزایا و خطرهای آن صحبت می‌کند.","s":[{"de":"Sehr geehrte Damen und Herren, herzlich willkommen zu meinem Kurzvortrag über ein Thema, das uns alle betrifft: die Krankenversicherung.","fa":"خانم‌ها و آقایان محترم، به سخنرانی کوتاه من دربارهٔ موضوعی که به همهٔ ما مربوط است خوش آمدید: بیمهٔ درمانی."},{"de":"In Deutschland sind rund 90 Prozent der Menschen gesetzlich versichert.","fa":"در آلمان حدود ۹۰ درصد مردم بیمهٔ درمانی همگانی (قانونی) دارند."},{"de":"Das System beruht auf dem Prinzip der Solidarität: Die Gesunden zahlen mit für die Kranken, die Jungen für die Alten.","fa":"این نظام بر اصل همبستگی استوار است: سالم‌ها برای بیماران و جوان‌ها برای سالمندان هم پرداخت می‌کنند."},{"de":"Die Beiträge richten sich nach dem Einkommen und nicht nach dem persönlichen Gesundheitsrisiko.","fa":"حق بیمه بر اساس درآمد تعیین می‌شود، نه بر اساس خطر سلامتی هر فرد."},{"de":"In den letzten Jahren haben jedoch fast alle Krankenkassen sogenannte Bonusprogramme eingeführt.","fa":"اما در سال‌های اخیر تقریباً همهٔ صندوق‌های بیمه برنامه‌هایی به نام «برنامهٔ پاداش» راه انداخته‌اند."},{"de":"Wer regelmäßig Sport treibt, zur Vorsorgeuntersuchung geht oder nicht raucht, sammelt Punkte.","fa":"کسی که مرتب ورزش کند، به معاینهٔ پیشگیرانه برود یا سیگار نکشد، امتیاز جمع می‌کند."},{"de":"Diese Punkte kann man dann gegen Geld oder Prämien eintauschen, oft sind das zwischen 50 und 150 Euro im Jahr.","fa":"این امتیازها را بعد می‌شود با پول یا جایزه عوض کرد؛ اغلب بین ۵۰ تا ۱۵۰ یورو در سال."},{"de":"Einige Kassen gehen noch weiter und belohnen ihre Mitglieder dafür, dass sie Daten aus ihrer Fitnessuhr übermitteln.","fa":"برخی صندوق‌ها از این هم فراتر می‌روند و به اعضایشان برای ارسال داده‌های ساعت ورزشی‌شان پاداش می‌دهند."},{"de":"Die Befürworter argumentieren, dass man die Menschen auf diese Weise zu einem gesünderen Leben motiviert.","fa":"موافقان استدلال می‌کنند که به این شیوه مردم به زندگی سالم‌تر تشویق می‌شوند."},{"de":"Langfristig könnten dadurch die Kosten für das gesamte System sinken.","fa":"در درازمدت ممکن است به این ترتیب هزینه‌های کل نظام کاهش پیدا کند."},{"de":"Das mag auf den ersten Blick überzeugend klingen, aber es gibt auch ernsthafte Bedenken.","fa":"این ممکن است در نگاه اول قانع‌کننده به نظر برسد، اما نگرانی‌های جدی هم وجود دارد."},{"de":"Erstens profitieren vor allem Menschen, die ohnehin schon sportlich und gesund sind.","fa":"اول اینکه بیشتر کسانی سود می‌برند که از قبل هم ورزشکار و سالم‌اند."},{"de":"Wer chronisch krank ist oder eine Behinderung hat, kann viele Punkte gar nicht sammeln.","fa":"کسی که بیماری مزمن یا معلولیت دارد، اصلاً نمی‌تواند بسیاری از امتیازها را جمع کند."},{"de":"Zweitens stellt sich die Frage des Datenschutzes, denn Gesundheitsdaten gehören zu den sensibelsten Daten überhaupt.","fa":"دوم اینکه مسئلهٔ حفاظت از داده‌ها پیش می‌آید، چون داده‌های سلامت جزو حساس‌ترین داده‌ها هستند."},{"de":"Kritiker befürchten, dass am Ende individuelle Tarife stehen, bei denen Kranke mehr bezahlen müssen.","fa":"منتقدان نگران‌اند که در نهایت تعرفه‌های فردی پدید آید که در آن بیماران باید بیشتر بپردازند."},{"de":"Damit wäre das Prinzip der Solidarität in Gefahr.","fa":"در آن صورت اصل همبستگی در خطر می‌افتد."},{"de":"Ein Bonusprogramm mag ein sinnvoller Anreiz sein, aber es darf niemanden benachteiligen.","fa":"برنامهٔ پاداش شاید انگیزهٔ معقولی باشد، اما نباید باعث تبعیض علیه کسی شود."},{"de":"Ich persönlich halte freiwillige Programme ohne Übermittlung von Fitnessdaten für einen guten Kompromiss.","fa":"من شخصاً برنامه‌های داوطلبانه بدون ارسال داده‌های ورزشی را راه میانهٔ خوبی می‌دانم."},{"de":"Wie viel Kontrolle wir akzeptieren wollen, sollte aber nicht allein von den Krankenkassen entschieden, sondern gesellschaftlich diskutiert werden.","fa":"اما اینکه چه میزان کنترل را می‌خواهیم بپذیریم، نباید فقط صندوق‌های بیمه تصمیم بگیرند، بلکه باید در جامعه درباره‌اش بحث شود."},{"de":"Ich freue mich jetzt auf Ihre Meinungen und Fragen.","fa":"حالا مشتاق شنیدن نظرها و سؤال‌های شما هستم."}],"q":[{"q":"Worauf beruht die gesetzliche Krankenversicherung?","opts":["auf dem Alter der Versicherten","auf dem persönlichen Gesundheitsrisiko","auf dem Prinzip der Solidarität"],"a":2,"fa":"سخنران می‌گوید نظام بر اصل همبستگی استوار است و حق بیمه به درآمد بستگی دارد، نه به خطر سلامتی."},{"q":"Wofür bekommt man in Bonusprogrammen Punkte?","opts":["für einen Wechsel der Krankenkasse","für möglichst viele Arztbesuche","für Sport, Vorsorgeuntersuchungen oder Nichtrauchen"],"a":2,"fa":"کسی که ورزش کند، به معاینهٔ پیشگیرانه برود یا سیگار نکشد، امتیاز می‌گیرد."},{"q":"Wie viel Geld bekommt man oft durch ein Bonusprogramm?","opts":["zwischen 5 und 15 Euro im Monat","zwischen 50 und 150 Euro im Jahr","über 1000 Euro im Jahr"],"a":1,"fa":"گفته شد که اغلب بین ۵۰ تا ۱۵۰ یورو در سال است."},{"q":"Wer profitiert laut Vortrag vor allem von Bonusprogrammen?","opts":["Menschen mit einer Behinderung","chronisch kranke Menschen","Menschen, die schon sportlich und gesund sind"],"a":2,"fa":"بیشتر کسانی سود می‌برند که از قبل ورزشکار و سالم‌اند؛ بیماران مزمن و افراد دارای معلولیت امتیاز کمتری جمع می‌کنند."},{"q":"Was befürchten Kritiker?","opts":["individuelle Tarife, bei denen Kranke mehr bezahlen","dass Sport verboten wird","dass Fitnessuhren zu teuer werden"],"a":0,"fa":"منتقدان نگران تعرفه‌های فردی‌اند که در آن بیماران باید بیشتر بپردازند."},{"q":"Welche Lösung findet der Redner gut?","opts":["Pflichtprogramme mit Fitnessuhr","die Abschaffung der Krankenversicherung","freiwillige Programme ohne Übermittlung von Fitnessdaten"],"a":2,"fa":"او برنامه‌های داوطلبانه بدون ارسال داده‌های ورزشی را راه میانهٔ خوبی می‌داند."}]}],"9":[{"id":"h1","type":"Radiobeitrag","title":"Was Angestellte wirklich motiviert","title_fa":"چه چیزی واقعاً به کارمندان انگیزه می‌دهد","intro_fa":"گوینده‌ی یک برنامه‌ی رادیویی درباره‌ی دنیای کار، نتایج یک آزمایش و یک نظرسنجی درباره‌ی انگیزه‌ی کارمندان را گزارش می‌دهد.","s":[{"de":"Guten Tag und willkommen zu unserer Sendung „Arbeitswelt heute“.","fa":"روز بخیر و به برنامه‌ی ما، «دنیای کار امروز»، خوش آمدید."},{"de":"Heute geht es um eine Frage, die sich viele Unternehmen stellen: Was motiviert Angestellte wirklich?","fa":"امروز موضوع پرسشی است که بسیاری از شرکت‌ها از خودشان می‌پرسند: چه چیزی واقعاً به کارمندان انگیزه می‌دهد؟"},{"de":"Lange Zeit glaubte man, dass vor allem materielle Anreize wie ein höheres Gehalt oder Gutscheine entscheidend sind.","fa":"مدت‌ها تصور می‌شد که بیش از همه مشوق‌های مادی، مثل حقوق بیشتر یا کارت هدیه، تعیین‌کننده هستند."},{"de":"Eine neue Studie aus den USA zeigt jedoch, dass dieses Bild nicht ganz stimmt.","fa":"اما یک پژوهش جدید از آمریکا نشان می‌دهد که این تصور کاملاً درست نیست."},{"de":"In einem Experiment sollten Studierende kleine Figuren aus Plastikteilen zusammenbauen und erhielten für jede fertiggestellte Figur etwas Geld.","fa":"در یک آزمایش، دانشجویان باید آدمک‌های کوچکی را از قطعات پلاستیکی سر هم می‌کردند و برای هر آدمکِ تکمیل‌شده مقداری پول می‌گرفتند."},{"de":"Bei der ersten Gruppe wurden die fertigen Figuren gut sichtbar auf den Tisch gestellt.","fa":"در گروه اول، آدمک‌های آماده به‌طور کاملاً پیدا روی میز گذاشته می‌شدند."},{"de":"Bei der zweiten Gruppe dagegen wurden die gerade gebauten Figuren sofort vor ihren Augen wieder auseinandergenommen.","fa":"اما در گروه دوم، آدمک‌هایی که تازه ساخته شده بودند، بلافاصله جلوی چشمشان دوباره از هم باز می‌شدند."},{"de":"Das Ergebnis war eindeutig: Die erste Gruppe baute im Durchschnitt elf Figuren, die zweite nur sieben.","fa":"نتیجه روشن بود: گروه اول به‌طور میانگین یازده آدمک ساخت و گروه دوم فقط هفت تا."},{"de":"Obwohl die Bezahlung genau gleich war, fehlte der zweiten Gruppe offenbar der Sinn ihrer Arbeit.","fa":"با اینکه دستمزد دقیقاً یکسان بود، ظاهراً گروه دوم معنای کارش را از دست داده بود."},{"de":"Die Forscher schließen daraus, dass Anerkennung und sichtbare Ergebnisse wichtige Faktoren für die Produktivität sind.","fa":"پژوهشگران از این نتیجه می‌گیرند که قدردانی و نتایج قابل‌دیدن عوامل مهمی برای بهره‌وری هستند."},{"de":"Dieses Ergebnis lässt sich auch auf den Berufsalltag übertragen.","fa":"این نتیجه را می‌توان به زندگی روزمره‌ی کاری هم تعمیم داد."},{"de":"Wer ständig das Gefühl hat, dass seine Arbeit niemanden interessiert, verliert schnell die Lust.","fa":"کسی که مدام احساس کند کارش برای هیچ‌کس مهم نیست، خیلی زود انگیزه‌اش را از دست می‌دهد."},{"de":"Laut einer Umfrage unter zweitausend Beschäftigten in Deutschland nennen zwei Drittel die Wertschätzung als wichtigsten Grund für ihre Zufriedenheit im Job.","fa":"طبق یک نظرسنجی از دو هزار شاغل در آلمان، دو سوم آن‌ها قدرشناسی را مهم‌ترین دلیل رضایتشان از شغل می‌دانند."},{"de":"Ein gutes Gehalt kommt erst an dritter Stelle, nach einem guten Verhältnis zu den Kollegen.","fa":"حقوق خوب تازه در جایگاه سوم قرار دارد، بعد از رابطه‌ی خوب با همکاران."},{"de":"Das bedeutet aber nicht, dass Geld unwichtig ist.","fa":"اما این به آن معنا نیست که پول بی‌اهمیت است."},{"de":"Wer schlecht bezahlt wird, fühlt sich auf Dauer nicht wertgeschätzt, auch wenn er viel gelobt wird.","fa":"کسی که حقوق کمی می‌گیرد، در درازمدت احساس نمی‌کند که قدرش دانسته می‌شود، حتی اگر زیاد از او تعریف شود."},{"de":"Experten empfehlen deshalb eine Mischung aus fairer Bezahlung, spannenden Herausforderungen und ehrlicher Anerkennung.","fa":"به همین دلیل کارشناسان ترکیبی از دستمزد منصفانه، چالش‌های جذاب و قدردانی صادقانه را توصیه می‌کنند."},{"de":"Auch zu viel Druck ist nicht hilfreich, denn gestresste Mitarbeiter machen mehr Fehler.","fa":"فشار زیاد هم کمکی نمی‌کند، چون کارمندانِ تحت استرس اشتباه‌های بیشتری می‌کنند."},{"de":"Eine motivierte Belegschaft ist dagegen engagierter, kreativer und seltener krank.","fa":"در مقابل، کارکنانِ باانگیزه متعهدتر و خلاق‌تر هستند و کمتر بیمار می‌شوند."},{"de":"Für Unternehmen ist das also nicht nur eine Frage der Freundlichkeit, sondern auch eine Frage des Erfolgs.","fa":"پس برای شرکت‌ها این فقط مسئله‌ی مهربانی نیست، بلکه مسئله‌ی موفقیت هم هست."},{"de":"Im zweiten Teil unserer Sendung hören Sie, wie ein Handwerksbetrieb aus Freiburg seine Mitarbeiter bei Laune hält.","fa":"در بخش دوم برنامه می‌شنوید که یک کارگاه صنعتگری در فرایبورگ چطور حال و حوصله‌ی کارکنانش را خوب نگه می‌دارد."}],"q":[{"q":"Was mussten die Teilnehmer im Experiment tun?","opts":["Figuren aus Plastikteilen bauen","Gutscheine verteilen","Fragebögen ausfüllen"],"a":0,"fa":"گوینده می‌گوید دانشجویان باید آدمک‌های کوچکی را از قطعات پلاستیکی سر هم می‌کردند."},{"q":"Was passierte bei der zweiten Gruppe?","opts":["Sie bekam mehr Geld.","Ihre Figuren wurden sofort wieder auseinandergenommen.","Sie durfte die Figuren mit nach Hause nehmen."],"a":1,"fa":"در گروه دوم آدمک‌های تازه‌ساخته بلافاصله جلوی چشمشان از هم باز می‌شدند."},{"q":"Wie viele Figuren baute die erste Gruppe im Durchschnitt?","opts":["sieben","elf","neun"],"a":1,"fa":"گروه اول به‌طور میانگین یازده آدمک ساخت و گروه دوم فقط هفت تا."},{"q":"Was ist laut Umfrage der wichtigste Grund für die Zufriedenheit im Job?","opts":["flexible Arbeitszeiten","ein hohes Gehalt","die Wertschätzung"],"a":2,"fa":"دو سوم شاغلان قدرشناسی را مهم‌ترین دلیل رضایت شغلی می‌دانند؛ حقوق تازه در جایگاه سوم است."},{"q":"Welche Rolle spielt das Gehalt laut Beitrag?","opts":["Es steht an erster Stelle.","Es ist völlig unwichtig.","Es ist wichtig, aber nicht allein entscheidend."],"a":2,"fa":"گوینده می‌گوید پول بی‌اهمیت نیست، اما کارشناسان ترکیبی از دستمزد منصفانه، چالش و قدردانی را توصیه می‌کنند."},{"q":"Worum geht es im zweiten Teil der Sendung?","opts":["um einen Handwerksbetrieb aus Freiburg","um eine neue Studie aus den USA","um gestresste Studierende"],"a":0,"fa":"در پایان گفته می‌شود که بخش دوم درباره‌ی یک کارگاه صنعتگری در فرایبورگ است."}]},{"id":"h2","type":"Kurzvortrag","title":"Lob ist nicht gleich Lob","title_fa":"هر تعریفی مثل هم نیست","intro_fa":"یک مربی در یک دوره‌ی آموزشی برای همکارانش سخنرانی کوتاهی درباره‌ی مزایا و معایب تعریف و تمجید ارائه می‌دهد.","s":[{"de":"Liebe Kolleginnen und Kollegen, in meinem kurzen Vortrag möchte ich über ein Thema sprechen, das uns alle betrifft: das Loben.","fa":"همکاران عزیز، در سخنرانی کوتاهم می‌خواهم درباره‌ی موضوعی صحبت کنم که به همه‌ی ما مربوط است: تعریف کردن."},{"de":"Die meisten Menschen sind überzeugt, dass Lob immer motivierend wirkt.","fa":"بیشتر مردم مطمئن‌اند که تعریف همیشه انگیزه‌بخش است."},{"de":"Die Forschung zeigt aber, dass Lob nicht gleich Lob ist.","fa":"اما پژوهش‌ها نشان می‌دهند که هر تعریفی مثل هم نیست."},{"de":"Zunächst zu den Vorteilen.","fa":"اول درباره‌ی مزایا."},{"de":"Ein ehrliches Lob stärkt das Selbstvertrauen und gibt uns das Gefühl, dass unsere Leistung gesehen wird.","fa":"یک تعریف صادقانه اعتماد به نفس را تقویت می‌کند و این حس را به ما می‌دهد که کارمان دیده می‌شود."},{"de":"Besonders bei neuen Aufgaben kann eine ermutigende Rückmeldung helfen, nicht aufzugeben.","fa":"به‌خصوص در کارهای تازه، یک بازخورد دلگرم‌کننده می‌تواند کمک کند که آدم دست نکشد."},{"de":"Außerdem verbessert Lob die Atmosphäre im Team, weil sich die Leute gegenseitig wertschätzen.","fa":"علاوه بر این، تعریف فضای تیم را بهتر می‌کند، چون افراد قدر یکدیگر را می‌دانند."},{"de":"Nun aber zu den Nachteilen, die oft übersehen werden.","fa":"اما حالا درباره‌ی معایبی که اغلب نادیده گرفته می‌شوند."},{"de":"Wer ständig und für jede Kleinigkeit gelobt wird, nimmt das Lob irgendwann nicht mehr ernst.","fa":"کسی که مدام و برای هر چیز کوچکی از او تعریف شود، بالاخره روزی تعریف را دیگر جدی نمی‌گیرد."},{"de":"Übertriebenes Lob wirkt außerdem schnell unglaubwürdig oder sogar manipulierend.","fa":"علاوه بر این، تعریفِ اغراق‌آمیز زود غیرقابل‌باور یا حتی فریبکارانه به نظر می‌رسد."},{"de":"Ein weiteres Problem ist das sogenannte Personenlob, also Sätze wie „Du bist so intelligent“.","fa":"مشکل دیگر به اصطلاح «تعریف از شخص» است، یعنی جمله‌هایی مثل «تو خیلی باهوشی»."},{"de":"Eine bekannte Studie mit Schulkindern hat gezeigt, dass solche Kinder später schwierige Aufgaben eher vermeiden.","fa":"یک پژوهش معروف با دانش‌آموزان نشان داده است که چنین کودکانی بعدها بیشتر از کارهای دشوار دوری می‌کنند."},{"de":"Sie haben nämlich Angst, ihr Bild als kluges Kind zu verlieren.","fa":"چون می‌ترسند تصویرشان به‌عنوان بچه‌ی باهوش از بین برود."},{"de":"Kinder, die für ihre Anstrengung gelobt wurden, wählten dagegen häufiger die schwierigere Aufgabe.","fa":"در مقابل، کودکانی که برای تلاششان تشویق شده بودند، بیشتر تمرین دشوارتر را انتخاب کردند."},{"de":"Was bedeutet das für unseren Alltag?","fa":"این برای زندگی روزمره‌ی ما چه معنایی دارد؟"},{"de":"Ein gutes Lob ist konkret: Statt „Super gemacht“ sagt man besser, was genau gut war.","fa":"یک تعریف خوب مشخص است: به جای «عالی بود» بهتر است بگوییم دقیقاً چه چیزی خوب بود."},{"de":"Es sollte zeitnah kommen, also nicht erst Wochen später im Jahresgespräch.","fa":"تعریف باید به‌موقع باشد، یعنی نه چند هفته بعد در جلسه‌ی ارزیابی سالانه."},{"de":"Und es sollte ehrlich gemeint sein, denn falsches Lob ist leicht zu erkennen.","fa":"و باید صادقانه باشد، چون تعریف دروغین به‌راحتی قابل‌تشخیص است."},{"de":"Wichtig ist auch, Lob und Kritik nicht in einem einzigen Satz zu verbinden, weil sich der Zuhörer meist nur die Kritik merkt.","fa":"این هم مهم است که تعریف و انتقاد را در یک جمله با هم نیاوریم، چون شنونده معمولاً فقط انتقاد را به خاطر می‌سپارد."},{"de":"Meiner Meinung nach ist Lob also ein wertvolles Werkzeug, wenn man es bewusst und sparsam einsetzt.","fa":"به نظر من، پس تعریف ابزار ارزشمندی است، به شرط اینکه آگاهانه و با صرفه‌جویی از آن استفاده کنیم."},{"de":"Vielen Dank für Ihre Aufmerksamkeit, und jetzt freue ich mich auf Ihre Fragen.","fa":"از توجه شما بسیار سپاسگزارم و حالا با کمال میل منتظر پرسش‌هایتان هستم."}],"q":[{"q":"Welcher Vorteil von Lob wird genannt?","opts":["Es ersetzt eine Gehaltserhöhung.","Es stärkt das Selbstvertrauen.","Es macht Kritik überflüssig."],"a":1,"fa":"سخنران می‌گوید تعریف صادقانه اعتماد به نفس را تقویت می‌کند."},{"q":"Was passiert, wenn man für jede Kleinigkeit gelobt wird?","opts":["Man arbeitet doppelt so viel.","Man nimmt das Lob nicht mehr ernst.","Man wird schneller befördert."],"a":1,"fa":"به گفته‌ی سخنران، کسی که برای هر چیز کوچکی تشویق شود، دیگر تعریف را جدی نمی‌گیرد."},{"q":"Wie verhielten sich Kinder, die für ihre Intelligenz gelobt wurden?","opts":["Sie fragten öfter nach Hilfe.","Sie wählten häufiger schwierige Aufgaben.","Sie vermieden eher schwierige Aufgaben."],"a":2,"fa":"طبق پژوهش، این کودکان بیشتر از کارهای دشوار دوری می‌کردند، چون می‌ترسیدند تصویر باهوش بودنشان از بین برود."},{"q":"Wofür sollte man Kinder laut der Studie eher loben?","opts":["für ihre Intelligenz","für ihre Anstrengung","für ihr Aussehen"],"a":1,"fa":"کودکانی که برای تلاششان تشویق شده بودند، بیشتر تمرین دشوارتر را انتخاب کردند."},{"q":"Wann sollte ein Lob kommen?","opts":["erst im Jahresgespräch","nur am Ende eines Projekts","möglichst zeitnah"],"a":2,"fa":"سخنران می‌گوید تعریف باید به‌موقع باشد، نه چند هفته بعد در جلسه‌ی سالانه."},{"q":"Warum soll man Lob und Kritik nicht in einem Satz verbinden?","opts":["Weil das unhöflich ist.","Weil man sich meist nur die Kritik merkt.","Weil es zu lange dauert."],"a":1,"fa":"دلیلش این است که شنونده معمولاً فقط انتقاد را به خاطر می‌سپارد."}]},{"id":"h3","type":"Podcast-Folge","title":"Mein bester und mein schlechtester Chef","title_fa":"بهترین و بدترین رئیسم","intro_fa":"مارکوس در پادکستی درباره‌ی دنیای کار از تجربه‌هایش با دو رئیس کاملاً متفاوت تعریف می‌کند.","s":[{"de":"Hallo und herzlich willkommen zu einer neuen Folge von „Job und Leben“, dem Podcast rund um die Arbeitswelt.","fa":"سلام و به قسمت تازه‌ای از «کار و زندگی»، پادکستی درباره‌ی دنیای کار، خوش آمدید."},{"de":"Ich bin Markus, und heute erzähle ich euch von dem besten und dem schlechtesten Chef, die ich je hatte.","fa":"من مارکوس هستم و امروز از بهترین و بدترین رئیسی که تا حالا داشته‌ام برایتان تعریف می‌کنم."},{"de":"Mein erster Chef leitete eine kleine Werbeagentur in Köln.","fa":"رئیس اولم یک آژانس تبلیغاتی کوچک را در کلن اداره می‌کرد."},{"de":"Er war ein brillanter Kopf, aber leider auch ein Mensch, der seine Mitarbeiter gern vor allen anderen niedermachte.","fa":"او آدم فوق‌العاده باهوشی بود، اما متأسفانه کسی هم بود که دوست داشت کارمندانش را جلوی بقیه خرد کند."},{"de":"Wenn ein Entwurf nicht seinen Vorstellungen entsprach, wurde er laut, und zwar mitten in der Teamsitzung.","fa":"اگر طرحی مطابق انتظارش نبود، صدایش را بلند می‌کرد، آن هم وسط جلسه‌ی تیم."},{"de":"Wir standen ständig unter Druck, und innerhalb eines Jahres haben vier von zehn Kollegen gekündigt.","fa":"ما همیشه زیر فشار بودیم و ظرف یک سال، چهار نفر از ده همکار استعفا دادند."},{"de":"Auch ich habe nach achtzehn Monaten aufgegeben und die Agentur verlassen.","fa":"من هم بعد از هجده ماه کنار کشیدم و آژانس را ترک کردم."},{"de":"Meine zweite Chefin, Frau Berger, war das komplette Gegenteil.","fa":"رئیس دومم، خانم برگر، کاملاً برعکس بود."},{"de":"Sie hat sich jeden Montag zehn Minuten Zeit für jeden im Team genommen, um zu hören, woran wir gerade arbeiten.","fa":"او هر دوشنبه برای هر کدام از اعضای تیم ده دقیقه وقت می‌گذاشت تا بشنود که روی چه چیزی کار می‌کنیم."},{"de":"Kritik hat sie immer unter vier Augen geäußert, und zwar sachlich und mit konkreten Vorschlägen.","fa":"انتقادش را همیشه در خلوت و دونفره مطرح می‌کرد، آن هم منطقی و با پیشنهادهای مشخص."},{"de":"Gleichzeitig hat sie uns viel Freiheit gegeben und uns zugetraut, Entscheidungen selbst zu treffen.","fa":"در عین حال آزادی زیادی به ما می‌داد و به ما اعتماد داشت که خودمان تصمیم بگیریم."},{"de":"Ich erinnere mich noch gut an ein schwieriges Projekt, bei dem ich mich ziemlich herausgefordert fühlte.","fa":"هنوز پروژه‌ی سختی را خوب به یاد دارم که در آن حسابی احساس می‌کردم با چالش روبه‌رو هستم."},{"de":"Statt mir die Aufgabe wegzunehmen, hat sie mich ermutigt und mir eine erfahrene Kollegin zur Seite gestellt.","fa":"به جای اینکه کار را از من بگیرد، تشویقم کرد و یک همکار باتجربه را کنارم گذاشت."},{"de":"Am Ende war das Projekt ein großer Erfolg, und ich war unglaublich stolz.","fa":"در پایان، پروژه موفقیت بزرگی بود و من به‌شدت احساس غرور می‌کردم."},{"de":"Für mich war sie wie ein Fels in der Brandung, besonders in stressigen Phasen.","fa":"برای من او مثل کوهی استوار بود، به‌خصوص در دوره‌های پراسترس."},{"de":"Interessanterweise passt meine Erfahrung genau zu einer aktuellen Umfrage eines Karriereportals.","fa":"جالب اینکه تجربه‌ی من دقیقاً با نظرسنجی تازه‌ی یک سایت کاریابی جور درمی‌آید."},{"de":"Danach wünschen sich die meisten Beschäftigten von ihrer Führungskraft vor allem Fairness und Ehrlichkeit.","fa":"طبق آن، بیشتر شاغلان از مدیرشان بیش از همه انصاف و صداقت می‌خواهند."},{"de":"Fachliche Kompetenz ist zwar auch wichtig, landet aber erst auf Platz vier.","fa":"صلاحیت تخصصی هم البته مهم است، اما تازه در رتبه‌ی چهارم قرار می‌گیرد."},{"de":"Ein bekanntes Zitat sagt: Menschen verlassen nicht ihre Firma, sondern ihren Chef.","fa":"یک جمله‌ی معروف می‌گوید: آدم‌ها شرکتشان را ترک نمی‌کنند، بلکه رئیسشان را."},{"de":"Nach meinen Erfahrungen ist da wirklich etwas dran.","fa":"بر اساس تجربه‌های من، واقعاً حقیقتی در این حرف هست."},{"de":"Jetzt seid ihr dran: Schreibt mir in die Kommentare, was für euch einen guten Chef oder eine gute Chefin ausmacht!","fa":"حالا نوبت شماست: در کامنت‌ها برایم بنویسید که از نظر شما یک رئیس خوب چه ویژگی‌هایی دارد!"},{"de":"Bis zur nächsten Folge!","fa":"تا قسمت بعد!"}],"q":[{"q":"Wo arbeitete Markus bei seinem ersten Chef?","opts":["in einem Krankenhaus","in einer Bank","in einer Werbeagentur"],"a":2,"fa":"مارکوس می‌گوید رئیس اولش یک آژانس تبلیغاتی کوچک را در کلن اداره می‌کرد."},{"q":"Was war das Problem mit dem ersten Chef?","opts":["Er war fachlich schwach.","Er war selten im Büro.","Er machte Mitarbeiter vor anderen schlecht."],"a":2,"fa":"او باهوش بود، اما کارمندانش را جلوی بقیه، حتی وسط جلسه‌ی تیم، خرد می‌کرد."},{"q":"Wie lange blieb Markus in der Agentur?","opts":["achtzehn Monate","vier Jahre","ein Jahr"],"a":0,"fa":"مارکوس می‌گوید بعد از هجده ماه کنار کشید و آژانس را ترک کرد."},{"q":"Wie äußerte Frau Berger Kritik?","opts":["unter vier Augen und sachlich","per E-Mail an das ganze Team","gar nicht"],"a":0,"fa":"خانم برگر انتقادش را همیشه دونفره، منطقی و با پیشنهادهای مشخص مطرح می‌کرد."},{"q":"Was tat Frau Berger bei dem schwierigen Projekt?","opts":["Sie ermutigte Markus und stellte ihm eine Kollegin zur Seite.","Sie übernahm das Projekt selbst.","Sie gab die Aufgabe einem anderen Kollegen."],"a":0,"fa":"به جای گرفتن کار از مارکوس، او را تشویق کرد و یک همکار باتجربه کنارش گذاشت."},{"q":"Was wünschen sich Beschäftigte laut der Umfrage am meisten?","opts":["mehr Homeoffice","Fairness und Ehrlichkeit","fachliche Kompetenz"],"a":1,"fa":"طبق نظرسنجی، بیشتر شاغلان انصاف و صداقت می‌خواهند؛ صلاحیت تخصصی در رتبه‌ی چهارم است."}]}]};
